; GFA3BLIB  -  the GFA-BASIC runtime library 3.03 E
;
; Devpac source of the library, disassembled by Darren Birks, 4 November 2026.  Assembled as a plain
; binary it gives the library file byte for byte:
;
;     vasmm68k_mot -devpac -m68000 -Fbin -o GFA3BLIB GFA3BLIB.S
;
; The library is an archive of DRI object modules: $ff65, then each module as a 28-byte entry (its name
; and length) and its object file (header, code, symbol table, a relocation word for every code word).
; References to other modules are left as data words, filled in by the linker, with the symbol named.

	dc.w	$ff65				; library archive

;==============================================================================
; Module 00000000.O: 0 bytes of code, 0 of data, 0 of bss; exports BaseA4, A0000000
;==============================================================================
	dc.b	$30,$30,$30,$30,$30,$30,$30,$30,$2e,$4f,$00,$00,$00,$00	; library entry: the name 00000000.O
	dc.w	$b32b,$12a2,$0000,$01b6,$0000,$0038,$0000	; entry: the rest (the member's length at +8)
	dc.w	$601a				; DRI object module
	dc.l	$0,$0,$0,$1c		; text, data and bss lengths, symbol table length
	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_00000000:
; symbol table: name, type, value
	dc.b	$42,$61,$73,$65,$41,$34,$00,$00		; BaseA4
	dc.w	$a200				; defined global text
	dc.l	$0
	dc.b	$41,$30,$30,$30,$30,$30,$30,$30		; A0000000
	dc.w	$a200				; defined global text
	dc.l	$0
; relocation words, one a code word: 0 none, 1 data, 2 text, 3 bss, 4 external, 5 a long (its low
; word tells), 6 external pc-relative, 7 the first word of an instruction; an external's symbol
