	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_eqeq:
;------------------------------------------------------------------------------
; == (approximate equality) of two floats in memory.
; Entry: a1 -> right float, a0 -> left float
; Exit: d0.l = -1 if about equal, else 0; a0, a1 advanced by 6
;------------------------------------------------------------------------------
VVFEQEQ:
	move.l	(a1)+,d0                        ; right operand from (a1)
	move.w	(a1)+,d1                        ; low mantissa word
	move.w	(a1)+,d2                        ; exponent word

;------------------------------------------------------------------------------
; == with the left operand in memory.
; Entry: a0 -> left float, d0-d2 = right float
; Exit: d0.l = -1 if about equal, else 0; a0 advanced by 6
;------------------------------------------------------------------------------
VFEQEQ:
	move.l	(a0)+,d3                        ; left operand from (a0)
	move.w	(a0)+,d4                        ; low mantissa word
	move.w	(a0)+,d5                        ; exponent word

;------------------------------------------------------------------------------
; x == y: approximate float equality. Both mantissas are rounded at bit 3 and
; only their top 28 bits are compared; the low word is ignored. Numbers whose
; exponent magnitude is below 8 count as zero.
; Entry: d3-d5 = left, d0-d2 = right
; Exit: d0.l = -1 if about equal, else 0; d3-d5 changed
;------------------------------------------------------------------------------
FEQEQ:
	addq.l	#8,d0                           ; round the right mantissa at bit 3
	bcc.s	.round_left                     ; no carry out: done
	roxr.l	#1,d0                           ; carry: shift it back down
	addq.w	#1,d2                           ; and raise the exponent
.round_left:
	addq.l	#8,d3                           ; round the left mantissa at bit 3
	bcc.s	.test_left_tiny                 ; no carry out: done
	roxr.l	#1,d3                           ; carry: shift it back down
	addq.w	#1,d5                           ; and raise the exponent
.test_left_tiny:
	cmpi.w	#$8,d5                          ; left exponent 0-7: left counts as zero
	bcs.s	.left_tiny
	cmpi.w	#$fff8,d5                       ; left exponent -1..-7: also zero
	bhi.s	.left_tiny
	cmp.w	d2,d5                           ; exponents (and signs) must match
	bne.s	.false
	eor.l	d3,d0                           ; bits that differ in the high mantissa longs
	lsr.l	#4,d0                           ; ignore the low 4 bits
	bne.s	.false                          ; the top 28 bits differ: not equal
.true:
	moveq	#-1,d0                          ; true
	rts
.left_tiny:
	cmpi.w	#$8,d2                          ; left is zero: true if right is too
	bcs.s	.true
	cmpi.w	#$fff8,d2
	bhi.s	.true
.false:
	moveq	#0,d0                           ; false
	rts

; symbol table: name, type, value
	dc.b	$56,$56,$46,$45,$51,$45,$51,$00		; VVFEQEQ
	dc.w	$a200				; defined global text
	dc.l	$0
	dc.b	$56,$46,$45,$51,$45,$51,$00,$00		; VFEQEQ
	dc.w	$a200				; defined global text
	dc.l	$6
	dc.b	$46,$45,$51,$45,$51,$00,$00,$00		; FEQEQ
	dc.w	$a200				; defined global text
	dc.l	$c
