m_ge:
;------------------------------------------------------------------------------
; Floating point compare, both operands in memory: (a0) < (a1).
; Entry: a0 -> left float, a1 -> right float
; Exit: d0.l = -1 if (a0) < (a1), else 0
;------------------------------------------------------------------------------
float_less_stored_pair:
	move.l	(a1)+,d0                        ; right operand from (a1)
	move.w	(a1)+,d1                        ; low mantissa word
	move.w	(a1)+,d2                        ; exponent word

;------------------------------------------------------------------------------
; Floating point compare with the left operand in memory: (a0) < d0-d2.
; Entry: a0 -> left float, d0-d2 = right float
; Exit: d0.l = -1 if (a0) < d0-d2, else 0
;------------------------------------------------------------------------------
float_less_stored:
	move.l	(a0)+,d3                        ; left operand from (a0)
	move.w	(a0)+,d4                        ; low mantissa word
	move.w	(a0)+,d5                        ; exponent word

;------------------------------------------------------------------------------
; Floating point compare, left < right.
; Entry: d3-d5 = left operand, d0-d2 = right operand (float format as float_greater)
; Exit: d0.l = -1 if left < right, else 0
; float_less_stored and float_less_stored_pair before it load the operands from memory.
;------------------------------------------------------------------------------
float_less:
	cmp.w	d2,d5                           ; signed exponents order the numbers when they differ
	beq.s	.same_exponent
	blt.s	.true                           ; left exponent lower: left is smaller
.false:
	moveq	#0,d0                           ; false
	rts
.same_exponent:
	move.w	d2,d6                           ; same sign and exponent: compare mantissas
	bgt.s	.compare_positive               ; positive
	beq.s	.false                          ; both zero: equal
	cmp.l	d3,d0                           ; negative: the larger mantissa is the smaller number
	bne.s	.test_result                    ; high longs differ: decided
	cmp.w	d4,d1                           ; high longs equal: low words
	bcc.s	.false                          ; left mantissa not above: not less
	moveq	#-1,d0                          ; true
	rts
.compare_positive:
	cmp.l	d0,d3                           ; positive: compare mantissas unsigned
	bne.s	.test_result
	cmp.w	d1,d4                           ; high longs equal: compare the low words
.test_result:
	bcc.s	.false
.true:
	moveq	#-1,d0                          ; true
	rts

