m_exist:
;------------------------------------------------------------------------------
; EXIST(name$): tests whether a file exists (Fsfirst with every attribute except volume label and directory).
; Entry: a0 -> string descriptor of the file name
; Exit: d0.l = -1 if found, else 0
;------------------------------------------------------------------------------
file_exists:
	moveq	#-25,d0                         ; attributes $ffe7: all but volume label and directory
	bsr.s	find_first_file
	tst.l	d0
	bmi.s	.not_found                      ; negative GEMDOS error: no such file
	moveq	#-1,d0                          ; found
	rts
.not_found:
	moveq	#0,d0
	rts

;------------------------------------------------------------------------------
; Fsfirst on a BASIC string: the string is zero-terminated in place for the call and the byte after it restored.
; Entry: a0 -> string descriptor of the file name, d0.w = attributes
; Exit: d0.l = GEMDOS result
;------------------------------------------------------------------------------
find_first_file:
	dc.w	$6100,$0000                     ; bsr.w find_first_file+2 -> XStr0Kil (filled in by the linker), a1 ->
                                                ;   text, d1 = length
	lea	0(a1,d1.w),a0                   ; a0 -> byte after the text
	move.b	(a0),-(sp)                      ; keep that byte
	pea	(a0)                            ; address of the byte for the restore
	clr.b	(a0)                            ; terminate the name
	move.w	d0,-(sp)                        ; attributes
	pea	(a1)                            ; file name
