	cmpi.l	#$ffff,d0                       ; more than 16 bits?
	bhi.s	.negative_long
	move.w	#$40d,d2                        ; exponent for a 16-bit value
	tst.w	d0                              ; top bit already set?
	bmi.s	.negative_word_top_set
.negative_word_loop:
	add.w	d0,d0                           ; shift until the top bit is set
	dbmi	d2,.negative_word_loop
	swap	d0                              ; mantissa into the high word
	neg.w	d2                              ; negative exponent marks a negative number
	rts
.negative_word_top_set:
	swap	d0                              ; mantissa into the high word
	addq.w	#1,d2                           ; one exponent more
	neg.w	d2                              ; negative
	rts
.negative_long:
	move.w	#$41d,d2                        ; exponent for a 32-bit value
.negative_long_loop:
	add.l	d0,d0                           ; shift until the top bit is set
	dbmi	d2,.negative_long_loop
	neg.w	d2                              ; negative
