;------------------------------------------------------------------------------
long_multiply:
	tst.l	d1                              ; make the multiplier positive
	bpl.s	.multiplier_positive            ; multiplier positive
	neg.l	d1                              ; and move its sign to the multiplicand
	neg.l	d0
	bpl.s	unsigned_multiply               ; multiplicand now positive: plain multiply
.negative_result:
	neg.l	d0                              ; multiply the magnitudes and negate
	bsr.s	unsigned_multiply               ; magnitudes multiplied
	neg.l	d0                              ; and negated
	rts
.multiplier_positive:
	tst.l	d0                              ; multiplicand negative?
	bmi.s	.negative_result                ; multiplicand negative: negate around it

;------------------------------------------------------------------------------
; Unsigned 32 x 32 multiply, low 32 bits of the result.
; Entry: d0.l, d1.l = factors
; Exit: d0.l = product
