	cmpi.l	#$10000,d0                      ; both fit in 16 bits?
	bcc.s	.long_multiply                  ; d0 too big: long multiply
.short_multiply:
	mulu.w	d1,d0                           ; one mulu does it
	rts
.swap_check:
	cmpi.l	#$10000,d1                      ; d1 within 16 bits?
	bcs.s	.short_multiply                 ; d1 is the bigger one: is d0 within 16 bits?
	exg	d1,d0                           ; make d1 the 16-bit factor
.long_multiply:
	move.l	d0,d2                           ; low * low plus (high * low) << 16
	mulu.w	d1,d0                           ; low word of d0 times d1
	swap	d2                              ; high word of d0
	mulu.w	d1,d2                           ; times d1
	swap	d2                              ; shifted up 16 bits
	clr.w	d2                              ; low half of it cleared
	add.l	d2,d0                           ; added to the low product
	rts

