	ble.s	multiply_sign_operand           ; operand zero or negative
	ext.l	d2                              ; accumulator zero or negative
	ble.s	multiply_sign_accumulator       ; accumulator zero or negative

;------------------------------------------------------------------------------
; Multiplies two positive floats, skipping partial products of zero words.
; Entry: d0-d2, d3-d5 = positive floats
; Exit: d0-d2 = product
;------------------------------------------------------------------------------
multiply_magnitudes:
	add.w	d5,d2                           ; add the exponents
	subi.w	#$3fe,d2                        ; remove one bias (and one for the mantissa position)
	tst.w	d1                              ; accumulator low word zero?
