	moveq	#0,d6                           ; carry source
	swap	d3                              ; op high word
	mulu.w	d3,d1                           ; op high * acc low
	add.l	d5,d1                           ; 2^-32 terms summed
	swap	d0                              ; acc high
	move.w	d3,d5                           ; op high
	mulu.w	d0,d5                           ; acc high * op high (top term)
	addx.l	d6,d5                           ; plus the carry
	move.w	d3,d6                           ; op high
	swap	d3                              ; op mid
	move.w	d0,d7                           ; acc high
	swap	d0                              ; acc mid
	mulu.w	d6,d0                           ; acc mid * op high
	mulu.w	d7,d3                           ; op mid * acc high
	add.l	d3,d0                           ; 2^-16 terms summed
	bcc.w	normalize_product               ; no carry: normalize
	addi.l	#$10000,d5                      ; carry into the top term
	bra.s	normalize_product               ; normalize the sum
.operand_mid_zero:
	swap	d3                              ; operand mid word zero
	mulu.w	d3,d1                           ; op high * acc low
	swap	d0                              ; acc high
	move.w	d3,d5                           ; op high
	mulu.w	d0,d5                           ; acc high * op high
	swap	d0                              ; acc mid
	mulu.w	d3,d0                           ; acc mid * op high
	bra.s	normalize_product               ; normalize the sum
.operand_sign:
	beq.s	.zero                           ; sign handling for the unlabelled entry just before
                                                ;   multiply_full_precision
