;------------------------------------------------------------------------------
; Converts a long to a float and divides it by a short float constant.
; Entry: d0.l = integer, d3.l/d5.w = constant (low word taken as 0)
; Exit: d0-d2 = quotient
;------------------------------------------------------------------------------
long_divide_constant:
	moveq	#0,d4                           ; constant has no low mantissa word

;------------------------------------------------------------------------------
; Converts a long to a float and divides it by a float.
; Entry: d0.l = integer, d3-d5 = divisor
; Exit: d0-d2 = quotient
;------------------------------------------------------------------------------
