; Divides a float in memory by the accumulator and stores the quotient there.
; Entry: a0 -> float (6 bytes), d0-d2 = divisor
; Exit: d0-d2 = (a0) / d0-d2, also stored at (a0); a0 unchanged
;------------------------------------------------------------------------------
divide_float_in_place:
	bsr.s	divide_stored_float             ; (a0) / d0-d2, a0 past it
	move.w	d2,-(a0)                        ; store the quotient back
	move.w	d1,-(a0)                        ; low mantissa word
	move.l	d0,-(a0)                        ; mantissa high long
	rts

