	move.w	(a0)+,d1                        ; low mantissa word
	move.w	(a0)+,d2                        ; exponent word
	move.l	(a1)+,d3                        ; divisor from (a1)
	move.w	(a1)+,d4                        ; low mantissa word
	move.w	(a1)+,d5                        ; exponent word
	bra.s	float_divide_accumulator        ; divide

;------------------------------------------------------------------------------
; Divides two floats in memory: (a1) / (a0).
; Entry: a0 -> divisor, a1 -> dividend
; Exit: d0-d2 = quotient
;------------------------------------------------------------------------------
