	move.w	d0,$694(a6)                     ; for the user VDI block
	move.w	d0,$618(a6)                     ; for the graphics commands
	lea	$fa0(a6),a0                     ; work_out
	lea	$129c(a6),a1                    ; kept copy of work_out
	moveq	#44,d0                          ; 45 words
.copy_work_out:
