	move.l	a6,d1                           ; runtime block base
	lea	aes_param_block(pc),a0          ; first parameter block
.relocate:
	add.l	d1,(a0)+                        ; offset into an address
	dbra	d0,.relocate                    ; next
	rts                                     ; done

