	move.l	a0,d0                           ; into d0
	rts                                     ; done

; The program's AES parameter block: offsets into the runtime block of
; control, global, intin, intout, addrin and addrout, made addresses at
; the start. The program's VDI block (contrl, intin, ptsin, intout,
; ptsout) follows at +$18.
aes_param_block:
