;------------------------------------------------------------------------------
conterm_shift_on:
	pea	conterm_set_super(pc)           ; routine to run
	bra.s	initaes_supexec                 ; run it in supervisor mode

;------------------------------------------------------------------------------
; Clears conterm bit 3 again if conterm_shift_on set it.
;------------------------------------------------------------------------------
conterm_restore:
	jsr	initaes_hook-m_initaes          ; hook, an rts here
	pea	conterm_restore_super(pc)       ; routine to run

initaes_supexec:
	move.w	#$26,-(sp)                      ; Supexec
	trap	#14                             ; Supexec, Supexec
	addq.l	#6,sp                           ; drop the arguments
	rts                                     ; done

conterm_restore_super:
	move.b	$0,d0                           ; set when the bit was clear before
	beq.s	.done                           ; no: leave it
	bclr	#$3,$484.w                      ; conterm, shift state off again
.done:
	rts                                     ; done

conterm_set_super:
	bset	#$3,$484.w                      ; conterm, shift state with each key
	seq	$0                              ; remember whether it was clear

initaes_hook:
	rts                                     ; empty hook (and the end of conterm_set_super)

;------------------------------------------------------------------------------
; RUN: clears the variables, closes the windows, resets the graphics
; state and the window table, empties the stack and starts the program
; again at basepage + $10e, after its call to INIT.
;------------------------------------------------------------------------------
RUN:
	dc.w	$6100,$0000                     ; bsr.w	RUN+2 -> CLEAR (filled in by the linker), clear the variables
	bsr.s	m_initaes+$302                  ; close all windows

