	dc.w	$6100,$0000                     ; bsr.w run_call_graphini+2 -> GRAPHINI (filled in by the linker),
                                                ;   graphics defaults
	bsr.s	m_initaes+$2fe                  ; reset the window table
	lea	$3a84(a6),sp                    ; fresh stack
	movea.l	$2a(a6),a0                      ; basepage
	jmp	$10e(a0)                        ; program start after its call to INIT

