	bsr.s	close_channel                   ; close it
	move.w	(sp)+,d0
	dbra	d0,.next_channel                ; down to channel 0
	rts

;------------------------------------------------------------------------------
; CLOSE #n: frees a channel, flushes and closes its file and frees its random-access field buffer.
; Entry: d0.w = channel
;------------------------------------------------------------------------------
close_channel:
