	cmp.w	d1,d0
	bcc.s	close_return                    ; out of range: nothing to do
	lea	$1f2(a6),a0                     ; channel table: one handle byte each
	adda.w	d0,a0
	move.b	(a0),d1                         ; handle or device code
	beq.s	close_return                    ; not open
	clr.b	(a0)                            ; free the channel
	move.b	$64(a0),-(sp)                   ; its field buffer number
	clr.b	$64(a0)                         ; free that too
	ext.w	d1
	cmpi.w	#$1,d1                          ; standard handles 0 and 1 are not closed
	bls.s	close_channel_free_field
	move.w	d1,d6                           ; handle for FClose

