	beq.s	close_return                    ; none
	asl.w	#3,d2                           ; 8 bytes per field buffer
	lea	$2bc(a6),a0                     ; field buffer table
	adda.w	d2,a0
	moveq	#0,d0                           ; length 0: free the string

close_call_screat:
	dc.w	$6000,$0000                     ; bra.w close_call_screat+2 -> Screat (filled in by the linker), free
                                                ;   the field buffer

