;------------------------------------------------------------------------------
; Gives a newly opened handle its buffer: a 4106-byte string (10-byte header and 4096 bytes of data) in the file buffer
; table entry for the handle. The header holds the buffer position and count, the mode and the file position.
; Entry: d0.w = handle or device code, d5.w = mode (1 read, 2 write, 3 both), d7.l = file position
; Exit: d0 = 0
;------------------------------------------------------------------------------
open_channel_buffer:
	lea	$1f2(a6),a1
	mulu.w	#$6,d0                          ; 6 bytes per handle
	lea	$3bc(a6),a0                     ; file buffer table: 6 bytes per handle
	adda.w	d0,a0
	move.w	#$100a,d0                       ; buffer size 4106 bytes
	clr.w	4(a0)                           ; no buffer yet

open_call_screat_buffer:
	dc.w	$6100,$0000                     ; bsr.w open_call_screat_buffer+2 -> Screat (filled in by the linker),
                                                ;   allocate it as a string
	clr.l	(a1)+                           ; position and count 0
	move.w	d5,(a1)+                        ; mode
	move.l	d7,(a1)+                        ; file position
	moveq	#0,d0
	rts

;------------------------------------------------------------------------------
; Copies a file name (at most 254 characters) into the text buffer, zero-terminated.
; Exit: a0 -> text buffer, d0 = 1
;------------------------------------------------------------------------------
open_file_name:
	movea.l	(sp)+,a2                        ; handle byte address back
	lea	$46(a6),a0                      ; text buffer
	cmpi.w	#$fe,d7                         ; at most 254 characters
	bcs.s	.next
	move.w	#$fe,d7
.copy:
	move.b	(a1)+,(a0)+                     ; copy the name
.next:
	dbra	d7,.copy
	clr.b	(a0)+                           ; terminate it
	lea	$46(a6),a0                      ; a0 -> name
	moveq	#1,d0                           ; a file

open_return:
	rts

;------------------------------------------------------------------------------
; OPEN "I",#n,name$: opens a file for reading (Fopen mode 0) or attaches a device.
; Entry: d1.w = channel, a0 -> name descriptor; GEMDOS errors are raised as runtime errors
;------------------------------------------------------------------------------
open_input:
	bsr.w	open_check_name                 ; device or name
	beq.s	open_return                     ; device: done
	moveq	#1,d5                           ; mode 1: read
	moveq	#61,d0                          ; Fopen
	bra.s	open_call_mode_zero             ; with mode 0

;------------------------------------------------------------------------------
; OPEN "O",#n,name$: creates a file for writing (Fcreate) or attaches a device.
; Entry: d1.w = channel, a0 -> name descriptor
;------------------------------------------------------------------------------
open_output:
	bsr.w	open_check_name
	beq.s	open_return                     ; device: done
	moveq	#2,d5                           ; mode 2: write
	moveq	#60,d0                          ; Fcreate

;------------------------------------------------------------------------------
; Opens through GEMDOS with mode or attribute 0 on the stack, then enters the handle for the channel.
; Entry: d0.w = GEMDOS function, a0 -> file name, a2 -> handle byte
;------------------------------------------------------------------------------
open_call_mode_zero:
	clr.w	-(sp)                           ; mode or attribute 0

;------------------------------------------------------------------------------
; Calls the GEMDOS open or create function with the mode already on the stack and enters the handle for the channel; a
; GEMDOS error is a runtime error.
; Entry: d0.w = function, a0 -> file name, a2 -> handle byte, mode word on the stack
;------------------------------------------------------------------------------
open_call_gemdos:
	pea	(a0)                            ; file name
	move.w	d0,-(sp)                        ; function
	move.l	a2,d6                           ; keep a2 across the call
	trap	#1                              ; GEMDOS
	movea.l	d6,a2
	addq.l	#8,sp                           ; drop the arguments
	tst.w	d0
	bmi.w	open_gemdos_error               ; negative: GEMDOS error
	bra.s	open_set_channel                ; enter the handle

;------------------------------------------------------------------------------
; OPEN "U",#n,name$: opens a file for reading and writing (Fopen mode 2).
;------------------------------------------------------------------------------
open_update:
	bsr.w	open_check_name
	beq.s	open_return                     ; device: done
	moveq	#3,d5                           ; mode 3: read and write
	move.w	#$2,-(sp)                       ; Fopen mode 2
	moveq	#61,d0                          ; Fopen
	bra.s	open_call_gemdos                ; open it

;------------------------------------------------------------------------------
; OPEN "A",#n,name$: opens a file read/write and positions at its end.
;------------------------------------------------------------------------------
open_append:
	bsr.w	open_check_name
	beq.s	open_return                     ; device: done
	moveq	#3,d5                           ; mode 3: read and write
	moveq	#61,d0                          ; Fopen
	move.w	#$2,-(sp)                       ; mode 2
	pea	(a0)
	move.w	d0,-(sp)
	move.l	a2,d6                           ; keep a2 across the call
	trap	#1                              ; GEMDOS
	movea.l	d6,a2
	addq.l	#8,sp
	move.w	d0,d6                           ; d6 = handle
	bmi.w	open_gemdos_error
	move.b	d0,(a2)                         ; into the channel table
	move.w	#$2,-(sp)                       ; mode 2: from the end
	move.w	d0,-(sp)                        ; handle
	clr.l	-(sp)                           ; offset 0
	move.w	#$42,-(sp)                      ; Fseek
	trap	#1                              ; Fseek
	lea	$a(sp),sp                       ; drop the arguments
	move.l	d0,d7                           ; d7 = file length, the position
	bmi.s	open_gemdos_error
	move.w	d6,d0                           ; handle
	bra.w	open_channel_buffer             ; give it its buffer

open_drop_length:
	addq.l	#2,sp                           ; drop the record length
	rts

;------------------------------------------------------------------------------
; OPEN "R",#n,name$,len: opens or creates a file for random access and gives it a free field buffer.
; Entry: d0.w = record length, d1.w = channel, a0 -> name descriptor
; Raises error 48 for a bad length, 49 when no field buffer is free.
;------------------------------------------------------------------------------
open_random:
	move.w	d0,-(sp)                        ; keep the record length
	bsr.w	open_check_name                 ; device or name
	beq.s	open_drop_length                ; device: done
	moveq	#3,d5                           ; mode 3: read and write
	pea	(a0)                            ; keep the name
	move.w	#$2,-(sp)                       ; Fopen mode 2
	pea	(a0)
	move.w	#$3d,-(sp)                      ; Fopen
	move.l	a2,d6                           ; keep a2
	trap	#1                              ; GEMDOS
	addq.l	#8,sp                           ; drop the arguments
	tst.l	d0
	bpl.s	.opened                         ; opened
	movea.l	(sp),a0                         ; no such file: create it
	clr.w	-(sp)                           ; attribute 0
	pea	(a0)
	move.w	#$3c,-(sp)                      ; Fcreate
	trap	#1                              ; Fcreate
	addq.l	#8,sp                           ; drop the arguments
.opened:
	movea.l	d6,a2                           ; a2 back
	addq.l	#4,sp                           ; drop the name
	tst.l	d0
	bmi.s	open_gemdos_error               ; GEMDOS error
	move.b	d0,(a2)                         ; into the channel table
	ext.w	d0                              ; handle
	moveq	#0,d7                           ; position 0
	pea	$64(a2)                         ; the channel's field byte
	bsr.w	open_channel_buffer
	movea.l	(sp)+,a0                        ; a0 -> field byte
	move.w	(sp)+,d0                        ; record length
	bmi.s	.bad_length                     ; 32768 or more: error 48
	lea	$256(a6),a1                     ; field numbers of all channels
	moveq	#99,d1                          ; 100 channels
	moveq	#1,d3                           ; field 0 never free
.mark_field:
	move.b	(a1)+,d2
	beq.s	.next_field
	bset	d2,d3                           ; mark it used
.next_field:
	dbra	d1,.mark_field
	moveq	#31,d1                          ; from field 31 down
.find_free_field:
	btst	d1,d3
	dbeq	d1,.find_free_field             ; first free one
	tst.w	d1
	bgt.s	open_random_record              ; found one
	moveq	#49,d0                          ; error 49: too many "R" files
	bra.w	open_gemdos_error               ; raise it
.bad_length:
	moveq	#48,d0                          ; error 48: record length wrong

open_gemdos_error:
	dc.w	$6000,$0000                     ; bra.w	open_gemdos_error+2 -> ERROR (filled in by the linker), raise it

;------------------------------------------------------------------------------
; Gives a random-access channel its field buffer: stores the field buffer number for the channel and allocates the
; 6-byte record descriptor (record length and record number).
; Entry: d1 = free field buffer number, a0 -> the channel's field byte, d0.w = record length
;------------------------------------------------------------------------------
open_random_record:
	move.b	d1,(a0)                         ; field number for the channel
	asl.w	#3,d1
	lea	$2bc(a6),a1                     ; field buffers: 8 bytes each
	adda.w	d1,a1
	move.w	d0,-(sp)                        ; keep the record length
	movea.l	a1,a0
	clr.l	(a1)+
	clr.w	(a1)+
	moveq	#6,d0                           ; 6-byte record descriptor

open_call_screat_record:
	dc.w	$6100,$0000                     ; bsr.w open_call_screat_record+2 -> Screat (filled in by the linker),
                                                ;   allocate it
	move.w	(sp)+,(a1)+                     ; record length
	clr.l	(a1)+                           ; record number 0
	rts

; Device names OPEN recognises, four characters each, in the order PRN: LST: AUX: CON: MID: IKB: VID: (codes -7 to -1).
device_names:
	dc.b	'PRN:LST:AUX:CON:MID:IKB:VID:`',0 ; the bytes '`',0,0,0 after VID: are a bra.w word pair (at $228)
	dc.w	$0000

