m_kill:
;------------------------------------------------------------------------------
; KILL name$: deletes a file (Fdelete).
; Entry: a0 -> string descriptor of the name
;------------------------------------------------------------------------------
KILL:
	moveq	#65,d0                          ; unlabelled entry: KILL (Fdelete)
	bra.s	gemdos_path_call                ; make the call

;------------------------------------------------------------------------------
; MKDIR path$: creates a folder (Dcreate).
; Entry: a0 -> string descriptor of the path
;------------------------------------------------------------------------------
MKDIR:
	moveq	#57,d0                          ; unlabelled entry: MKDIR (Dcreate)
	bra.s	gemdos_path_call                ; make the call

;------------------------------------------------------------------------------
; RMDIR path$: deletes a folder (Ddelete).
; Entry: a0 -> string descriptor of the path
;------------------------------------------------------------------------------
RMDIR:
	moveq	#58,d0                          ; unlabelled entry: RMDIR (Ddelete)
	bra.s	gemdos_path_call                ; make the call

;------------------------------------------------------------------------------
; CHDIR path$: Dsetpath.
; Entry: a0 -> path string descriptor
;------------------------------------------------------------------------------
change_directory:
	moveq	#59,d0                          ; Dsetpath

;------------------------------------------------------------------------------
; Calls a GEMDOS function that takes one path, zero-terminating the BASIC string in place for the call.
; Entry: d0.w = function, a0 -> string descriptor; a GEMDOS error is raised as a runtime error
;------------------------------------------------------------------------------
gemdos_path_call:
	move.w	d0,d7                           ; function

kill_call_xstr0kil:
	dc.w	$6100,$0000                     ; bsr.w kill_call_xstr0kil+2 -> XStrKill (filled in by the linker), a1
                                                ;   -> text, d1 = length
	lea	0(a1,d1.w),a0                   ; a0 -> byte after the text
	move.b	(a0),-(sp)                      ; keep it
	pea	(a0)                            ; address for the restore
	clr.b	(a0)                            ; terminate the text
	pea	(a1)                            ; path
	move.w	d7,-(sp)
	trap	#1                              ; GEMDOS
	addq.l	#6,sp                           ; drop path and function
	movea.l	(sp)+,a0                        ; restore the byte
	move.b	(sp)+,(a0)
	tst.l	d0

kill_call_error:
	dc.w	$6b00,$0000                     ; bmi.w	kill_call_error+2 -> ERROR (filled in by the linker), error
	rts

