;------------------------------------------------------------------------------
; NAME old$ AS new$ (RENAME): renames a file with Frename. Both strings are
; zero-terminated in place for the call and the bytes after them restored.
; Entry: a1 -> descriptor of the old name, a0 -> descriptor of the new name
; Exit: GEMDOS errors are raised as runtime errors
;------------------------------------------------------------------------------
RENAME:
	move.l	a0,-(sp)                        ; keep the new name
	movea.l	a1,a0                           ; the old name first

name_call_xstr0kil_old:
	dc.w	$6100,$0000                     ; bsr.w name_call_xstr0kil_old+2 -> XStr0Kil (filled in by the linker),
                                                ;   a1 -> text, d1 = length
	move.l	(sp)+,d2                        ; new name descriptor
	movea.l	a1,a2                           ; a2 -> old name text
	lea	0(a1,d1.w),a0                   ; byte after it
	move.b	(a0),-(sp)                      ; keep it
	pea	(a0)                            ; address for the restore
	clr.b	(a0)                            ; terminate the old name
	movea.l	d2,a0                           ; the new name

name_call_xstr0kil_new:
	dc.w	$6100,$0000                     ; bsr.w name_call_xstr0kil_new+2 -> XStr0Kil (filled in by the linker),
                                                ;   a1 -> text, d1 = length
	lea	0(a1,d1.w),a0                   ; byte after it
	move.b	(a0),-(sp)                      ; keep it
	pea	(a0)                            ; address for the restore
	clr.b	(a0)                            ; terminate the new name
	pea	(a1)                            ; new name
	pea	(a2)                            ; old name
	clr.w	-(sp)                           ; reserved word 0
	move.w	#$56,-(sp)                      ; Frename
	trap	#1                              ; Frename
	lea	$c(sp),sp                       ; drop the arguments
	movea.l	(sp)+,a0                        ; restore the byte after the new name
	move.b	(sp)+,(a0)
	movea.l	(sp)+,a0                        ; restore the byte after the old name
	move.b	(sp)+,(a0)
	tst.l	d0

name_call_error:
	dc.w	$6b00,$0000                     ; bmi.w name_call_error+2 -> ERROR (filled in by the linker), negative:
                                                ;   raise the error
	rts

