;------------------------------------------------------------------------------
; PEEK(addr): reads a byte in supervisor mode.
; Entry: d0.l = address
; Exit: d0.l = byte
;------------------------------------------------------------------------------
peek_byte:
	pea	read_byte_super(pc)             ; routine for Supexec
	bra.s	supexec_peek                    ; run it in supervisor mode

;------------------------------------------------------------------------------
; DPEEK(addr): reads a word in supervisor mode.
; Entry: d0.l = address
; Exit: d0.l = word
;------------------------------------------------------------------------------
peek_word:
	pea	read_word_super(pc)             ; routine for Supexec
	bra.s	supexec_peek                    ; run it in supervisor mode

;------------------------------------------------------------------------------
; TIMER: reads the 200 Hz system counter (_hz_200).
; Exit: d0.l = count
;------------------------------------------------------------------------------
read_timer:
	move.l	#$4ba,d0                        ; _hz_200

;------------------------------------------------------------------------------
; LPEEK(addr): reads a long in supervisor mode.
; Entry: d0.l = address
; Exit: d0.l = long
;------------------------------------------------------------------------------
peek_long:
	pea	read_long_super(pc)             ; routine for Supexec

;------------------------------------------------------------------------------
; Runs the stacked read routine with Supexec.
; Entry: d0.l = address, routine address stacked
;------------------------------------------------------------------------------
supexec_peek:
	move.l	d0,d3                           ; address for the routine
	move.w	#$26,-(sp)                      ; Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop routine and opcode
