; Two VDI MFDBs (20 bytes each), disassembled as code: the source block at 0 and the screen block at $14
; (fd_addr, fd_w, fd_h, fd_wdwidth, fd_stand, fd_nplanes, three reserved words); preset 640x400 mono.
getput_source_mfdb:
	dc.w	$0000,$0000
	andi.l	#$1900028,d0                    ; fd_w, fd_h, fd_wdwidth (640, 400, 40)
	ori.b	#$1,d0                          ; fd_stand 0, fd_nplanes 1
	ori.b	#$0,d0                          ; reserved

;------------------------------------------------------------------------------
; Last reserved word of the source MFDB; label+2 is the screen MFDB.
;------------------------------------------------------------------------------
getput_source_mfdb_r3:
	ori.b	#$0,d0                          ; reserved; the screen MFDB starts at $14
	dc.w	$0000

;------------------------------------------------------------------------------
; fd_w of the screen MFDB, followed by fd_h.
;------------------------------------------------------------------------------
getput_screen_mfdb_width:
	andi.l	#$1900028,d0                    ; screen fd_w, fd_h, fd_wdwidth (640, 400, 40)
	ori.b	#$1,d0                          ; fd_stand 0, fd_nplanes 1
	ori.b	#$0,d0                          ; reserved
	dc.w	$0000

;------------------------------------------------------------------------------
; Points both MFDBs at the logical screen with the Line-A screen size, line width and plane count.
; Exit: both MFDBs set; changes d0-d4, d7, a0-a2
;------------------------------------------------------------------------------
getput_mfdbs_to_screen:
	move.w	#$3,-(sp)                       ; Logbase
	trap	#14                             ; Logbase
	addq.l	#2,sp
	move.l	d0,d7                           ; screen address
	movea.l	$32(a6),a0                      ; Line-A variables
	move.w	-$c(a0),d0                      ; V_REZ_HZ: width
	movem.w	-$4(a0),d1-d2/d4                ; V_REZ_VT, BYTES_LIN, PLANES
	lsr.w	#1,d2                           ; words a line
	moveq	#0,d3                           ; fd_stand 0: device format
	lea	getput_source_mfdb(pc),a0       ; source MFDB
	move.l	d7,(a0)+                        ; fd_addr
	movem.w	d0-d4,(a0)                      ; fd_w .. fd_nplanes
	lea	getput_source_mfdb_r3+2(pc),a0  ; screen MFDB
	move.l	d7,(a0)+                        ; fd_addr
	movem.w	d0-d4,(a0)                      ; fd_w .. fd_nplanes

getput_return:
	rts

;------------------------------------------------------------------------------
; PUT x,y,a$: puts a GET string on the screen in replace mode (3).
; Entry: a0 = string descriptor, d1 = x, d2 = y
; Exit: through SPUTM
;------------------------------------------------------------------------------
SPUT:
	moveq	#3,d0                           ; mode 3: replace

;------------------------------------------------------------------------------
; PUT x,y,a$,mode: puts a GET string (width-1, height-1, planes, then the bitmap) on the screen. Modes 0-15 use the
; Line-A bit block transfer with clipping to the screen; 16 and up go through VDI vro_cpyfm. Strings shorter than 6
; bytes or with another plane count are ignored. Hides the mouse; nothing here shows it again.
; Entry: a0 = string descriptor, d0 = mode, d1 = x, d2 = y
; Exit: changes d0-d7, a0-a1
;------------------------------------------------------------------------------
SPUTM:
	cmpi.w	#$10,d0                         ; modes 16 and up
	bcc.w	sput_vdi_copy                   ; use VDI vro_cpyfm
