;------------------------------------------------------------------------------
; FORM_ALERT: builds an alert string "[icon][text][buttons]" in TEXT_BUFFER from the two strings, removing any [ and ]
; characters, keeping at most 5 text lines of 30 characters and 3 buttons of 8 characters split by '|', then calls AES
; form_alert (52).
; Entry: d1 = default button, d2 = icon (0-3), a1 = text string, a0 = buttons string.
; Exit: d0 = d1.l = button pressed.
;------------------------------------------------------------------------------
form_alert:
	move.w	d1,-(sp)                        ; default button
	move.w	d2,-(sp)                        ; icon
	move.l	a1,-(sp)                        ; text string

alert_call_xstr0kil_buttons:
	dc.w	$6100,$0000                     ; bsr.w alert_call_xstr0kil_buttons+2 -> XStr0Kil (filled in by the
                                                ;   linker), buttons string
	move.l	a1,d6                           ; buttons text
	move.w	d1,d7                           ; buttons length
	movea.l	(sp)+,a0                        ; text string descriptor

alert_call_xstr0kil_text:
	dc.w	$6100,$0000                     ; bsr.w alert_call_xstr0kil_text+2 -> XStr0Kil (filled in by the
                                                ;   linker), text string
	move.w	d7,d2                           ; text length to d1, buttons length to d2
	movea.l	d6,a2                           ; buttons text
	lea	$46(a6),a0                      ; build in the text buffer
	moveq	#3,d0                           ; icon 0-3
	and.w	(sp)+,d0                        ; icon from the stack
	ori.w	#$5b30,d0                       ; "[n"
	move.w	d0,(a0)+                        ; "[n"
	move.w	#$5d5b,(a0)+                    ; "]["
	moveq	#3,d3                           ; at most 5 lines
	moveq	#30,d4                          ; of 30 characters
	bra.s	.text_next                      ; enter the text loop
.text_char:
	move.b	(a1)+,d0                        ; next text character
	cmpi.b	#$5b,d0                         ; brackets are left out
	beq.s	.text_next
	cmpi.b	#$5d,d0                         ; ']'?
	beq.s	.text_next
	move.b	d0,(a0)+                        ; store the character
	cmpi.b	#$7c,d0                         ; '|' starts a new line
	beq.s	.text_new_line
	dbra	d4,.text_next                   ; line still has room?
	subq.l	#1,a0                           ; full: drop the character
	moveq	#0,d4                           ; no more on this line
	bra.s	.text_next
.text_new_line:
	moveq	#30,d4                          ; new line
	dbra	d3,.text_next                   ; too many lines?
	subq.l	#1,a0                           ; drop the '|' and stop
	moveq	#0,d1                           ; end the text
.text_next:
	dbra	d1,.text_char                   ; text characters left?
	move.b	#$5d,(a0)+                      ; "]["
	move.b	#$5b,(a0)+
	moveq	#2,d3                           ; at most 3 buttons
	moveq	#8,d4                           ; of 8 characters
	bra.s	.button_next                    ; enter the button loop
.button_char:
	move.b	(a2)+,d0                        ; next button character
	cmpi.b	#$5b,d0                         ; brackets are left out
	beq.s	.button_next
	cmpi.b	#$5d,d0                         ; ']'?
	beq.s	.button_next
	move.b	d0,(a0)+                        ; store the character
	cmpi.b	#$7c,d0                         ; '|' starts a new button
	beq.s	.button_new
	dbra	d4,.button_next                 ; button still has room?
	subq.l	#1,a0                           ; full: drop the character
	moveq	#0,d4                           ; no more on this button
	bra.s	.button_next
.button_new:
	moveq	#8,d4                           ; new button
	dbra	d3,.button_next                 ; too many buttons?
	subq.l	#1,a0                           ; drop the '|' and stop
	moveq	#0,d2                           ; end the buttons
.button_next:
	dbra	d2,.button_char                 ; button characters left?
	move.b	#$5d,(a0)+                      ; "]"
	clr.b	(a0)+                           ; zero terminate
	lea	$46(a6),a0                      ; the alert string
	move.w	(sp)+,d0                        ; default button
	move.l	a0,$112c(a6)                    ; addr_in[0]
	move.w	d0,$10dc(a6)                    ; int_in[0]
	moveq	#52,d0                          ; form_alert

