.next_object:
	adda.w	#$18,a0                         ; next object (24 bytes)
	subq.w	#1,d0                           ; up to the item
	bne.s	.count_items                    ; more objects
.store_menu_index:
	move.w	d1,$1342(a6)                    ; MENU(0)
	move.l	d2,d1                           ; ON MENU GOSUB handler
.queue_handler:
	bsr.s	queue_event_handler             ; queue the GOSUB handler
	rts

;------------------------------------------------------------------------------
; Queues an event handler: when the flags say the handler address in d1 is set, slips it under the return address, so
; the handler runs when the caller returns.
; Entry: d1.l = handler address, Z set when there is none.
; Exit: stack changed when a handler is queued.
;------------------------------------------------------------------------------
queue_event_handler:
	beq.s	event_return                    ; no handler
	move.l	(sp),-(sp)                      ; copy the return address down
	move.l	d1,4(sp)                        ; handler runs when the caller returns

;------------------------------------------------------------------------------
; Return from queue_event_handler and the event poll.
;------------------------------------------------------------------------------
event_return:
	rts

;------------------------------------------------------------------------------
; MENU(n): n >= 0 returns word n of the event results (MENU(0) = menu entry number, then the message buffer and the
; evnt_multi results); MENU(-1) returns the menu tree address and MENU(-2) the message buffer address. The ON MENU
; statements that set up the handlers follow.
; Entry: d0 = n.
; Exit: d0.l = value.
;------------------------------------------------------------------------------
menu_function:
	add.w	d0,d0                           ; word index
	bmi.s	.special                        ; negative: special values
	lea	$1342(a6),a0                    ; MENU(0) and the event results
	move.w	0(a0,d0.w),d0                   ; the word
	ext.l	d0                              ; as a long
	rts
.special:
	addq.w	#4,d0                           ; MENU(-1)?
	beq.s	.message_buffer                 ; MENU(-2)
	move.l	$1298(a6),d0                    ; menu tree address
	rts
.message_buffer:
	lea	$1344(a6),a0                    ; MENU(-2): message buffer address
	move.l	a0,d0                           ; as the result
	rts

;------------------------------------------------------------------------------
; ON MENU IBOX n,x,y,w,h GOSUB: handler for the mouse entering a rectangle.
; Entry: d1 = rectangle number (1 or 2), d2-d4/d0 = x, y, w, h, a2 = handler
;------------------------------------------------------------------------------
on_menu_enter_box:
	moveq	#0,d5                           ; ON MENU IBOX: enter the rectangle
	bra.s	on_menu_box                     ; store it

;------------------------------------------------------------------------------
; ON MENU OBOX n,x,y,w,h GOSUB: handler for the mouse leaving a rectangle.
; Entry: as on_menu_enter_box
;------------------------------------------------------------------------------
on_menu_leave_box:
	moveq	#1,d5                           ; ON MENU OBOX: leave the rectangle

;------------------------------------------------------------------------------
; Stores the parameters and the handler of one of the two mouse rectangles.
; Entry: d5 = 0 enter, 1 leave; d1 = rectangle number, d2-d4/d0 = x, y, w, h, a2 = handler
;------------------------------------------------------------------------------
on_menu_box:
	lea	$1336(a6),a0                    ; first rectangle handler
	lea	$1316(a6),a1                    ; first rectangle parameters
	moveq	#2,d6                           ; event bit 2
	lsr.w	#1,d1                           ; second rectangle?
	bcc.s	.store_rect                     ; first rectangle
	addq.l	#4,a0                           ; second rectangle handler
	lea	$1320(a6),a1                    ; second rectangle parameters
	moveq	#3,d6                           ; event bit 3
.store_rect:
	move.w	d5,(a1)+                        ; enter/leave flag
	move.w	d0,d5                           ; h next to x, y, w
	movem.w	d2-d5,(a1)                      ; x, y, w, h
	move.w	d6,d0                           ; event bit
	bra.s	set_event_handler               ; store the handler

;------------------------------------------------------------------------------
; ON MENU BUTTON clicks,mask,state GOSUB: handler for mouse clicks.
; Entry: d1-d2/d0 = clicks, mask, state, a2 = handler
;------------------------------------------------------------------------------
on_menu_button:
	move.w	d0,d3                           ; ON MENU BUTTON: clicks, mask, state
	movem.w	d1-d3,$1310(a6)                 ; evnt_multi button parameters
	moveq	#1,d0                           ; event bit 1
	lea	$1332(a6),a0                    ; button handler
	bra.s	set_event_handler               ; store the handler

;------------------------------------------------------------------------------
; ON MENU KEY GOSUB: handler for key presses.
; Entry: a2 = handler
;------------------------------------------------------------------------------
on_menu_key:
	lea	$132e(a6),a0                    ; ON MENU KEY handler
	moveq	#0,d0                           ; event bit 0
	bra.s	set_event_handler               ; store the handler

;------------------------------------------------------------------------------
; ON MENU MESSAGE GOSUB: handler for AES messages other than menu selections.
; Entry: a2 = handler
;------------------------------------------------------------------------------
on_menu_message:
	lea	$133e(a6),a0                    ; ON MENU MESSAGE handler
	bra.s	on_menu_message_bit             ; event bit 4 as well

;------------------------------------------------------------------------------
; ON MENU GOSUB: handler for menu selections.
; Entry: a2 = handler
;------------------------------------------------------------------------------
on_menu_gosub:
	lea	$132a(a6),a0                    ; ON MENU GOSUB handler

on_menu_message_bit:
	moveq	#4,d0                           ; event bit 4

;------------------------------------------------------------------------------
; Stores an ON MENU handler and turns its event bit in the evnt_multi mask on, or off when the handler address is 0.
; Entry: a0 -> handler slot, a2 = handler, d0 = event bit
;------------------------------------------------------------------------------
set_event_handler:
	move.w	$130e(a6),d2                    ; event mask
	bclr	d0,d2                           ; event off
	move.l	a2,(a0)                         ; store the handler address
	beq.s	.store_mask                     ; address 0 turns the event off
	bset	d0,d2                           ; else on
.store_mask:
	move.w	d2,$130e(a6)                    ; new event mask
	rts

; symbol table: name, type, value
	dc.b	$50,$4f,$4c,$4c,$4d,$45,$4e,$55		; POLLMENU
	dc.w	$a200				; defined global text
	dc.l	$0
	dc.b	$54,$50,$4f,$4c,$4c,$4d,$45,$4e		; TPOLLMEN
	dc.w	$a200				; defined global text
	dc.l	$2
	dc.b	$4d,$45,$4e,$55,$46,$4e,$00,$00		; MENUFN
	dc.w	$a200				; defined global text
	dc.l	$90
	dc.b	$4f,$4e,$4d,$5f,$49,$42,$58,$00		; ONM_IBX
	dc.w	$a200				; defined global text
	dc.l	$b2
	dc.b	$4f,$4e,$4d,$5f,$4f,$42,$58,$00		; ONM_OBX
	dc.w	$a200				; defined global text
	dc.l	$b6
	dc.b	$4f,$4e,$4d,$5f,$42,$55,$54,$00		; ONM_BUT
	dc.w	$a200				; defined global text
	dc.l	$da
	dc.b	$4f,$4e,$4d,$5f,$4b,$45,$59,$00		; ONM_KEY
	dc.w	$a200				; defined global text
	dc.l	$ea
	dc.b	$4f,$4e,$4d,$5f,$4d,$53,$47,$00		; ONM_MSG
	dc.w	$a200				; defined global text
	dc.l	$f2
	dc.b	$4f,$4e,$4d,$5f,$4d,$45,$4e,$00		; ONM_MEN
	dc.w	$a200				; defined global text
	dc.l	$f8
	dc.b	$45,$56,$4e,$54,$5f,$4d,$55,$58		; EVNT_MUX
	dc.w	$8800				; defined external
	dc.l	$0
; relocation words, one a code word: 0 none, 1 data, 2 text, 3 bss, 4 external, 5 a long (its low
; word tells), 6 external pc-relative, 7 the first word of an instruction; an external's symbol
; number is the word >> 3
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$004e,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000

;==============================================================================
; Module MENU.O: 676 bytes of code, 0 of data, 8900 of bss; exports MENUKILL, MENU
;==============================================================================
	dc.b	$4d,$45,$4e,$55,$2e,$4f,$00,$00,$00,$00,$00,$00,$00,$00	; library entry: the name MENU.O
	dc.w	$b3cd,$12a2,$0000,$01b6,$0000,$05aa,$0000	; entry: the rest (the member's length at +8)
	dc.w	$601a				; DRI object module
	dc.l	$2a4,$0,$22c4,$46		; text, data and bss lengths, symbol table length
	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_menu:
;------------------------------------------------------------------------------
; MENU KILL: removes all ON MENU handlers and the menu bar.
;------------------------------------------------------------------------------
menu_kill:
	lea	$132a(a6),a0
	moveq	#5,d0                           ; six handler longs
.clear_handler:
	clr.l	(a0)+
	dbra	d0,.clear_handler
	clr.w	(a0)+                           ; MENU(0) = 0

;------------------------------------------------------------------------------
; Removes the menu bar (menu_bar 0) if there is one and forgets the tree.
;------------------------------------------------------------------------------
remove_menu_bar:
	move.l	$1298(a6),d1                    ; menu tree
	beq.s	remove_bar_done                 ; none: nothing to remove
	moveq	#0,d0                           ; menu_bar 0: remove

remove_bar_call_menu_bar:
	dc.w	$6100,$0000                     ; bsr.w remove_bar_call_menu_bar+2 -> MENU_BAR (filled in by the
                                                ;   linker), call MENU_BAR
	clr.l	$1298(a6)                       ; no tree now

;------------------------------------------------------------------------------
; Return point.
;------------------------------------------------------------------------------
remove_bar_done:
	rts

; Character height used for the menu objects: 8, or 16 in high resolution.
menu_char_height:
	dc.w	$0000

;------------------------------------------------------------------------------
; Starts the runtime's menu object tree: 200 string objects, then the root (screen size from the desktop area at
; $1250(a6)), the bar, the title box and the box for the drop-down menus, sized from the character height (8, or 16 in
; high resolution).
; Exit: var_a44f4 = object tree; menu_char_height set
;------------------------------------------------------------------------------
init_menu_tree:
	moveq	#4,d0                           ; wind_get 0, WF_WORKXYWH: desktop work area
	moveq	#0,d1

init_menu_call_wind_get:
	dc.w	$6100,$0000                     ; bsr.w init_menu_call_wind_get+2 -> WIND_GET (filled in by the linker),
                                                ;   call WIND_GET
	movem.w	d1-d4,$1250(a6)                 ; desktop x, y, w, h
	move.w	#$4,-(sp)                       ; high resolution: 16 lines per character
	trap	#14                             ; Getrez
	addq.l	#2,sp
	moveq	#4,d7                           ; shift 4: 16 lines
	subq.w	#2,d0                           ; 2 = high resolution
	beq.s	.char_height
	moveq	#3,d7                           ; else shift 3: 8 lines
.char_height:
	moveq	#1,d2                           ; character height
	asl.w	d7,d2
	move.w	d2,menu_char_height-m_menu      ; keep it
	lea	$0,a0                           ; tree block
	moveq	#1,d0                           ; ob_next of object 0 = 1
	moveq	#-1,d1                          ; -1: no children
.fill_objects:
	move.w	d0,(a0)+                        ; 200 objects: next, head/tail -1, G_STRING
	move.l	d1,(a0)+                        ; ob_head, ob_tail = -1
	move.w	#$1c,(a0)+                      ; ob_type G_STRING
	clr.l	(a0)+                           ; ob_flags, ob_state = 0
	clr.l	(a0)+                           ; ob_spec = 0
	clr.l	(a0)+                           ; ob_x, ob_y = 0
	move.l	d2,(a0)+                        ; ob_width 0, ob_height = character height
	addq.w	#1,d0
	cmpi.w	#$c9,d0                         ; up to 200 objects
	bne.s	.fill_objects
	lea	$0,a0                           ; root object
	move.w	d1,(a0)+                        ; ob_next -1
	move.w	#$1,(a0)+                       ; ob_head 1
	move.w	#$15,(a0)+                      ; ob_tail 21
	move.w	#$19,(a0)+                      ; G_IBOX
	addq.l	#8,a0                           ; skip flags, state, spec
	clr.l	(a0)+                           ; x, y = 0
	move.w	$1254(a6),(a0)+                 ; width = desktop width
	moveq	#25,d0                          ; height 25 lines
	asl.w	d7,d0
	move.w	d0,(a0)+
	move.w	#$15,(a0)+                      ; object 1, the bar: ob_next 21
	move.w	#$2,(a0)+                       ; ob_head 2
	move.w	#$2,(a0)+                       ; ob_tail 2
	move.w	#$14,(a0)+                      ; G_BOX
	addq.l	#6,a0                           ; skip flags, state, spec high word
	move.w	#$1100,(a0)+                    ; ob_spec low word $1100
	addq.l	#4,a0                           ; skip x, y
	move.w	$1254(a6),(a0)+                 ; width = desktop width
	moveq	#1,d0                           ; height: one line plus 2
	asl.w	d7,d0
	addq.w	#2,d0
	move.w	d0,(a0)+                        ; ob_height
	move.w	#$1,(a0)+                       ; object 2, the title box: ob_next 1
	move.w	#$3,(a0)+                       ; ob_head 3
	move.w	#$15,(a0)+                      ; ob_tail 21 (set again at the end)
	move.w	#$19,(a0)+                      ; G_IBOX
	addq.l	#8,a0                           ; skip flags, state, spec
	move.w	#$10,(a0)+                      ; x = 16
	clr.w	(a0)+                           ; y = 0
	moveq	#-16,d0                         ; width = desktop width - 16
	add.w	$1254(a6),d0
	move.w	d0,(a0)+
	moveq	#1,d1                           ; one line plus 3
	asl.w	d7,d1
	addq.w	#3,d1
	move.w	d1,(a0)+                        ; ob_height
	moveq	#17,d0                          ; objects 3-20
.title_objects:
	move.w	#$20,6(a0)                      ; G_TITLE
	move.w	d1,$16(a0)                      ; title height
	adda.w	#$18,a0                         ; next object
	dbra	d0,.title_objects
	clr.w	(a0)+                           ; object 21: ob_next 0
	move.w	#$16,(a0)+                      ; ob_head 22
	movea.l	a0,a2                           ; a2 -> its ob_tail
	addq.w	#2,a0                           ; skip ob_tail
	move.w	#$19,(a0)+                      ; G_IBOX
	addq.l	#8,a0                           ; skip flags, state, spec
	move.l	$1250(a6),(a0)+                 ; x, y = desktop x, y
	move.w	$1254(a6),(a0)+                 ; width = desktop width
	moveq	#25,d0                          ; height 25 lines
	asl.w	d7,d0
	move.w	d0,(a0)+                        ; ob_height
	rts

;------------------------------------------------------------------------------
; MENU m$(): builds the menu from a string array and shows the bar.
; Entry: a0 = array descriptor
;------------------------------------------------------------------------------
menu_create:
	movem.l	a3/a5,$46(a6)                   ; keep a3/a5 in the text buffer
	bsr.s	build_menu

;------------------------------------------------------------------------------
; Restores a3/a5 kept in the text buffer by menu_create.
;------------------------------------------------------------------------------
restore_menu_registers:
	movem.l	$46(a6),a3/a5
	rts

;------------------------------------------------------------------------------
; Takes the next element of the menu string array, counting down the element count at 4(sp).
; Entry: a3 -> next descriptor
; Exit: a0 = text, d0 = length; d0 = 0 also at the end of the array
;------------------------------------------------------------------------------
next_menu_string:
	subq.l	#1,4(sp)                        ; one element fewer
	bmi.s	.end_of_array                   ; array used up
	movea.l	(a3)+,a0                        ; element text
	move.w	(a3)+,d0                        ; element length
	rts
.end_of_array:
	moveq	#0,d0                           ; end: like an empty string
	rts

;------------------------------------------------------------------------------
; MENU with an array that is not one-dimensional: error 28.
;------------------------------------------------------------------------------
menu_not_one_dimension:
	moveq	#28,d0                          ; error 28

;------------------------------------------------------------------------------
; Restores a3/a5 and raises the error in d0.
;------------------------------------------------------------------------------
menu_error:
	bsr.s	restore_menu_registers

menu_jump_error:
	dc.w	$6000,$0000                     ; bra.w menu_jump_error+2 -> ERROR (filled in by the linker), tail call
                                                ;   ERROR

;------------------------------------------------------------------------------
; MENU with too many titles, entries or text: error 62.
;------------------------------------------------------------------------------
menu_invalid:
	moveq	#62,d0                          ; error 62
	bra.s	menu_error

;------------------------------------------------------------------------------
; MENU m$(): builds the menu tree from the strings: each title is followed by its entries and an empty string, an entry
; beginning with '-' is disabled, two empty strings end the menu. At most 18 titles, 199 objects and 4000 characters of
; text (copied to var_a57b4); then shows the bar with menu_bar.
; Entry: a0 = array descriptor
; Exit: menu bar shown, MENU_TREE set
;------------------------------------------------------------------------------
build_menu:
	pea	(a0)
	bsr.w	remove_menu_bar                 ; old bar away, fresh tree
	bsr.w	init_menu_tree
	movea.l	(sp)+,a0
	movea.l	(a0)+,a3                        ; array data
	cmpi.w	#$1,(a0)                        ; one dimension?
	bne.s	menu_not_one_dimension
	move.l	(a3)+,-(sp)                     ; element count
	moveq	#3,d6                           ; title 3 onwards, objects from 22
	moveq	#22,d7
	lea	$12c0,a5                        ; text area: tree block + $12c0
	moveq	#0,d5                           ; x of the next title
.next_title:
	bsr.s	next_menu_string
	beq.w	finish_menu_tree                ; empty string: end of the menu
	cmpi.w	#$a,d0                          ; at most 10 characters of a title count for its width
	bcs.s	.title_text
	moveq	#10,d0
.title_text:
	move.w	d0,d1                           ; visible length
	moveq	#24,d2                          ; 24 bytes an object
	mulu.w	d6,d2
	lea	$c,a1                           ; address error vector, ob_spec of object 0 (relocated)
	adda.l	d2,a1                           ; ob_spec of title d6
	move.l	a5,(a1)+                        ; title text
	move.w	d5,(a1)+                        ; ob_x
	move.b	#$20,(a5)+                      ; leading space
	subq.w	#1,d0                           ; dbra count
	pea	(a1)                            ; keep the object pointer
	lea	$2260,a1                        ; end of the text area
.copy_title:
	move.b	(a0)+,(a5)+                     ; copy the title
	cmpa.l	a1,a5                           ; stop at the end of the text area
	dbhi	d0,.copy_title
	movea.l	(sp)+,a1
	bcc.w	menu_too_big                    ; text area full
	move.b	#$20,(a5)+                      ; trailing space
	clr.b	(a5)+                           ; zero terminate
	addq.w	#2,d1                           ; two spaces
	asl.w	#3,d1                           ; eight pixels a character
	move.w	d1,2(a1)                        ; title width
	moveq	#24,d0
	mulu.w	d7,d0                           ; object d7 of the tree
	lea	$0,a1                           ; the box for its entries
	adda.l	d0,a1
	move.w	d7,(a2)                         ; link the box into the previous one
	movea.l	a1,a2                           ; a2 = the box
	move.w	d7,(a1)+                        ; ob_next = itself for now
	bsr.w	next_menu_object                ; check the object count
	move.w	d7,(a1)+                        ; ob_head = first entry
	move.w	d7,(a1)+                        ; ob_tail, set at the end
	move.w	#$14,(a1)+                      ; G_BOX
	clr.l	(a1)+                           ; flags, state = 0
	move.l	#$ff1100,(a1)+                  ; ob_spec $00ff1100
	move.w	d5,d0                           ; x under its title
	addi.w	#$10,d0
	move.w	d0,(a1)+                        ; ob_x
	add.w	d1,d5                           ; x of the next title
	addq.l	#6,a1                           ; skip y, width, height
	moveq	#0,d4                           ; widest entry
	moveq	#0,d3                           ; entry count
.next_entry:
	bsr.w	next_menu_string                ; next entry string
	beq.s	.title_done                     ; empty: title done
	move.w	d0,d1                           ; length
	move.l	a5,$c(a1)                       ; ob_spec = text
	move.w	d3,d2                           ; y = entry number * line height
	mulu.w	menu_char_height(pc),d2
	move.w	d2,$12(a1)                      ; ob_y
	subq.w	#1,d0                           ; '-' at the start: disabled entry
	cmpi.b	#$2d,(a0)                       ; starts with '-'?
	bne.s	.copy_entry_text
	bset	#$3,$b(a1)                      ; DISABLED
.copy_entry_text:
	pea	(a1)                            ; keep the object pointer
	lea	$2260,a1                        ; end of the text area
.copy_entry:
	move.b	(a0)+,(a5)+                     ; copy the entry
	cmpa.l	a1,a5                           ; stop at the end of the text area
	dbhi	d0,.copy_entry
	movea.l	(sp)+,a1
	bcc.s	menu_too_big                    ; text area full: error 62
	clr.b	(a5)+                           ; zero terminate
	asl.w	#3,d1                           ; widest entry
	cmp.w	d1,d4                           ; wider than the widest so far?
	bhi.s	.entry_done
	move.w	d1,d4                           ; new widest
.entry_done:
	adda.w	#$18,a1                         ; next object, not range checked
	addq.w	#1,d7
	addq.w	#1,d3
	bra.s	.next_entry
.title_done:
	move.w	(a2),-$18(a1)                   ; last entry: ob_next = its box
	subq.w	#1,d7                           ; last entry
	move.w	d7,4(a2)                        ; box ob_tail
	mulu.w	menu_char_height(pc),d3         ; box height
	move.w	d3,$16(a2)
	movea.l	a2,a0                           ; from the box
.set_widths:
	move.w	d4,$14(a0)                      ; box and entries get the widest width
	adda.w	#$18,a0
	cmpa.l	a1,a0                           ; up to the last entry
	bls.s	.set_widths
	bsr.s	next_menu_object                ; one object on, checking the count
	addq.w	#1,d6                           ; next title object
	cmpi.w	#$15,d6                         ; past title 20?
	bcs.w	.next_title                     ; no: next title

menu_too_big:
	bra.w	menu_invalid                    ; error 62

;------------------------------------------------------------------------------
; Moves to the next object of the menu tree; past object 198 the menu is too big (error 62).
;------------------------------------------------------------------------------
next_menu_object:
	addq.w	#1,d7                           ; next object
	cmpi.w	#$c7,d7                         ; 199 or more?
	bcc.s	menu_too_big                    ; too many: error 62
	rts

;------------------------------------------------------------------------------
; Ends the menu tree: last title and box, flags of the last object, then shows the bar (menu_bar 1) and keeps the tree
; address.
;------------------------------------------------------------------------------
finish_menu_tree:
	addq.l	#4,sp                           ; drop the element count
	lea	$0,a0                           ; tree block
	subq.w	#1,d6                           ; last title
	move.w	d6,$34(a0)                      ; object 2 ob_tail
	move.w	(a2),$1fc(a0)                   ; object 21 ob_tail = the last box
