	move.w	(a0)+,d1                        ; attributes for wind_create
	pea	(a0)                            ; keep -> x, y, w, h
	movem.w	$1250(a6),d2-d5                 ; full size: the desktop
	move.w	d5,d0

open_call_wind_create:
	dc.w	$6100,$0000                     ; bsr.w open_call_wind_create+2 -> WIND_CRE (filled in by the linker),
                                                ;   wind_create in the desktop area
	movea.l	(sp),a0                         ; table entry + 4
	move.w	d0,-$4(a0)                      ; keep the handle
	lea	$10dc(a6),a0                    ; int_in
	move.w	d0,(a0)+                        ; int_in[0] = handle
	move.w	#$2,(a0)+                       ; wind_set WF_NAME
	move.l	d7,(a0)+                        ; title address
	moveq	#105,d0                         ; wind_set

open_call_xaes_name:
	dc.w	$6100,$0000                     ; bsr.w open_call_xaes_name+2 -> Xaes (filled in by the linker), call
                                                ;   Xaes
	move.w	#$3,$10de(a6)                   ; wind_set WF_INFO
	addi.l	#$140,$10e0(a6)                 ; info line address: 320 bytes on
	moveq	#105,d0                         ; wind_set

open_call_xaes_info:
	dc.w	$6100,$0000                     ; bsr.w open_call_xaes_info+2 -> Xaes (filled in by the linker), call
                                                ;   Xaes
	movea.l	(sp)+,a0                        ; -> x, y, w, h
	lea	$10de(a6),a1                    ; int_in[1..4]
	move.l	(a0)+,(a1)+                     ; x, y
	move.l	(a0)+,(a1)+                     ; w, h
	moveq	#101,d0                         ; wind_open
	bra.s	window_aes_call

;------------------------------------------------------------------------------
; The window is open: sets its attributes (WF_KIND) and rectangle (WF_CURRXYWH), then tops it.
; Entry: a0 -> table entry + 2, d1 = handle
;------------------------------------------------------------------------------
open_window_update:
	move.w	d1,-(sp)                        ; keep the handle
	move.w	#$1,d2                          ; WF_KIND
	move.w	(a0)+,d3                        ; wind_set WF_KIND
	pea	(a0)                            ; keep -> x, y, w, h

update_call_wind_set_kind:
	dc.w	$6100,$0000                     ; bsr.w update_call_wind_set_kind+2 -> WIND_SET (filled in by the
                                                ;   linker), call WIND_SET
	movea.l	(sp)+,a0                        ; -> x, y, w, h
	move.w	(sp)+,d1                        ; handle
	moveq	#5,d2                           ; WF_CURRXYWH
	movem.w	(a0),d3-d6                      ; x, y, w, h
	move.w	d6,d0                           ; h

update_call_wind_set_rect:
	dc.w	$6100,$0000                     ; bsr.w update_call_wind_set_rect+2 -> WIND_SET (filled in by the
                                                ;   linker), wind_set WF_CURRXYWH
	move.w	$117c(a6),$10dc(a6)             ; handle from WIND_SET's int_in[0] into int_in[0]

;------------------------------------------------------------------------------
; Brings the window whose handle is in int_in[0] to the top (wind_set WF_TOP) and makes it the output window.
;------------------------------------------------------------------------------
top_window:
	move.w	#$a,$10de(a6)                   ; int_in[1] = WF_TOP

;------------------------------------------------------------------------------
; wind_set with int_in already filled, then makes the window the output window.
;------------------------------------------------------------------------------
window_set_call:
	moveq	#105,d0                         ; wind_set

;------------------------------------------------------------------------------
; Makes the AES call in d0 and makes the window in int_in[0] the output window.
;------------------------------------------------------------------------------
window_aes_call:
	dc.w	$6100,$0000                     ; bsr.w	window_aes_call+2 -> Xaes (filled in by the linker), call Xaes
	move.w	$10dc(a6),d0                    ; handle from int_in[0]

;------------------------------------------------------------------------------
; Makes a window the output for graphics and text: reads its work area (wind_get WF_WORKXYWH) and sets the graphics
; origin, the text window and the clipping to it.
; Entry: d0 = window handle (0 = desktop)
;------------------------------------------------------------------------------
select_output_window:
	move.w	d0,d1                           ; handle
	moveq	#4,d0                           ; WF_WORKXYWH

select_output_call_wind_get:
	dc.w	$6100,$0000                     ; bsr.w select_output_call_wind_get+2 -> WIND_GET (filled in by the
                                                ;   linker), call WIND_GET: d1-d4 = work area

;------------------------------------------------------------------------------
; Sets the graphics origin to the window corner, turns the text window on and the ESC flag off, then the clipping.
; Entry: d1-d4 = x, y, w, h
;------------------------------------------------------------------------------
set_window_origin:
	movem.w	d1-d2,$125c(a6)                 ; graphics origin at the corner
	st	$1260(a6)                       ; text window on
	st	$1290(a6)                       ; no ESC pending

;------------------------------------------------------------------------------
; Keeps a work rectangle for the text window and clips to it.
; Entry: d1-d4 = x, y, w, h
;------------------------------------------------------------------------------
set_clip_rect:
	movem.w	d1-d4,$127c(a6)                 ; text window x, y, w, h
	subq.w	#1,d3                           ; to corner coordinates
	subq.w	#1,d4
	add.w	d1,d3
	add.w	d2,d4

;------------------------------------------------------------------------------
; Keeps the clipping rectangle and sets it with vs_clip.
; Entry: d1-d4 = x1, y1, x2, y2
;------------------------------------------------------------------------------
set_clip_and_save:
	movem.w	d1-d4,$1284(a6)                 ; keep the clipping rectangle
	move.w	d4,d0                           ; y2

set_clip_jump_clipxyxy:
	dc.w	$6000,$0000                     ; bra.w set_clip_jump_clipxyxy+2 -> CLIPXYXY (filled in by the linker),
                                                ;   tail call CLIPXYXY

;------------------------------------------------------------------------------
; TOPW n: brings window n (1-4) to the top if it is open.
; Entry: d0 = window number
;------------------------------------------------------------------------------
top_window_number:
	subq.w	#1,d0
	bmi.s	.done                           ; n = 0: nothing
	andi.w	#$3,d0                          ; windows 1-4
	mulu.w	#$c,d0                          ; 12 bytes a window
	lea	$121c(a6),a0                    ; window table
	move.w	0(a0,d0.l),$10dc(a6)            ; int_in[0] = handle
	bne.s	top_window                      ; open: top it
.done:
	rts

;------------------------------------------------------------------------------
; CLOSEW for all four windows, then the full clipping rectangle and a fresh window table.
;------------------------------------------------------------------------------
close_all_windows:
	moveq	#3,d0                           ; four windows
.next_window:
	move.w	d0,-(sp)                        ; keep the counter
	bsr.s	close_window_entry              ; close it
	move.w	(sp)+,d0                        ; counter back
	dbra	d0,.next_window                 ; all four
	movem.w	$1284(a6),d1-d4                 ; saved clipping rectangle
	bsr.s	set_window_origin               ; as the output area
	bra.w	init_window_table               ; fresh window table

;------------------------------------------------------------------------------
; CLOSEW n: closes window n (1-4); n = 0 gives the full screen back as output.
; Entry: d0 = window number
;------------------------------------------------------------------------------
close_window:
	subq.w	#1,d0
	bmi.s	reset_full_screen_output        ; n = 0: the full screen
	andi.w	#$3,d0                          ; windows 1-4

;------------------------------------------------------------------------------
; Closes and deletes the window of a table entry and makes the top window the output window, or the full screen when
; none is left.
; Entry: d0 = window number - 1
;------------------------------------------------------------------------------
close_window_entry:
	mulu.w	#$c,d0                          ; 12 bytes a window
	lea	$121c(a6),a0                    ; window table
	adda.l	d0,a0
	move.w	(a0),d0                         ; handle
	beq.s	close_find_top                  ; not open
	clr.w	(a0)                            ; mark it closed
	move.w	d0,$10dc(a6)                    ; int_in[0] = handle

close_call_wind_close:
	dc.w	$6100,$0000                     ; bsr.w close_call_wind_close+2 -> WIND_CLO (filled in by the linker),
                                                ;   wind_close
	moveq	#103,d0                         ; wind_delete

close_call_wind_delete:
	dc.w	$6100,$0000                     ; bsr.w close_call_wind_delete+2 -> Xaes (filled in by the linker), call
                                                ;   Xaes

;------------------------------------------------------------------------------
; Makes the top window the output window, or the full screen when none is open.
;------------------------------------------------------------------------------
close_find_top:
	moveq	#10,d0                          ; wind_get WF_TOP

close_call_wind_get_top:
	dc.w	$6100,$0000                     ; bsr.w close_call_wind_get_top+2 -> WIND_GET (filled in by the linker),
                                                ;   call WIND_GET: d0 = top window
	tst.w	d0                              ; one is open?
	bne.w	select_output_window            ; make it the output

;------------------------------------------------------------------------------
; Gives the whole screen back as output: no text window, origin 0,0, clipping from the saved rectangle.
;------------------------------------------------------------------------------
reset_full_screen_output:
	moveq	#0,d0                           ; handle 0: the desktop
	bsr.w	select_output_window            ; work area, origin and clipping
	sf	$1260(a6)                       ; text window off
	clr.l	$125c(a6)                       ; graphics origin 0,0
	movem.w	$1284(a6),d1-d4                 ; saved clipping rectangle
	moveq	#0,d1                           ; from 0,0
	moveq	#0,d2
	bra.w	set_clip_and_save               ; set it
	rts                                     ; not reached

;------------------------------------------------------------------------------
; Writes text into the output window as the text window, one character at a time with v_gtext at the window cursor. In
; output mode 2 CR, LF, BEL and BS are handled, ESC E clears the window and ESC p / ESC q set and clear bit 3 of the
; text effects; in any other mode every character is drawn as it is. At the bottom the window scrolls up.
; Entry: a1 = text, d0.l = length, d6 = output mode
;------------------------------------------------------------------------------
window_print:
	pea	(a3)                            ; keep a3
	movea.l	a1,a3                           ; a3 = text
	move.l	d0,d7                           ; d7 = length
	cmpi.w	#$2,d6                          ; other than mode 2: control characters drawn as they are
	sne	$1261(a6)                       ; flag set: draw everything
	move.w	$1294(a6),d4                    ; character cell width and height
	move.w	$1296(a6),d5
	movem.w	$1280(a6),d0-d1                 ; text area width and height
	move.w	$128c(a6),d2                    ; cursor column
	addq.w	#1,d2                           ; cursor still inside the width?
	mulu.w	d4,d2
	cmp.w	d0,d2
	bls.s	.check_row                      ; fits
	clr.w	$128c(a6)                       ; column 0
	bsr.w	window_next_line                ; next line
	movem.w	$1280(a6),d0-d1                 ; width and height again
.check_row:
	move.w	$128e(a6),d2                    ; cursor row
	addq.w	#1,d2                           ; still inside the height?
	mulu.w	d5,d2
	cmp.w	d1,d2
	bls.s	window_print_start              ; fits
	divu.w	d5,d1                           ; rows that fit
	subq.w	#1,d1                           ; the last one
	move.w	d1,$128e(a6)                    ; cursor to the last row
	bra.s	window_print_start              ; start

;------------------------------------------------------------------------------
; Next character of window_print.
; Entry: a3 -> text, d7 = characters left (dbra count, high word for more than 65536)
;------------------------------------------------------------------------------
window_print_next_char:
	moveq	#0,d0                           ; next character
	move.b	(a3)+,d0
	tst.b	$1261(a6)                       ; draw everything?
	bne.s	window_print_draw_char          ; yes
	tas	$1290(a6)                       ; after an ESC?
	bmi.s	window_print_control            ; no ESC: normal character
	cmpi.b	#$45,d0                         ; ESC E: clear
	beq.s	window_print_clear
	move.w	$1292(a6),d1                    ; text effects
	bset	#$3,d1                          ; underline on for ESC p
	cmpi.b	#$70,d0                         ; ESC p?
	beq.s	.set_effects
	bclr	#$3,d1                          ; underline off for ESC q
	cmpi.b	#$71,d0                         ; ESC q?
	bne.s	window_print_continue           ; other: ignored
.set_effects:
	move.w	d1,$1292(a6)                    ; keep the effects
	move.w	d1,$6a0(a6)                     ; intin[0]
	moveq	#106,d0                         ; vst_effects
	moveq	#1,d1                           ; one intin word
	moveq	#0,d2                           ; no points

window_print_call_vst_effects:
	dc.w	$6100,$0000                     ; bsr.w window_print_call_vst_effects+2 -> Xvdi (filled in by the
                                                ;   linker), call Xvdi

;------------------------------------------------------------------------------
; Enters the character loop.
;------------------------------------------------------------------------------
window_print_start:
	bra.s	window_print_continue           ; into the loop

;------------------------------------------------------------------------------
; ESC E: clears the window text and goes on.
;------------------------------------------------------------------------------
window_print_clear:
	bsr.w	clear_window_text               ; ESC E: clear the window
	bra.s	window_print_continue           ; next character

;------------------------------------------------------------------------------
; No ESC pending: control characters are handled, the rest drawn.
; Entry: d0 = character
;------------------------------------------------------------------------------
window_print_control:
	cmpi.b	#$20,d0                         ; printable?
	bcc.s	window_print_draw_char          ; yes: draw it
	cmpi.b	#$1b,d0                         ; ESC: the next character is a command
	sne	$1290(a6)                       ; ESC: flag 0 = ESC pending
	beq.s	window_print_continue           ; ESC: next character
	cmpi.b	#$d,d0                          ; CR?
	beq.s	window_print_return
	cmpi.b	#$a,d0                          ; LF?
	beq.s	window_print_line_feed
	cmpi.b	#$7,d0                          ; BEL?
	beq.s	window_print_bell
	cmpi.b	#$8,d0                          ; BS?
	bne.s	window_print_count              ; other control characters ignored
	subq.w	#1,$128c(a6)                    ; BS: one column back
	bpl.s	window_print_continue           ; still on the line
	clr.w	$128c(a6)                       ; not before column 0

;------------------------------------------------------------------------------
; Goes on with the next character.
;------------------------------------------------------------------------------
window_print_continue:
	bra.s	window_print_count              ; next character

;------------------------------------------------------------------------------
; Draws the character at the cursor with v_gtext (baseline at the bottom of the cell) and moves the cursor on,
; to the next line at the right edge.
; Entry: d0 = character, d4/d5 = cell width/height
;------------------------------------------------------------------------------
window_print_draw_char:
	move.w	d0,$6a0(a6)                     ; intin[0] = character
	move.w	$128c(a6),d0                    ; column
	mulu.w	d4,d0                           ; times cell width
	add.w	$125c(a6),d0                    ; plus the window origin x
	move.w	d0,$7a0(a6)                     ; ptsin[0] = x
	move.w	$128e(a6),d0                    ; row
	addq.w	#1,d0                           ; bottom of the cell
	mulu.w	d5,d0
	subq.w	#1,d0                           ; last pixel row of the cell
	add.w	$125e(a6),d0                    ; plus the window origin y
	move.w	d0,$7a2(a6)                     ; ptsin[1] = y
	moveq	#8,d0                           ; v_gtext
	moveq	#1,d1                           ; one intin word
	moveq	#1,d2                           ; one point

window_print_call_v_gtext:
	dc.w	$6100,$0000                     ; bsr.w window_print_call_v_gtext+2 -> Xvdi (filled in by the linker),
                                                ;   call Xvdi
	addq.w	#1,$128c(a6)                    ; column + 1
	move.w	d4,d0                           ; start of the next column
	mulu.w	$128c(a6),d0
	cmp.w	$1280(a6),d0                    ; still inside the width?
	bcs.s	window_print_count              ; yes
	clr.w	$128c(a6)                       ; wrap to column 0

;------------------------------------------------------------------------------
; LF: next line.
;------------------------------------------------------------------------------
window_print_line_feed:
	bsr.s	window_next_line                ; next line

;------------------------------------------------------------------------------
; Counts the characters down.
;------------------------------------------------------------------------------
window_print_count:
	dbra	d7,window_print_next_char       ; next character
	subi.l	#$10000,d7                      ; high word of the count
	bpl.w	window_print_next_char          ; more blocks of 65536
	movea.l	(sp)+,a3                        ; a3 back
	rts

;------------------------------------------------------------------------------
; CR: back to the first column.
;------------------------------------------------------------------------------
window_print_return:
	clr.w	$128c(a6)                       ; CR: column 0
	bra.s	window_print_count              ; next character

;------------------------------------------------------------------------------
; BEL: rings the bell (Bconout to the console).
;------------------------------------------------------------------------------
window_print_bell:
	move.w	#$7,-(sp)                       ; BEL
	pea	$30002                          ; Bconout, device 2: console
	trap	#13                             ; BIOS
	addq.l	#6,sp                           ; drop the arguments
	bra.s	window_print_count              ; next character

;------------------------------------------------------------------------------
; Moves the text window cursor to the next row; past the last row the cursor stays and the window scrolls up one line.
;------------------------------------------------------------------------------
window_next_line:
	addq.w	#1,$128e(a6)                    ; row + 1
	move.w	d5,d6                           ; cell height
	mulu.w	$128e(a6),d6                    ; times the row
	subq.w	#1,d6                           ; one less, plus a row:
	add.w	d5,d6                           ; the bottom of the new row
	sub.w	$1282(a6),d6                    ; past the text area height?
	bcs.s	.done                           ; no: fits
	subq.w	#1,$128e(a6)                    ; stay on the last row
	bra.w	scroll_window_text              ; and scroll up
.done:
	rts

;------------------------------------------------------------------------------
; Clears every visible part of window n through its rectangle list (wind_get WF_FIRSTXYWH / WF_NEXTXYWH) inside
; wind_update.
; Entry: d0 = window number
;------------------------------------------------------------------------------
clear_window_rectangles:
	subq.w	#1,d0
	bmi.s	clear_window_skip               ; n = 0: nothing
	andi.w	#$3,d0                          ; windows 1-4
	mulu.w	#$c,d0                          ; 12 bytes a window
	lea	$121c(a6),a0                    ; window table
	adda.l	d0,a0
	lea	$10dc(a6),a1                    ; int_in (not used further)
	move.w	(a0),d0                         ; handle
	beq.s	clear_window_skip               ; not open: nothing
	move.w	d0,-(sp)                        ; keep it
	bsr.s	begin_window_update             ; lock the screen
	move.w	(sp)+,$10dc(a6)                 ; int_in[0] = handle
	moveq	#11,d0                          ; WF_FIRSTXYWH

;------------------------------------------------------------------------------
; Reads the next rectangle of the list and clears it; an empty one ends the list.
; Entry: d0 = WF_FIRSTXYWH or WF_NEXTXYWH, handle in int_in[0]
;------------------------------------------------------------------------------
clear_rects_next:
	move.w	$10dc(a6),d1                    ; handle

clear_rects_call_wind_get:
	dc.w	$6100,$0000                     ; bsr.w clear_rects_call_wind_get+2 -> WIND_GET (filled in by the
                                                ;   linker), call WIND_GET
	movem.w	$11a6(a6),d4-d7                 ; rectangle x, y, w, h
	move.w	d7,d3                           ; empty?
	or.w	d6,d3
	beq.s	.done                           ; yes: end of the list
	bsr.s	blit_clear_rect                 ; clear it
	moveq	#12,d0                          ; WF_NEXTXYWH
	bra.s	clear_rects_next
.done:
	moveq	#0,d0                           ; wind_update 0: unlock
	bra.s	window_update_call              ; through WIND_UPD

;------------------------------------------------------------------------------
; wind_update(1): screen locked for drawing.
;------------------------------------------------------------------------------
begin_window_update:
	moveq	#1,d0

window_update_call:
	dc.w	$6000,$0000                     ; bra.w window_update_call+2 -> WIND_UPD (filled in by the linker), tail
                                                ;   call WIND_UPD

clear_window_skip:
	rts

;------------------------------------------------------------------------------
; CLEARW n: tops window n and clears its work area; the text cursor goes to the top left.
; Entry: d0 = window number
;------------------------------------------------------------------------------
clear_window:
	clr.l	$128c(a6)                       ; cursor to column 0, row 0
	subq.w	#1,d0                           ; n = 0: nothing
	bmi.s	blit_skip
	andi.w	#$3,d0                          ; windows 1-4
	mulu.w	#$c,d0                          ; 12 bytes a window
	lea	$121c(a6),a0                    ; window table
	adda.l	d0,a0
	move.w	(a0),$10dc(a6)                  ; int_in[0] = handle
	bsr.w	top_window                      ; top it, make it the output
	move.w	#$b,$10de(a6)                   ; wind_get WF_WORKXYWH
	moveq	#104,d0                         ; wind_get

clear_window_call_xaes:
	dc.w	$6100,$0000                     ; bsr.w clear_window_call_xaes+2 -> Xaes (filled in by the linker), call
                                                ;   Xaes
	movem.w	$1106(a6),d4-d7                 ; int_out[1..4]: x, y, w, h
	bra.s	blit_clear_rect                 ; clear it

;------------------------------------------------------------------------------
; ESC E in the text window: the cursor to the top left and the clipped area cleared with vro_cpyfm (mode 0) on the
; screen.
;------------------------------------------------------------------------------
clear_window_text:
	moveq	#0,d0                           ; cursor 0,0
	move.l	d0,$128c(a6)
	move.l	#$7fff7fff,d1                   ; 32767, 32767
	move.l	d0,d2
	move.l	d1,d3
	movem.l	d0-d3,$7a0(a6)                  ; whole screen as source and destination
	lea	null_screen_mfdb(pc),a0
	move.l	a0,$648(a6)                     ; contrl[7..10]: both MFDBs the screen
	move.l	a0,$64c(a6)
	clr.w	$6a0(a6)                        ; intin[0] = 0: all white
	moveq	#109,d0                         ; vro_cpyfm
	moveq	#1,d1                           ; one intin word
	moveq	#4,d2                           ; four ptsin pairs

clear_text_jump_xvdi:
	dc.w	$6000,$0000                     ; bra.w clear_text_jump_xvdi+2 -> Xvdi (filled in by the linker), tail
                                                ;   call Xvdi

; A zero long used as the MFDB of the screen.
null_screen_mfdb:
	dc.w	$0000,$0000

;------------------------------------------------------------------------------
; Clears a rectangle with a Line-A bit block transfer, run in supervisor mode with the mouse hidden.
; Entry: d4-d7 = x, y, w, h
;------------------------------------------------------------------------------
blit_clear_rect:
	pea	blit_clear_super(pc)            ; supervisor routine
	dc.w	$a00a                           ; Line-A Hide mouse
	move.w	#$26,-(sp)                      ; Supexec
	trap	#14                             ; Supexec
	addq.l	#6,sp                           ; drop the arguments

blit_skip:
	rts

;------------------------------------------------------------------------------
; Supervisor part of blit_clear_rect: fills the Line-A BITBLT block at $7a0(a6) and calls $a007. a6 points at that block
; here, so the a6 field names in this routine stand for BITBLT offsets.
;------------------------------------------------------------------------------
blit_clear_super:
	movea.l	$32(a6),a0                      ; Line-A variables
	lea	$7a0(a6),a6                     ; a6 -> BITBLT block
	tst.w	d6                              ; no width
	ble.s	.done
	tst.w	d7                              ; no height
	ble.s	.done
	movem.w	d6-d7,(a6)                      ; b_wd, b_ht
	move.l	$44e.w,d0                       ; _v_bas_ad
	move.l	d0,$12(a6)                      ; s_form: the screen
	move.l	d0,$20(a6)                      ; d_form ($20)
	moveq	#0,d0
	move.l	d0,$2a(a6)                      ; p_addr: no pattern
	move.l	d0,6(a6)                        ; fg_col, bg_col
	move.l	d0,$a(a6)                       ; op_tab: all 0, clear
	movem.w	d4-d5,$e(a6)                    ; s_xmin, s_ymin ($e)
	movem.w	d4-d5,$1c(a6)                   ; d_xmin, d_ymin ($1c)
	move.w	-$c(a0),d0                      ; horizontal resolution
	movem.w	-$4(a0),d1-d3                   ; vertical resolution, bytes per line, planes
	move.w	d2,$18(a6)                      ; s_nxln ($18)
	move.w	d2,$26(a6)                      ; d_nxln
	move.w	d3,4(a6)                        ; plane_ct
	add.w	d3,d3
	move.w	d3,$16(a6)                      ; s_nxwd
	move.w	d3,$24(a6)                      ; d_nxwd ($24)
	moveq	#2,d2
	cmp.w	d2,d3
