; Entry: d0-d2 = x
; Exit: through MKLSTR (a 4-byte temporary string)
;------------------------------------------------------------------------------
MKSSTR:
	ext.l	d2                              ; keep the sign in the high word
	bpl.s	.magnitude                      ; positive
	neg.w	d2                              ; magnitude
.magnitude:
	subi.w	#$3be,d2                        ; rebias for the 7-bit exponent
	bpl.s	.clamp_high                     ; in range at the bottom
	moveq	#0,d2                           ; too small: 0
	moveq	#0,d0
	moveq	#0,d1
.clamp_high:
	cmpi.w	#$7f,d2                         ; fits in 7 bits?
	bls.s	.sign
	move.w	#$7f,d2                         ; too large: largest exponent
	moveq	#-1,d0                          ; and all mantissa bits set
	moveq	#-1,d1
.sign:
	tst.l	d2                              ; negative number?
	bpl.s	.store_exponent
	ori.b	#$80,d2                         ; sign bit
.store_exponent:
	move.b	d2,d0                           ; exponent byte in place of the lowest mantissa byte

mks_jump_mklstr:
	dc.w	$6000,$0000                     ; bra.w mks_jump_mklstr+2 -> MKLSTR (filled in by the linker), tail call
                                                ;   MKLSTR

;------------------------------------------------------------------------------
; MKD$(x): x as an 8-byte string in the runtime's own float format.
; Entry: d0-d2 = x
; Exit: a0 = temporary descriptor, d0.l = its address
;------------------------------------------------------------------------------
MKDSTR:
	move.w	d2,-(sp)                        ; exponent
	move.w	d1,-(sp)                        ; mantissa low
	move.l	d0,d7                           ; mantissa high
	moveq	#8,d0                           ; 8 bytes

mkd_call_stcreat:
	dc.w	$6100,$0000                     ; bsr.w mkd_call_stcreat+2 -> STcreat (filled in by the linker), call
                                                ;   STcreat: a0 = descriptor, a1 = text
	move.l	d7,(a1)+                        ; mantissa high
	move.l	(sp)+,(a1)+                     ; mantissa low and exponent
	move.l	a0,d0                           ; descriptor address
	rts

;------------------------------------------------------------------------------
; MKF$(x): x as a 6-byte string: bit 31 the sign, the mantissa without its top bit, then a 10-bit exponent (the
; float exponent less $1ff) in the low bits of the last word. Too small gives exponent 0, too large all ones.
; Entry: d0-d2 = x
; Exit: a0 = temporary descriptor
;------------------------------------------------------------------------------
MKFSTR:
	neg.w	d2                              ; negate: positive numbers become negative
	bpl.s	.rebias                         ; negative or zero: keep bit 31 as the sign
	bclr	#$1f,d0                         ; positive: clear the top bit
	neg.w	d2                              ; magnitude again
.rebias:
	subi.w	#$1ff,d2                        ; rebias for the 10-bit exponent
	bpl.s	.clamp_high                     ; in range
	moveq	#0,d2                           ; too small: exponent 0
.clamp_high:
	cmpi.w	#$3ff,d2                        ; fits in 10 bits?
	bls.s	.pack
	moveq	#-1,d2                          ; too large: all ones
	ori.l	#$7fffffff,d0                   ; and all mantissa bits set (sign kept)
.pack:
	andi.w	#$fc00,d1                       ; top six bits of the low mantissa word
	or.w	d2,d1                           ; exponent in the low ten bits
	move.l	d0,d7                           ; mantissa high
	move.w	d1,-(sp)                        ; low word
	moveq	#6,d0                           ; 6 bytes

mkf_call_stcreat:
	dc.w	$6100,$0000                     ; bsr.w mkf_call_stcreat+2 -> STcreat (filled in by the linker), call
                                                ;   STcreat: a0 = descriptor, a1 = text
	move.l	d7,(a1)+                        ; mantissa high with the sign
	move.w	(sp)+,(a1)+                     ; low word with the exponent
	rts

;------------------------------------------------------------------------------
; CVF(a$): the 6-byte MKF$ format back to a float; 0 if the string is shorter or the exponent field is 0.
; Entry: a0 = string descriptor
; Exit: d0-d2 = value
;------------------------------------------------------------------------------
CVFSTR:
	dc.w	$6100,$0000                     ; bsr.w CVFSTR+2 -> LENSTR (filled in by the linker), call LENSTR: a0 =
                                                ;   text, d0 = length
	subq.w	#6,d0                           ; at least 6 bytes?
	bmi.s	cv_return_zero
	move.l	(a0)+,d0                        ; mantissa high with the sign
	move.w	(a0),d1                         ; low word with the exponent
	move.w	d1,d2                           ; exponent field
	andi.w	#$3ff,d2
	beq.s	cv_return_zero                  ; 0: zero
	sub.w	d2,d1                           ; clear it from the mantissa
	addi.w	#$1ff,d2                        ; float exponent
	tst.l	d0                              ; sign bit set?
	bpl.s	.set_top_bit
	neg.w	d2                              ; negative exponent for a negative number
.set_top_bit:
	bset	#$1f,d0                         ; the top mantissa bit
	rts

;------------------------------------------------------------------------------
; Returns 0 (exponent 0) for CVF and CVS.
;------------------------------------------------------------------------------
cv_return_zero:
	moveq	#0,d0                           ; mantissa 0
	moveq	#0,d2                           ; exponent 0: zero
	rts

;------------------------------------------------------------------------------
; CVS(a$): the 4-byte MKS$ format back to a float; 0 if the string is shorter. An exponent byte of 0 is not
; treated as zero: it gives exponent $3be with the mantissa as stored.
; Entry: a0 = string descriptor
; Exit: d0-d2 = value
;------------------------------------------------------------------------------
CVSSTR:
	dc.w	$6100,$0000                     ; bsr.w CVSSTR+2 -> LENSTR (filled in by the linker), call LENSTR: a0 =
                                                ;   text, d0 = length
	subq.w	#4,d0                           ; at least 4 bytes?
	bmi.s	cv_return_zero
	move.l	(a0),d0                         ; mantissa bytes and the exponent byte
	moveq	#0,d1
	moveq	#0,d2
	move.b	d0,d2                           ; exponent byte
	move.b	d1,d0                           ; lowest mantissa byte 0
	bclr	#$7,d2                          ; sign bit
	beq.s	.positive                       ; positive
	addi.w	#$3be,d2                        ; float exponent
	neg.w	d2                              ; negative number
	rts
.positive:
	addi.w	#$3be,d2                        ; float exponent
	rts

