	dc.b	$53,$54,$52,$49,$4e,$47,$2e,$4f,$00,$00,$00,$00,$00,$00	; library entry: the name STRING.O
	dc.w	$92f0,$12dd,$0000,$01b6,$0000,$0422,$0000	; entry: the rest (the member's length at +8)
