m_string:
;------------------------------------------------------------------------------
; Returns a new empty temporary string.
; Entry: none
; Exit: a0 = descriptor, d0 = 0
;------------------------------------------------------------------------------
string_empty:
	moveq	#0,d0                           ; length 0
	bra.s	string_temp_alloc               ; make it

;------------------------------------------------------------------------------
; Makes a temporary string of d0 bytes copied from a2.
; Entry: a2 = text, d0.w = length
; Exit: a0 = temporary descriptor
;------------------------------------------------------------------------------
string_from_buffer:
	bsr.s	string_temp_alloc               ; new temporary string
	bra.s	.count_byte                     ; enter the count
.copy_byte:
	move.b	(a2)+,(a1)+                     ; copy the text
.count_byte:
	dbra	d0,.copy_byte                   ; d0 bytes
	rts

;------------------------------------------------------------------------------
; Sets the string variable at a0 to the one character in d0.
; Entry: a0 = string descriptor, d0.b = character
; Exit: a1 = data
;------------------------------------------------------------------------------
string_var_set_byte:
	move.b	d0,d2                           ; room for one byte
	moveq	#1,d0                           ; one byte
	bsr.s	string_var_alloc                ; room for it
	move.b	d2,(a1)                         ; store it
	rts

;------------------------------------------------------------------------------
; Sets the string variable at a0 to the two bytes of d0 (MKI$, two-character constants).
; Entry: a0 = string descriptor, d0.w = bytes
; Exit: a1 = data
;------------------------------------------------------------------------------
string_var_set_word:
	move.w	d0,d2                           ; room for two bytes
	moveq	#2,d0                           ; two bytes
	bsr.s	string_var_alloc                ; room for them
	move.w	d2,(a1)                         ; store them
	rts

;------------------------------------------------------------------------------
; Sets the string variable at a0 to the four bytes of d0 (MKL$, four-character constants).
; Entry: a0 = string descriptor, d0.l = bytes
; Exit: a1 = data
;------------------------------------------------------------------------------
string_var_set_long:
	move.l	d0,d2                           ; room for four bytes
	moveq	#4,d0                           ; four bytes
	bsr.s	string_var_alloc                ; room for them
	move.l	d2,(a1)                         ; store them
	rts

;------------------------------------------------------------------------------
; a$="": sets the string variable at a0 to the empty string, freeing its data.
; Entry: a0 = string descriptor
; Exit: none
;------------------------------------------------------------------------------
string_var_clear:
	moveq	#0,d0                           ; length 0

;------------------------------------------------------------------------------
; Gives the string variable at a0 room for d0 bytes. A block of the same length is reused; otherwise the old block is
; marked free and a new one is taken from the bottom of the heap.
; Entry: a0 = string descriptor, d0.w = new length
; Exit: a1 = data area, descriptor updated; d1 changed
;------------------------------------------------------------------------------
string_var_alloc:
	move.w	4(a0),d1                        ; current length
	beq.s	string_heap_alloc               ; no block yet
	movea.l	(a0),a1                         ; current data
	cmp.w	d0,d1                           ; same length: reuse it
	beq.s	string_alloc_done               ; reuse the block
	addq.w	#1,d1                           ; round up to even
	andi.b	#$fe,d1
	adda.w	d1,a1                           ; its back pointer
	neg.w	d1                              ; negative size
	ext.l	d1                              ; as a long
	move.l	d1,(a1)                         ; marks the old block free

;------------------------------------------------------------------------------
; Takes a block for d0 bytes from the bottom of the string heap and links it to the descriptor at a0. Each block holds
; the data (rounded up to even) followed by a long pointer back to its descriptor. Collects garbage if the heap would
; meet the local stack.
; Entry: a0 = descriptor, d0.w = length
; Exit: a1 = data; error 8 if there is no room
;------------------------------------------------------------------------------
string_heap_alloc:
	movea.l	$22(a6),a1                      ; heap bottom
	moveq	#0,d1                           ; block size
	move.w	d0,d1                           ; length
	beq.s	string_set_empty                ; empty string needs no block
	addq.w	#5,d1                           ; data even + back pointer
	andi.b	#$fe,d1                         ; rounded down to even
	suba.l	d1,a1                           ; new block below the heap
	cmpa.l	a3,a1                           ; into the local stack?
	bcs.s	string_heap_full                ; yes: collect first

;------------------------------------------------------------------------------
; Stores the new block a1 in the descriptor at a0, writes the back pointer and makes it the new heap bottom.
; Entry: a0 = descriptor, a1 = block, d0 = length, d1 = block size
; Exit: a1 = data
;------------------------------------------------------------------------------
string_heap_link:
	move.l	a1,(a0)                         ; descriptor data
	move.w	d0,4(a0)                        ; descriptor length
	move.l	a0,-$4(a1,d1.l)                 ; back pointer to the descriptor
	move.l	a1,$22(a6)                      ; new heap bottom

;------------------------------------------------------------------------------
; Return point when the block is reused unchanged.
; Entry: none
; Exit: none
;------------------------------------------------------------------------------
string_alloc_done:
	rts

;------------------------------------------------------------------------------
; Sets the descriptor length to 0 without a heap block.
; Entry: a0 = descriptor, d0 = 0
; Exit: none
;------------------------------------------------------------------------------
string_set_empty:
	move.w	d0,4(a0)                        ; length 0, no block
	rts

;------------------------------------------------------------------------------
; Allocates a temporary string: finds a free descriptor in the table of 1000 at TEMP_DESCRIPTORS (free ones have a
; negative length) and gives it d0 bytes on the heap.
; Entry: d0.w = length
; Exit: a0 = descriptor, a1 = data; error 14 if all descriptors are in use
;------------------------------------------------------------------------------
string_temp_alloc:
	lea	$1374(a6),a0                    ; temporary descriptor table
	move.w	#$3e7,d1                        ; 1000 entries
.find_free:
	addq.l	#4,a0                           ; skip the data pointer
	tst.w	(a0)+                           ; negative length = free
	dbmi	d1,.find_free                   ; until one is free or all tried
	bpl.s	.none_free                      ; none free
	subq.l	#6,a0                           ; back to the descriptor
	bra.s	string_heap_alloc               ; give it the data
.none_free:
	moveq	#14,d0                          ; too many temporary strings

string_temp_jump_error:
	dc.w	$6000,$0000                     ; bra.w string_temp_jump_error+2 -> ERROR (filled in by the linker),
                                                ;   tail call ERROR

