string_heap_full:
	bsr.s	string_collect                  ; collect garbage
	movea.l	$22(a6),a1                      ; heap bottom
	suba.l	d1,a1                           ; new block below the heap
	cmpa.l	a3,a1                           ; room now?
	bcc.s	string_heap_link                ; yes: link it
	moveq	#8,d0                           ; out of memory

string_heap_jump_error:
	dc.w	$6000,$0000                     ; bra.w string_heap_jump_error+2 -> ERROR (filled in by the linker),
                                                ;   tail call ERROR

;------------------------------------------------------------------------------
; Makes a one-character temporary string from d0 (CHR$).
; Entry: d0.b = character
; Exit: a0 = descriptor, a1 = data
;------------------------------------------------------------------------------
string_temp_byte:
	move.b	d0,-(sp)                        ; keep the character
	moveq	#1,d0                           ; one byte
	bsr.s	string_temp_alloc               ; make it
	move.b	(sp)+,(a1)                      ; store it
	rts

;------------------------------------------------------------------------------
; Makes a two-byte temporary string from d0 (MKI$ and two-character constants).
; Entry: d0.w = bytes
; Exit: a0 = descriptor, a1 = data
;------------------------------------------------------------------------------
string_temp_word:
	move.w	d0,-(sp)                        ; keep the bytes
	moveq	#2,d0                           ; two bytes
	bsr.s	string_temp_alloc               ; make it
	move.w	(sp)+,(a1)                      ; store them
	rts

;------------------------------------------------------------------------------
; Makes a four-byte temporary string from d0 (MKL$ and four-character constants).
; Entry: d0.l = bytes
; Exit: a0 = descriptor, a1 = data
;------------------------------------------------------------------------------
string_temp_long:
	move.l	d0,-(sp)                        ; keep the bytes
	moveq	#4,d0                           ; four bytes
	bsr.s	string_temp_alloc               ; make it
	move.l	(sp)+,(a1)                      ; store them
	rts

;------------------------------------------------------------------------------
; Garbage collection of the string heap: walks the blocks from the top of memory down, drops the free ones (negative
; back pointer) and moves the live ones up, updating their descriptors, then sets the new heap bottom.
; Entry: none
; Exit: all registers kept
;------------------------------------------------------------------------------
string_collect:
	movem.l	d0-d7/a0-a3,-(sp)               ; keep everything
	movea.l	$26(a6),a0                      ; top of the heap
	movea.l	$22(a6),a2                      ; heap bottom
.scan_block:
	movea.l	a0,a1                           ; destination = here while nothing moved
	cmpa.l	a0,a2                           ; whole heap done?
	beq.s	.done
	move.l	-(a0),d0                        ; back pointer of the block below
	bmi.s	.skip_free                      ; free block
	movea.l	d0,a3                           ; live: its descriptor
	movea.l	(a3),a0                         ; block start, stays in place
	bra.s	.scan_block                     ; go on below it
.skip_free:
	adda.l	d0,a0                           ; skip the free block
	cmpa.l	a0,a2                           ; reached the bottom?
	beq.s	.set_bottom
.next_block:
	move.l	-(a0),d0                        ; next back pointer
	bmi.s	.skip_free                      ; free: skip it
	move.l	d0,-(a1)                        ; move the back pointer
	movea.l	d0,a3                           ; descriptor
	move.w	4(a3),d0                        ; length
	lsr.w	#1,d0                           ; copy the data down to up in sizes
	bcc.s	.copy_second_word
	move.w	-(a0),-(a1)                     ; odd: one word (rounds up)
.copy_second_word:
	lsr.w	#1,d0
	bcc.s	.copy_long
	move.w	-(a0),-(a1)                     ; bit 1: one more word
.copy_long:
	lsr.w	#1,d0
	bcc.s	.copy_eight
	move.l	-(a0),-(a1)                     ; bit 2: a long
.copy_eight:
	lsr.w	#1,d0
	bcc.s	.copy_sixteen
	move.l	-(a0),-(a1)                     ; bit 3: eight bytes
	move.l	-(a0),-(a1)
.copy_sixteen:
	lsr.w	#1,d0
	bcc.s	.copy_blocks
	move.l	-(a0),-(a1)                     ; bit 4: sixteen bytes
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
	move.l	-(a0),-(a1)
.copy_blocks:
	lsr.w	#1,d0                           ; the rest in 32-byte blocks
	bcc.s	.count_blocks
	bra.s	.copy_block                     ; odd count: start in the middle
.copy_pair:
	move.l	-(a0),-(a1)                     ; copy 32 bytes
	lea	-$1c(a0),a0                     ; seven more longs
	movem.l	(a0),d1-d7
	movem.l	d1-d7,-(a1)
.copy_block:
	move.l	-(a0),-(a1)                     ; copy 32 bytes
	lea	-$1c(a0),a0                     ; seven more longs
	movem.l	(a0),d1-d7
	movem.l	d1-d7,-(a1)
.count_blocks:
	dbra	d0,.copy_pair                   ; 64-byte blocks
	move.l	a1,(a3)                         ; new data address in the descriptor
	cmpa.l	a0,a2                           ; more blocks?
	bne.s	.next_block                     ; yes
.set_bottom:
	move.l	a1,$22(a6)                      ; new heap bottom
.done:
	movem.l	(sp)+,d0-d7/a0-a3               ; restore everything
	rts

;------------------------------------------------------------------------------
; FRE: collects garbage first, then returns the free memory.
; Entry: none
; Exit: d0.l = free bytes
;------------------------------------------------------------------------------
fre_after_collect:
	bsr.w	string_collect                  ; collect garbage

;------------------------------------------------------------------------------
; FRE: free bytes between the local stack and the bottom of the string heap.
; Entry: a3 = local stack top
; Exit: d0.l = free bytes
;------------------------------------------------------------------------------
fre:
	move.l	$22(a6),d0                      ; heap bottom
	sub.l	a3,d0                           ; less the local stack top
	rts

;------------------------------------------------------------------------------
; Like string_unlink, but an empty string gets a pointer to two zero words instead of its own data, so the result can
; always be read.
; Entry: a0 = string descriptor
; Exit: a1 = data, d1.w = length
;------------------------------------------------------------------------------
string_fetch_safe:
	bsr.s	string_unlink                   ; fetch the string
	tst.w	d1                              ; empty?
	bne.s	.done
	lea	empty_string_data(pc),a1        ; point at zero words
.done:
	rts

; Two zero words used as the data of an empty string.
empty_string_data:
	dc.w	$0000,$0000

;------------------------------------------------------------------------------
; Fetches a string operand into a1/d1 and frees it if it is a temporary descriptor (the heap block is marked free but
; the heap bottom is not moved).
; Entry: a0 = string descriptor
; Exit: a1 = data, d1.w = length, a0 = descriptor length field; d3-d4 changed
;------------------------------------------------------------------------------
string_unlink:
	movea.l	(a0)+,a1                        ; data
	move.w	(a0),d1                         ; length
	cmpa.l	a6,a0                           ; below a6: a variable
	bcs.s	.done
	cmpa.l	sp,a0                           ; above sp: a variable
	bhi.s	.done
	st	(a0)                            ; free the temporary descriptor
	move.w	d1,d3                           ; length
	beq.s	.done                           ; empty: no block
	ext.l	d3                              ; as a long
	addq.w	#1,d3                           ; round up to even
	andi.b	#$fe,d3                         ; rounded down to even
	move.l	d3,d4                           ; size
	neg.l	d3                              ; negative size
	move.l	d3,0(a1,d4.l)                   ; marks the block free
.done:
	rts

