	moveq	#-1,d0                          ; length counter
.find_end:
	addq.w	#1,d0                           ; count up to the CR
	cmpi.b	#$d,(a1)+                       ; CR?
	bne.s	.find_end                       ; no: on
	movea.l	(sp)+,a0                        ; the variable

line_input_call_screat:
	dc.w	$6100,$0000                     ; bsr.w line_input_call_screat+2 -> Screat (filled in by the linker),
                                                ;   call Screat: a1 = its text (d0 bytes)
	lsr.w	#1,d0                           ; odd length: one word (rounds up)
	bcc.s	.copy_long
	move.w	(a2)+,(a1)+
.copy_long:
	lsr.w	#1,d0                           ; bit 1: one more word
	bcc.s	.count_longs
	move.w	(a2)+,(a1)+
	bra.s	.count_longs
.copy_loop:
	move.l	(a2)+,(a1)+                     ; rest in longs
.count_longs:
	dbra	d0,.copy_loop
	rts

line_input_jump_lineinp:
	dc.w	$6000,$0000                     ; bra.w line_input_jump_lineinp+2 -> LINEINP (filled in by the linker),
                                                ;   tail call LINEINP

;------------------------------------------------------------------------------
; Reads one line from the current input channel into the text buffer at $46(a6), up to LF or 255 characters; the last
; character stored becomes CR.
; Exit: line in the text buffer ending in CR
;------------------------------------------------------------------------------
read_input_line:
	move.w	$44(a6),d6                      ; current channel
	pea	(a3)                            ; keep a3
	lea	$46(a6),a3                      ; text buffer
.next_char:
	bsr.w	input_get_char                  ; next character
	move.b	d0,(a3)+                        ; store it
	lea	$145(a6),a0                     ; buffer full?
	cmpa.l	a0,a3
	beq.s	.end_line                       ; full: end the line
	cmpi.b	#$a,d0                          ; LF?
	bne.s	.next_char                      ; no: on
.end_line:
	move.b	#$d,-(a3)                       ; last character becomes CR
	movea.l	(sp)+,a3                        ; a3 back
	rts

;------------------------------------------------------------------------------
; INPUT into an integer variable: the number read, truncated to a long.
; Exit: d0.l = value
;------------------------------------------------------------------------------
input_integer:
	bsr.s	input_number                    ; read a number

input_integer_jump_fftoi:
	dc.w	$6000,$0000                     ; bra.w input_integer_jump_fftoi+2 -> FFTOI (filled in by the linker),
                                                ;   tail call FFTOI

input_bell_skip:
	rts

;------------------------------------------------------------------------------
; Bad INPUT field: unless a break is pending, rings the bell and has the line read again.
;------------------------------------------------------------------------------
input_error_bell:
	btst	#$1,$1364(a6)                   ; break pending?
	bne.s	input_bell_skip                 ; yes: return

input_error_call_bell:
	dc.w	$6100,$0000                     ; bsr.w input_error_call_bell+2 -> BELL (filled in by the linker), call
                                                ;   BELL
	clr.l	input_next_field-m_fileinp      ; no field pending: read a new line

;------------------------------------------------------------------------------
; INPUT of one number: takes the next field of the current input line, reading a new line when needed (keyboard channels
; through the screen line editor, with the "? " prompt if wanted). A bad number from the keyboard is asked for again;
; from other channels it is error 35. input_integer converts the result to an integer.
; Entry: OUTPUT_CHANNEL = channel
; Exit: d0-d2 = float
;------------------------------------------------------------------------------
input_number:
	move.w	$1260(a6),$1372(a6)             ; keep the text window flag for the line editor
	move.w	$44(a6),d7                      ; current channel
	move.w	d7,d6                           ; channel for the readers
	bpl.s	input_number_from_device        ; file
	addq.w	#1,d7                           ; -1: screen
	beq.s	input_number_screen             ; line editor
	addq.w	#3,d7                           ; -4: console
	beq.s	input_number_console            ; line editor
	addq.w	#2,d7                           ; -6 .. -2: BIOS device
	bpl.s	input_number_from_device        ; read it directly
	moveq	#-1,d0                          ; below -6: error -1

input_number_jump_error:
	dc.w	$6000,$0000                     ; bra.w input_number_jump_error+2 -> ERROR (filled in by the linker),
                                                ;   tail call ERROR

;------------------------------------------------------------------------------
; File or BIOS device: reads one field into the text buffer; a field that is no number gives error 35.
;------------------------------------------------------------------------------
input_number_from_device:
	move.w	$44(a6),d6                      ; channel
	bsr.w	read_input_field                ; one field into the text buffer
	lea	$46(a6),a0                      ; text buffer
	bsr.w	parse_input_number              ; read the number
	tst.l	d7                              ; a number?
	bmi.s	.not_a_number                   ; no
	rts                                     ; yes
.not_a_number:
	moveq	#35,d0                          ; error 35

input_number_jump_error_35:
	dc.w	$6000,$0000                     ; bra.w input_number_jump_error_35+2 -> ERROR (filled in by the linker),
                                                ;   tail call ERROR

;------------------------------------------------------------------------------
; Console (-4): next field of the pending line, or a new line from GETLNC.
;------------------------------------------------------------------------------
input_number_console:
	movea.l	input_next_field(pc),a0         ; pending field
	move.l	a0,d0                           ; any?
	bne.s	input_number_parse              ; yes: use it
	bsr.s	print_input_prompt              ; "? " if wanted

input_number_call_getlnc:
	dc.w	$6100,$0000                     ; bsr.w input_number_call_getlnc+2 -> GETLNC (filled in by the linker),
                                                ;   call GETLNC: line into the text buffer
	bra.s	input_number_line_read          ; first field

;------------------------------------------------------------------------------
; Screen (-1): next field of the pending line, or a new line from GETLNV.
;------------------------------------------------------------------------------
input_number_screen:
	movea.l	input_next_field(pc),a0         ; pending field
	move.l	a0,d0                           ; any?
	bne.s	input_number_parse              ; yes: use it
	bsr.s	print_input_prompt              ; "? " if wanted

input_number_call_getlnv:
	dc.w	$6100,$0000                     ; bsr.w input_number_call_getlnv+2 -> GETLNV (filled in by the linker),
                                                ;   call GETLNV: line into the text buffer

;------------------------------------------------------------------------------
; A new line: its first field.
;------------------------------------------------------------------------------
input_number_line_read:
	lea	$46(a6),a0                      ; first field

;------------------------------------------------------------------------------
; Reads the number of the field at a0 and keeps where the next field starts (0 at the line end); a bad number
; rings the bell and asks again.
; Entry: a0 = field text
;------------------------------------------------------------------------------
input_number_parse:
	bsr.w	parse_input_number              ; read the number
	cmpi.b	#$d,(a0)+                       ; separator a CR: the line is used up
	bne.s	.store_next_field               ; no
	suba.l	a0,a0                           ; no next field
.store_next_field:
	move.l	a0,input_next_field-m_fileinp   ; keep the next field
	tst.l	d7                              ; a number?
	bmi.w	input_error_bell                ; no: bell, ask again
	rts

;------------------------------------------------------------------------------
; Prints "? " when the prompt flag is set.
;------------------------------------------------------------------------------
print_input_prompt:
	move.w	input_prompt_flag(pc),d0        ; prompt wanted?
	beq.s	input_prompt_done               ; no
	move.w	#$3f20,d0                       ; "? "

input_prompt_call_p0rmki:
	dc.w	$6100,$0000                     ; bsr.w input_prompt_call_p0rmki+2 -> P0RMKI (filled in by the linker),
                                                ;   call P0RMKI: print the two characters

;------------------------------------------------------------------------------
; Return point.
;------------------------------------------------------------------------------
input_prompt_done:
	rts

;------------------------------------------------------------------------------
; INPUT of one string into the string variable at a0: takes the next field of the input line (up to a comma or the line
; end); a field in double quotes may contain commas and loses its quotes.
; Entry: a0 = string descriptor, OUTPUT_CHANNEL = channel
; Exit: string variable set, input_next_field updated
;------------------------------------------------------------------------------
input_string_field:
	pea	(a0)                            ; keep the variable
	move.w	$44(a6),d7                      ; current channel
	move.w	d7,d6                           ; channel for the readers
	bpl.s	input_string_from_device        ; file
	addq.w	#1,d7                           ; -1: screen
	beq.s	input_string_screen             ; line editor
	addq.w	#3,d7                           ; -4: console
	beq.s	input_string_console            ; line editor
	addq.w	#2,d7                           ; -6 .. -2: BIOS device
	bpl.s	input_string_from_device        ; read it directly
	moveq	#-1,d0                          ; below -6: error -1

input_string_jump_error:
	dc.w	$6000,$0000                     ; bra.w input_string_jump_error+2 -> ERROR (filled in by the linker),
                                                ;   tail call ERROR

;------------------------------------------------------------------------------
; File or BIOS device: reads one field into the text buffer.
;------------------------------------------------------------------------------
input_string_from_device:
	move.w	$44(a6),d6                      ; channel
	bsr.w	read_input_field                ; one field into the text buffer
	bra.s	input_string_line_read          ; take it

;------------------------------------------------------------------------------
; Console (-4): next field of the pending line, or a new line from GETLNC.
;------------------------------------------------------------------------------
input_string_console:
	movea.l	input_next_field(pc),a0         ; pending field
	move.l	a0,d0                           ; any?
	bne.s	input_string_take_field         ; yes: use it
	bsr.s	print_input_prompt              ; "? " if wanted

input_string_call_getlnc:
	dc.w	$6100,$0000                     ; bsr.w input_string_call_getlnc+2 -> GETLNC (filled in by the linker),
                                                ;   call GETLNC: line into the text buffer
	bra.s	input_string_line_read          ; first field

;------------------------------------------------------------------------------
; Screen (-1): next field of the pending line, or a new line from GETLNV.
;------------------------------------------------------------------------------
input_string_screen:
	movea.l	input_next_field(pc),a0         ; pending field
	move.l	a0,d0                           ; any?
	bne.s	input_string_take_field         ; yes: use it
	bsr.s	print_input_prompt              ; "? " if wanted

input_string_call_getlnv:
	dc.w	$6100,$0000                     ; bsr.w input_string_call_getlnv+2 -> GETLNV (filled in by the linker),
                                                ;   call GETLNV: line into the text buffer

;------------------------------------------------------------------------------
; A new line: its first field.
;------------------------------------------------------------------------------
input_string_line_read:
	lea	$46(a6),a0                      ; first field

;------------------------------------------------------------------------------
; Splits off the field at a0 (quoted or up to a comma, CR or LF), keeps where the next one starts and assigns it.
; Entry: a0 = field text, string descriptor on the stack
;------------------------------------------------------------------------------
input_string_take_field:
	cmpi.b	#$22,(a0)                       ; quoted?
	beq.s	.quoted                         ; yes
	moveq	#-1,d0                          ; length counter
.find_end:
	addq.w	#1,d0                           ; up to a comma
	move.b	0(a0,d0.w),d1                   ; next character
	cmpi.b	#$2c,d1                         ; comma?
	beq.s	.field_end                      ; yes
	cmpi.b	#$d,d1                          ; or CR
	beq.s	.field_end                      ; yes
	cmpi.b	#$a,d1                          ; or LF
	bne.s	.find_end                       ; no: on
.field_end:
	pea	0(a0,d0.w)                      ; keep the separator
	bra.s	.store_next_field               ; store the next field
.quoted:
	moveq	#0,d0                           ; length counter after the quote
.find_quote:
	addq.w	#1,d0                           ; up to the closing quote
	move.b	0(a0,d0.w),d1                   ; next character
	cmpi.b	#$d,d1                          ; CR before it: take the field as it is
	beq.s	.field_end
	cmpi.b	#$a,d1                          ; LF before it: take the field as it is
	beq.s	.field_end
	cmpi.b	#$22,d1                         ; a quote?
	bne.s	.find_quote                     ; no: on
	addq.w	#1,d0                           ; the character after it
	move.b	0(a0,d0.w),d1
	cmpi.b	#$2c,d1                         ; comma: end of the field
	beq.s	.quoted_end
	cmpi.b	#$d,d1                          ; CR: end of the field
	beq.s	.quoted_end
	cmpi.b	#$a,d1                          ; LF: end; else the quote is inside the field
	bne.s	.find_quote
.quoted_end:
	pea	0(a0,d0.w)                      ; keep the separator
	addq.l	#1,a0                           ; drop the opening quote
	subq.w	#2,d0                           ; and both quotes from the length
.store_next_field:
	movea.l	(sp)+,a1                        ; separator
	cmpi.b	#$d,(a1)+                       ; a CR: the line is used up
	bne.s	.assign                         ; no
	suba.l	a1,a1                           ; no next field
.assign:
	move.l	a1,input_next_field-m_fileinp   ; keep the next field
	movea.l	a0,a2                           ; field text
	movea.l	(sp)+,a0                        ; the variable

input_string_call_screat:
	dc.w	$6100,$0000                     ; bsr.w input_string_call_screat+2 -> Screat (filled in by the linker),
                                                ;   call Screat: a1 = its text (d0 bytes)
	bra.s	.next                           ; enter the count
.copy:
	move.b	(a2)+,(a1)+                     ; copy the field
.next:
	dbra	d0,.copy                        ; d0 characters
	rts

;------------------------------------------------------------------------------
; Takes the next number field of the INPUT line: finds its end (comma, CR or LF, a CR/LF pair counting as one) and reads
; the number with parse_field_number.
; Entry: a0 = field text
; Exit: d0-d2 = number, a0 -> after the separator; d7 = 0 after a comma, 1 at the line end, -1 when the field is no
; number
;------------------------------------------------------------------------------
parse_input_number:
	moveq	#-1,d0                          ; length counter
.find_separator:
	addq.w	#1,d0                           ; count
	move.b	0(a0,d0.w),d1                   ; next character
	cmpi.b	#$2c,d1                         ; comma?
	beq.s	.comma                          ; yes
	cmpi.b	#$d,d1                          ; CR?
	beq.s	.carriage_return                ; yes
	cmpi.b	#$a,d1                          ; LF?
	bne.s	.find_separator                 ; no: on
	bsr.s	parse_field_number              ; LF: read the number
	moveq	#13,d7                          ; a CR may follow
.skip_pair:
	cmp.b	1(a0),d7                        ; skip the CR or LF of a pair
	bne.s	.line_end                       ; no pair
	addq.l	#1,a0                           ; skip its second half
.line_end:
	moveq	#1,d7                           ; line end
	rts
.carriage_return:
	bsr.s	parse_field_number              ; CR: read the number
	moveq	#10,d7                          ; an LF may follow
	bra.s	.skip_pair                      ; check for a pair
.comma:
	bsr.s	parse_field_number              ; comma: read the number
	moveq	#0,d7                           ; comma
	rts

;------------------------------------------------------------------------------
; Reads the number of an INPUT field with parse_number and checks that only spaces stand between it and the separator.
; On failure it returns straight to the caller's caller with d7 = -1.
; Entry: a0 = field text
; Exit: d0-d2 = number, a0 -> the separator
;------------------------------------------------------------------------------
parse_field_number:
	dc.w	$6100,$0000                     ; bsr.w	parse_field_number+2 -> VALSUB (filled in by the linker)
	tst.l	d2                              ; valid?
	bmi.s	.fail                           ; no
	pea	(a1)                            ; end of the field
.skip_spaces:
	cmpi.b	#$20,-(a1)                      ; trailing spaces
	beq.s	.skip_spaces                    ; skip them
	addq.l	#1,a1                           ; back on the last non-space
	cmpa.l	a0,a1                           ; nothing else in the field?
	bne.s	.not_clean                      ; something else: fail
	movea.l	(sp)+,a0                        ; a0 -> the separator
	rts
.not_clean:
	addq.l	#4,sp                           ; drop the field end
.fail:
	addq.l	#4,sp                           ; drop the return to the caller
	moveq	#-1,d7                          ; not a number
	rts

;------------------------------------------------------------------------------
; Reads one character for INPUT: through the file buffer for a file, else with Bconin from the BIOS device (channel +
; 6); a pending break gives LF.
; Entry: d6 = channel handle or device code
; Exit: d0 = character
;------------------------------------------------------------------------------
input_get_char:
	move.w	d6,d0                           ; channel

input_get_char_jump_fgetc:
	dc.w	$6a00,$0000                     ; bpl.w input_get_char_jump_fgetc+2 -> FGetc (filled in by the linker),
                                                ;   file: tail call FGetc
	addq.w	#6,d0                           ; device = code + 6
	move.w	d0,-(sp)                        ; device
	move.w	#$2,-(sp)                       ; Bconin
	trap	#13                             ; Bconin
	addq.l	#4,sp                           ; drop the arguments
	tst.l	d0                              ; failed?
	bmi.s	input_get_char_jump_error       ; error
	btst	#$1,$1364(a6)                   ; break pending: end the line
	beq.s	.done                           ; no
	moveq	#10,d0                          ; LF: end the line
.done:
	rts

;------------------------------------------------------------------------------
; Bconin failed: raises the error in d0.
;------------------------------------------------------------------------------
input_get_char_jump_error:
	dc.w	$6000,$0000                     ; bra.w input_get_char_jump_error+2 -> ERROR (filled in by the linker),
                                                ;   tail call ERROR

;------------------------------------------------------------------------------
; Reads one INPUT field from the current channel into the text buffer: up to a comma or LF; a field that starts with a
; double quote runs on past commas to its closing quote. The last character stored becomes CR.
;------------------------------------------------------------------------------
read_input_field:
	move.w	$44(a6),d6                      ; current channel
	pea	(a3)                            ; keep a3
	lea	$46(a6),a3                      ; text buffer
.next_char:
	bsr.s	input_get_char                  ; next character
	move.b	d0,(a3)+                        ; store it
	cmpi.b	#$2c,d0                         ; comma?
	beq.s	.check_quotes                   ; yes
.check_line_end:
	cmpi.b	#$a,d0                          ; LF?
	beq.s	.check_quotes                   ; yes
	lea	$145(a6),a0                     ; buffer full?
	cmpa.l	a0,a3
	bne.s	.next_char                      ; not full: go on
.end_field:
	move.b	#$d,-(a3)                       ; last character becomes CR
	movea.l	(sp)+,a3                        ; a3 back
	rts
.check_quotes:
	cmpi.b	#$22,$46(a6)                    ; quoted field?
	bne.s	.end_field                      ; no
	cmpi.b	#$22,-$2(a3)                    ; closing quote: the field ends
	beq.s	.end_field                      ; yes
	cmpi.b	#$2c,d0                         ; comma inside quotes: go on
	beq.s	.check_line_end                 ; comma: go on
	bra.s	.end_field                      ; LF: end

