;------------------------------------------------------------------------------
; DRAW s$,a,b: turtle graphics commands with two values for the commands that run out of numbers.
; Entry: a0 = command string, d3-d5 / d0-d2 = first / second value (swapped here)
;------------------------------------------------------------------------------
DRAWS2:
	exg	d3,d0                           ; first value to d0-d2
	exg	d4,d1
	exg	d5,d2
	bra.s	draw_start

;------------------------------------------------------------------------------
; DRAW s$: turtle graphics commands.
; Entry: a0 = command string
;------------------------------------------------------------------------------
DRAWS0:
	moveq	#0,d2                           ; no first value

;------------------------------------------------------------------------------
; DRAW s$,a: turtle graphics commands with one value for a command that runs out of numbers.
; Entry: a0 = command string, d0-d2 = value
;------------------------------------------------------------------------------
DRAWS1:
	moveq	#0,d5                           ; no second value

;------------------------------------------------------------------------------
; Runs the turtle commands of the string: PU/PD pen up/down, CO colour, TT turn to, LT/RT turn left/right,
; FD/BK forward/back, MA/DA move/draw to, MR/DR move/draw by, SX/SY scale. Spaces, commas and semicolons
; between commands are skipped, other letter pairs ignored. The turtle (x, y, angle, x and y scale as floats,
; pen flag) lives in the module's data at 0, $c, $18, $24, $30 and $3c.
; Entry: a0 = string, $46(a6) = the two spare values
; Changes d0-d7, a0-a2
;------------------------------------------------------------------------------
draw_start:
	movem.l	d0-d5,$46(a6)                   ; keep the two spare values
	pea	(a3)                            ; keep a3

draw_call_xstr0kil:
	dc.w	$6100,$0000                     ; bsr.w draw_call_xstr0kil+2 -> XStr0Kil (filled in by the linker),
                                                ;   bsr.w m_draw_loc_0014+2 -> XStr0Kil (filled in by the linker),
                                                ;   string as a zero-terminated copy, a1 = text, d1 = length
	move.w	d1,d7                           ; characters left
	movea.l	a1,a3                           ; text

draw_next_command:
	subq.w	#2,d7                           ; two characters left for a command?
	bpl.s	.command                        ; yes
.done:
	movea.l	(sp)+,a3                        ; a3 back
	rts                                     ; done
.skip_char:
	subq.w	#1,d7                           ; skip one character
	bmi.s	.done                           ; end: done
.command:
	moveq	#-33,d0                         ; upper case
	and.b	(a3)+,d0                        ; first letter
	beq.s	.skip_char                      ; space or zero: skip
	cmpi.b	#$c,d0                          ; ',' (upper-cased): skip
	beq.s	.skip_char
	cmpi.b	#$1b,d0                         ; ';' (upper-cased): skip
	beq.s	.skip_char
	moveq	#-33,d2                         ; upper case
	and.b	(a3)+,d2                        ; second letter
	cmpi.b	#$50,d0                         ; P?
	bne.s	.check_co                       ; no
	cmpi.b	#$55,d2                         ; PU?
	beq.s	.pen_up
	cmpi.b	#$44,d2                         ; PD?
	bne.s	draw_next_command               ; no: ignore
	sf	$3c                             ; pen down
	bra.s	draw_next_command
.pen_up:
	st	$3c                             ; pen up
	bra.s	draw_next_command
.check_co:
	cmpi.b	#$43,d0                         ; CO?
	bne.s	draw_check_tt                   ; no
	cmpi.b	#$4f,d2
	bne.s	draw_next_command
	bsr.w	draw_read_number                ; read the colour

draw_colour_call_fftoi:
	dc.w	$6100,$0000                     ; bsr.w draw_colour_call_fftoi+2 -> FFTOI (filled in by the linker),
                                                ;   bsr.w m_draw_loc_0070+2 -> FFTOI (filled in by the linker), to an
                                                ;   integer

draw_call_color:
	dc.w	$6100,$0000                     ; bsr.w draw_call_color+2 -> COLOR (filled in by the linker), bsr.w
                                                ;   m_draw_loc_0074+2 -> COLOR (filled in by the linker), set the colour

draw_loop:
	bra.s	draw_next_command               ; next command

draw_check_tt:
	cmpi.b	#$54,d0                         ; TT?
	bne.s	draw_check_lt                   ; no
	cmp.b	d0,d2
	bne.s	draw_loop
	bsr.w	draw_read_number                ; read the angle

draw_store_angle:
	movem.l	d0-d2,$18                       ; turtle angle
	bra.s	draw_loop

draw_check_lt:
	cmpi.b	#$4c,d0                         ; LT?
	bne.s	draw_check_rt                   ; no
	cmpi.b	#$54,d2
	bne.s	draw_loop
	bsr.w	draw_read_number                ; read the angle
	neg.w	d2                              ; turn the other way

draw_turn:
	movem.l	$18,d3-d5                       ; turtle angle
	move.l	d7,-(sp)

draw_turn_call_fadd:
	dc.w	$6100,$0000                     ; bsr.w draw_turn_call_fadd+2 -> FADD (filled in by the linker), bsr.w
                                                ;   m_draw_loc_00ae+2 -> FADD (filled in by the linker), add the turn
	move.l	(sp)+,d7
	bra.s	draw_store_angle                ; store the angle

draw_check_rt:
	cmpi.b	#$52,d0                         ; RT?
	bne.s	.check_fd                       ; no
	cmpi.b	#$54,d2
	bne.s	draw_loop
	bsr.w	draw_read_number                ; read the angle
	bra.s	draw_turn                       ; add it
.check_fd:
	cmpi.b	#$46,d0                         ; FD?
	bne.w	draw_check_bk                   ; no
	cmpi.b	#$44,d2
	bne.s	draw_loop
	bsr.w	draw_read_number                ; read the distance

draw_forward:
	move.l	d7,-(sp)
	movem.l	d0-d2,-(sp)                     ; keep the distance
	bsr.w	draw_screen_position            ; start point
	movem.w	d0-d1,$7a0(a6)                  ; ptsin[0..1]
	movem.l	$18,d0-d2                       ; turtle angle

draw_call_fsinq:
	dc.w	$6100,$0000                     ; bsr.w draw_call_fsinq+2 -> FSINQ (filled in by the linker), bsr.w
                                                ;   m_draw_loc_00f2+2 -> FSINQ (filled in by the linker), sine
	movem.l	(sp),d3-d5                      ; distance

draw_sin_call_fmul:
	dc.w	$6100,$0000                     ; bsr.w draw_sin_call_fmul+2 -> FMUL (filled in by the linker), bsr.w
                                                ;   m_draw_loc_00fa+2 -> FMUL (filled in by the linker), * distance
	move.w	$2e,d5                          ; x scale set?
	beq.s	draw_move_x                     ; no
	movem.l	$24,d3-d4                       ; x scale mantissa

draw_scale_x_call_fmul:
	dc.w	$6100,$0000                     ; bsr.w draw_scale_x_call_fmul+2 -> FMUL (filled in by the linker),
                                                ;   bsr.w m_draw_loc_010e+2 -> FMUL (filled in by the linker), * x scale

draw_move_x:
	movem.l	$0,d3-d5                        ; turtle x

draw_x_call_fadd:
	dc.w	$6100,$0000                     ; bsr.w draw_x_call_fadd+2 -> FADD (filled in by the linker), bsr.w
                                                ;   m_draw_loc_011a+2 -> FADD (filled in by the linker), add
	movem.l	d0-d2,$0                        ; new x
	movem.l	$18,d0-d2                       ; turtle angle

draw_call_fcosq:
	dc.w	$6100,$0000                     ; bsr.w draw_call_fcosq+2 -> FCOSQ (filled in by the linker), bsr.w
                                                ;   m_draw_loc_012e+2 -> FCOSQ (filled in by the linker), cosine
	neg.w	d2                              ; negated: angle 0 points up
	movem.l	(sp)+,d3-d5                     ; distance

draw_cos_call_fmul:
	dc.w	$6100,$0000                     ; bsr.w draw_cos_call_fmul+2 -> FMUL (filled in by the linker), bsr.w
                                                ;   m_draw_loc_0138+2 -> FMUL (filled in by the linker), * distance
	move.w	$3a,d5                          ; y scale set?
	beq.s	draw_move_y                     ; no
	movem.l	$30,d3-d4                       ; y scale mantissa

draw_scale_y_call_fmul:
	dc.w	$6100,$0000                     ; bsr.w draw_scale_y_call_fmul+2 -> FMUL (filled in by the linker),
                                                ;   bsr.w m_draw_loc_014c+2 -> FMUL (filled in by the linker), * y scale

draw_move_y:
	movem.l	$c,d3-d5                        ; address error vector, turtle y

draw_y_call_fadd:
	dc.w	$6100,$0000                     ; bsr.w draw_y_call_fadd+2 -> FADD (filled in by the linker), bsr.w
                                                ;   m_draw_loc_0158+2 -> FADD (filled in by the linker), add
	movem.l	d0-d2,$c                        ; address error vector, new y
	move.l	(sp)+,d7

draw_line_to:
	bsr.w	draw_screen_position            ; end point
	movem.w	d0-d1,$7a4(a6)                  ; ptsin[2..3]
	tst.b	$3c                             ; pen up?
	bne.w	draw_loop                       ; yes: no line
	moveq	#6,d0                           ; v_pline
	moveq	#0,d1                           ; no intin
	moveq	#2,d2                           ; two points

draw_call_vdi:
	dc.w	$6100,$0000                     ; bsr.w draw_call_vdi+2 -> Xvdi (filled in by the linker), bsr.w
                                                ;   m_draw_loc_0180+2 -> Xvdi (filled in by the linker), draw it
	bra.w	draw_loop                       ; next command

draw_check_bk:
	cmpi.b	#$42,d0                         ; BK?
	bne.s	.check_move                     ; no
	cmpi.b	#$4b,d2
	bne.w	draw_loop
	bsr.w	draw_read_number                ; read the distance
	neg.w	d2                              ; backwards
	bra.w	draw_forward                    ; go
.check_move:
	cmpi.b	#$4d,d0                         ; M?
	beq.s	.check_mode
	cmpi.b	#$44,d0                         ; D?
	bne.s	.check_scale                    ; no
.check_mode:
	cmpi.b	#$41,d2                         ; MA / DA?
	beq.s	.move
	cmpi.b	#$52,d2                         ; MR / DR?
	bne.w	draw_loop                       ; no: ignore
.move:
	cmpi.b	#$4d,d0                         ; D: draw
	sne	-(sp)                           ; draw flag
	cmpi.b	#$41,d2                         ; R: relative
	sne	-(sp)                           ; relative flag
	bsr.w	draw_screen_position            ; start point
	movem.w	d0-d1,$7a0(a6)                  ; ptsin[0..1]
	bsr.w	draw_read_number                ; read x
	tst.b	(sp)                            ; relative?
	beq.s	.store_x                        ; no
	movem.l	$0,d3-d5                        ; turtle x
	bsr.s	draw_fadd                       ; add it
.store_x:
	movem.l	d0-d2,$0                        ; new x
	bsr.w	draw_read_number                ; read y
	tst.b	(sp)+                           ; relative?
	beq.s	.store_y                        ; no
	movem.l	$c,d3-d5                        ; address error vector, turtle y
	bsr.s	draw_fadd                       ; add it
.store_y:
	movem.l	d0-d2,$c                        ; address error vector, new y
	tst.b	(sp)+                           ; draw?
	beq.w	draw_loop                       ; no: next command
	bra.w	draw_line_to                    ; draw the line
.check_scale:
	cmpi.b	#$53,d0                         ; S?
	bne.s	.next                           ; no
	cmpi.b	#$58,d2                         ; SX?
	beq.s	.scale_x
	cmpi.b	#$59,d2                         ; SY?
	bne.s	.next                           ; no
	bsr.w	draw_read_number                ; read the y scale
	tst.w	d2                              ; zero?
	bne.s	.store_scale_y
	moveq	#0,d0
.store_scale_y:
	movem.l	d0-d2,$30                       ; y scale
.next:
	bra.w	draw_loop                       ; next command
.scale_x:
	bsr.s	draw_read_number                ; read the x scale
	tst.w	d2                              ; zero?
	bne.s	.store_scale_x
	moveq	#0,d2
.store_scale_x:
	movem.l	d0-d2,$24                       ; x scale
	bra.s	.next

;------------------------------------------------------------------------------
; FMUL keeping d7; nothing branches here.
;------------------------------------------------------------------------------
	move.l	d7,-(sp)                        ; not reached

draw_call_fmul:
	dc.w	$6100,$0000                     ; bsr.w draw_call_fmul+2 -> FMUL (filled in by the linker), bsr.w
                                                ;   m_draw_loc_024a+2 -> FMUL (filled in by the linker), multiply
	move.l	(sp)+,d7
	rts

;------------------------------------------------------------------------------
; FADD keeping d7 (the characters left).
; Entry: d0-d2, d3-d5 = floats
; Exit: d0-d2 = sum
;------------------------------------------------------------------------------
draw_fadd:
	move.l	d7,-(sp)                        ; keep d7

draw_call_fadd:
	dc.w	$6100,$0000                     ; bsr.w draw_call_fadd+2 -> FADD (filled in by the linker), bsr.w
                                                ;   m_draw_loc_0254+2 -> FADD (filled in by the linker), add
	move.l	(sp)+,d7
	rts

;------------------------------------------------------------------------------
; Turtle position as screen coordinates, rounded and moved by the graphics origin.
; Exit: d0 = x, d1 = y
;------------------------------------------------------------------------------
draw_screen_position:
	movem.l	$c,d0-d2                        ; address error vector, turtle y
	bsr.s	draw_round                      ; rounded
	add.w	$125e(a6),d0                    ; plus the origin y
	move.w	d0,-(sp)
	movem.l	$0,d0-d2                        ; turtle x
	bsr.s	draw_round                      ; rounded
	add.w	$125c(a6),d0                    ; plus the origin x
	move.w	(sp)+,d1                        ; y
	rts

;------------------------------------------------------------------------------
; Rounds a float to the nearest integer: doubles it, cuts it to an integer and halves that, rounding up.
; Entry: d0-d2 = float
; Exit: d0.l = integer
;------------------------------------------------------------------------------
draw_round:
	tst.w	d2                              ; negative?
	bmi.s	draw_round_negative
	addq.w	#1,d2                           ; double it

draw_round_call_fftoi:
	dc.w	$6100,$0000                     ; bsr.w draw_round_call_fftoi+2 -> FFTOI (filled in by the linker),
                                                ;   bsr.w m_draw_loc_0284+2 -> FFTOI (filled in by the linker), to an
                                                ;   integer
	lsr.l	#1,d0                           ; halve
	bcc.s	.rounded
	addq.l	#1,d0                           ; rounding up
.rounded:
	rts

draw_round_negative:
	subq.w	#1,d2                           ; double a negative
	bra.s	draw_round_call_fftoi

;------------------------------------------------------------------------------
; No number could be read: the value is 0.
;------------------------------------------------------------------------------
draw_no_number:
	moveq	#0,d2                           ; zero exponent: 0
	rts

;------------------------------------------------------------------------------
; The string has run out: takes the next value given after the string (the second moves up) and ends the
; string.
; Exit: d0-d2 = value, d7 = 0
;------------------------------------------------------------------------------
draw_next_argument:
	movem.l	$46(a6),d0-d5                   ; the two spare values
	movem.l	d3-d5,$46(a6)                   ; second becomes the first
	clr.l	$6e(a6)                         ; (purpose not worked out)
	moveq	#0,d7                           ; string ends
	rts

;------------------------------------------------------------------------------
; Reads the next number of the command string after spaces, commas and semicolons.
; Entry: a3 = text, d7.w = characters left
; Exit: d0-d2 = value; a3, d7 advanced
;------------------------------------------------------------------------------
draw_read_number:
	subq.w	#1,d7                           ; a character left?
	bmi.s	draw_next_argument              ; no: take a spare value
	move.b	(a3)+,d0
	cmpi.b	#$20,d0                         ; space?
	beq.s	draw_read_number                ; skip it
	cmpi.b	#$2c,d0                         ; comma?
	beq.s	draw_read_number                ; skip it
	cmpi.b	#$3b,d0                         ; semicolon?
	beq.s	draw_read_number                ; skip it
	subq.l	#1,a3                           ; back onto the number
	addq.w	#1,d7
	movea.l	a3,a0                           ; text
	move.l	d7,d0                           ; characters
	move.l	d7,-(sp)                        ; keep d7

draw_call_valsub:
	dc.w	$6100,$0000                     ; bsr.w draw_call_valsub+2 -> VALSUB (filled in by the linker), bsr.w
                                                ;   m_draw_loc_02ce+2 -> VALSUB (filled in by the linker), read the
                                                ;   number
	move.l	(sp)+,d7
	tst.l	d2                              ; no number?
	bmi.s	draw_no_number                  ; yes: 0
	suba.l	a3,a0                           ; length of the number
	adda.l	a0,a3                           ; past it
	sub.w	a0,d7
	rts

;------------------------------------------------------------------------------
; DRAW(n): turtle state: 0 x, 1 y, 2 angle, 3 x scale, 4 y scale; anything else gives TRUE when the pen
; is down.
; Entry: d0.l = n
; Exit: d0-d2 = float
;------------------------------------------------------------------------------
DRAWFN:
	moveq	#5,d1                           ; five values
	cmp.l	d1,d0
	bcc.s	.pen_state                      ; else the pen state
	mulu.w	#$c,d0                          ; 12 bytes each
	lea	$0,a0                           ; turtle data
	movem.l	0(a0,d0.w),d0-d2
	rts
.pen_state:
	move.b	$3c,d0                          ; pen up?
	bne.s	.pen_up                         ; yes: FALSE
	move.l	#$80000000,d0                   ; TRUE (-1.0)
	moveq	#0,d1
	move.w	#$fc01,d2
	rts
.pen_up:
	moveq	#0,d2                           ; zero exponent: 0
	rts

;------------------------------------------------------------------------------
; SETDRAW x: sets the turtle x position.
; Entry: d0-d2 = x
;------------------------------------------------------------------------------
SETXDRAW:
	movem.l	d0-d2,$0                        ; turtle x
	rts

;------------------------------------------------------------------------------
; SETDRAW ,y: sets the turtle y position.
; Entry: d0-d2 = y
;------------------------------------------------------------------------------
SETYDRAW:
	movem.l	d0-d2,$c                        ; address error vector, turtle y
	rts

;------------------------------------------------------------------------------
; SETDRAW ,,h: sets the turtle heading.
; Entry: d0-d2 = angle
;------------------------------------------------------------------------------
SETHDRAW:
	movem.l	d0-d2,$18                       ; turtle angle
	rts

; symbol table: name, type, value
	dc.b	$44,$52,$41,$57,$53,$32,$00,$00		; DRAWS2
	dc.w	$a200				; defined global text
	dc.l	$0
	dc.b	$44,$52,$41,$57,$53,$30,$00,$00		; DRAWS0
	dc.w	$a200				; defined global text
	dc.l	$8
	dc.b	$44,$52,$41,$57,$53,$31,$00,$00		; DRAWS1
	dc.w	$a200				; defined global text
	dc.l	$a
	dc.b	$44,$52,$41,$57,$46,$4e,$00,$00		; DRAWFN
	dc.w	$a200				; defined global text
	dc.l	$2e0
	dc.b	$53,$45,$54,$58,$44,$52,$41,$57		; SETXDRAW
	dc.w	$a200				; defined global text
	dc.l	$312
	dc.b	$53,$45,$54,$59,$44,$52,$41,$57		; SETYDRAW
	dc.w	$a200				; defined global text
	dc.l	$31c
	dc.b	$53,$45,$54,$48,$44,$52,$41,$57		; SETHDRAW
	dc.w	$a200				; defined global text
	dc.l	$326
	dc.b	$58,$53,$74,$72,$30,$4b,$69,$6c		; XStr0Kil
	dc.w	$8800				; defined external
	dc.l	$0
	dc.b	$46,$46,$54,$4f,$49,$00,$00,$00		; FFTOI
	dc.w	$8800				; defined external
	dc.l	$0
	dc.b	$43,$4f,$4c,$4f,$52,$00,$00,$00		; COLOR
	dc.w	$8800				; defined external
	dc.l	$0
	dc.b	$46,$41,$44,$44,$00,$00,$00,$00		; FADD
	dc.w	$8800				; defined external
	dc.l	$0
	dc.b	$46,$53,$49,$4e,$51,$00,$00,$00		; FSINQ
	dc.w	$8800				; defined external
	dc.l	$0
	dc.b	$46,$4d,$55,$4c,$00,$00,$00,$00		; FMUL
	dc.w	$8800				; defined external
	dc.l	$0
	dc.b	$46,$43,$4f,$53,$51,$00,$00,$00		; FCOSQ
	dc.w	$8800				; defined external
	dc.l	$0
	dc.b	$58,$76,$64,$69,$00,$00,$00,$00		; Xvdi
	dc.w	$8800				; defined external
	dc.l	$0
	dc.b	$56,$41,$4c,$53,$55,$42,$00,$00		; VALSUB
	dc.w	$8800				; defined external
	dc.l	$0
; relocation words, one a code word: 0 none, 1 data, 2 text, 3 bss, 4 external, 5 a long (its low
; word tells), 6 external pc-relative, 7 the first word of an instruction; an external's symbol
; number is the word >> 3
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$003e,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0005,$0003,$0000,$0000,$0005,$0003,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0046,$0000,$004e,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0005,$0003
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0005,$0003,$0000,$0000
	dc.w	$0056,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0005
	dc.w	$0003,$0000,$005e,$0000,$0000,$0000,$0066,$0000
	dc.w	$0005,$0003,$0000,$0000,$0000,$0005,$0003,$0000
	dc.w	$0066,$0000,$0000,$0005,$0003,$0000,$0056,$0000
	dc.w	$0000,$0005,$0003,$0000,$0000,$0005,$0003,$0000
	dc.w	$006e,$0000,$0000,$0000,$0000,$0066,$0000,$0005
	dc.w	$0003,$0000,$0000,$0000,$0005,$0003,$0000,$0066
	dc.w	$0000,$0000,$0005,$0003,$0000,$0056,$0000,$0000
	dc.w	$0005,$0003,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0005,$0003,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0076,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000
