; Exit: a0 = record (buffer, size, head, tail ...)
;------------------------------------------------------------------------------
keyboard_iorec:
	pea	$e0001                          ; Iorec, device 1: keyboard
	trap	#14                             ; XBIOS
	addq.l	#4,sp                           ; drop the arguments
	movea.l	d0,a0                           ; record
	rts

