	ori.w	#$700,sr                        ; interrupts off
	bsr.s	keyboard_iorec                  ; keyboard record
	movea.l	(a0)+,a1                        ; buffer
	movem.w	(a0),d0-d2                      ; size, head, tail
	addq.w	#4,d2                           ; next tail
	cmp.w	d0,d2                           ; past the end?
	bcs.s	.check_full                     ; no
	moveq	#0,d2                           ; wrap
