;------------------------------------------------------------------------------
; Line editor on the text already in the buffer, control characters accepted.
; Entry: d0 = maximum length, d6 = length of the text in the buffer
;------------------------------------------------------------------------------
edit_line_buffer:
	clr.w	$1370(a6)                       ; no lowest character: control codes accepted
	bra.s	edit_line

;------------------------------------------------------------------------------
; Line editor with an empty line, 255 characters at most, control characters accepted (input from the keyboard channel).
; Exit: as edit_line.
;------------------------------------------------------------------------------
edit_line_any_char:
	moveq	#-1,d0                          ; 255 characters
	clr.w	$1370(a6)                       ; control codes accepted
	bra.s	edit_line_empty

;------------------------------------------------------------------------------
; Line editor with an empty line, 255 characters at most, characters below space ignored (input from the screen
; channel).
; Exit: as edit_line.
;------------------------------------------------------------------------------
edit_line_printable:
	moveq	#-1,d0                          ; 255 characters
	move.w	#$20,$1370(a6)                  ; characters below space ignored

;------------------------------------------------------------------------------
; Line editor with an empty line.
; Entry: d0 = maximum length
;------------------------------------------------------------------------------
edit_line_empty:
	moveq	#0,d6                           ; empty line

;------------------------------------------------------------------------------
; Line editor in the text buffer at $46(a6), on the screen or in the text window. Keys: cursor left/right, Home or
; cursor up to the start, cursor down or Ctrl-right to the end, Ctrl-left to the start, Insert toggles overwrite mode,
; Backspace and Delete, Esc clears the line, Return or Enter ends. Characters below the lowest accepted one are ignored;
; a full line rings the bell in insert mode.
; Entry: d0 = maximum length, d6 = length of the line in the buffer, EDIT_MIN_CHAR set
; Exit: d0 = key that ended the line, line in the text buffer ending in CR, d6 = length
;------------------------------------------------------------------------------
edit_line:
	move.w	d6,$136e(a6)                    ; length shown so far
	andi.w	#$ff,d0
	move.w	d0,$1362(a6)                    ; maximum length
