.check_left:
	cmpi.b	#$4b,d0                         ; cursor left?
	beq.s	.cursor_left
	cmpi.b	#$4d,d0                         ; cursor right?
	beq.s	.cursor_right
	cmpi.b	#$73,d0                         ; Ctrl-left?
	beq.s	.cursor_home
	cmpi.b	#$74,d0                         ; Ctrl-right?
	beq.s	.cursor_end
	cmpi.b	#$50,d0                         ; cursor down?
	beq.s	.cursor_end
	cmpi.b	#$48,d0                         ; cursor up?
	bne.s	.next_key                       ; no: ignore
.cursor_home:
	moveq	#0,d7                           ; cursor to the start
.show:
	bra.s	.redraw
.cursor_left:
	subq.w	#1,d7                           ; one left
	bpl.s	.redraw                         ; not before the start
.cursor_right:
	addq.w	#1,d7                           ; one right
	cmp.w	d6,d7                           ; past the end?
	bls.s	.redraw                         ; no
.cursor_end:
