.not_full:
	tst.b	$1366(a6)                       ; overwrite mode?
	bpl.s	.insert_char                    ; no: insert
	move.b	d0,0(a0,d7.w)                   ; overwrite at the cursor
	addq.w	#1,d7                           ; cursor on
	cmp.w	d6,d7                           ; within the line?
	bls.s	.redraw                         ; yes
	addq.w	#1,d6                           ; appended: line longer
	bra.s	.redraw
.insert_char:
	cmp.w	d6,d7                           ; cursor at the end?
	bne.s	.open_gap                       ; no: make room
.store_char:
	addq.w	#1,d6                           ; line one longer
	move.b	d0,0(a0,d7.w)                   ; store the character
	addq.w	#1,d7                           ; cursor on
.redraw:
	bsr.w	edit_redraw                     ; show the line
	bra.w	.next_key                       ; next key
.line_full:
	bsr.w	ring_bell                       ; beep
	bra.w	.next_key                       ; next key
.finish:
	move.b	#$d,0(a0,d6.w)                  ; CR after the line
	move.w	d0,-(sp)                        ; keep the key
	moveq	#-1,d7                          ; no cursor
	bsr.w	edit_redraw                     ; show the line without it
	moveq	#13,d0                          ; CR
	bsr.w	edit_put_raw
	moveq	#10,d0                          ; LF
	bsr.w	edit_put_raw
	move.w	(sp)+,d0                        ; key that ended the line
	rts
.clear_line:
	moveq	#0,d6                           ; empty line
	bra.w	.cursor_end                     ; cursor to the start
.open_gap:
	lea	0(a0,d7.w),a1                   ; cursor position
	lea	1(a0,d6.w),a2                   ; after the end
.shift_right:
	move.b	-(a2),1(a2)                     ; move a byte up
	cmpa.l	a1,a2                           ; back to the cursor?
	bne.s	.shift_right
	bra.s	.store_char                     ; insert
.delete_key:
	cmp.w	d6,d7                           ; at the end?
	beq.s	.redraw                         ; yes: nothing to delete
	addq.w	#1,d7                           ; delete the character under the cursor
.backspace:
	tst.w	d7                              ; at the start?
	beq.w	.next_key                       ; yes: nothing to do
	subq.w	#1,d7                           ; cursor back
	subq.w	#1,d6                           ; line shorter
	cmp.w	d6,d7                           ; was it the last?
	beq.s	.redraw                         ; yes
	lea	1(a0,d7.w),a1                   ; after the deleted character
	lea	1(a0,d6.w),a2                   ; end of the line
.close_gap:
	move.b	(a1)+,-$2(a1)                   ; move a byte down
	cmpa.l	a1,a2
	bne.s	.close_gap
	bra.s	.redraw

;------------------------------------------------------------------------------
; Key with no character and no Alternate: ignored (d0 = 0).
;------------------------------------------------------------------------------
edit_key_none:
	rts

;------------------------------------------------------------------------------
; Reads a key for the line editor. A key with Alternate held and no character gives its scan code with bit 7 set; Ctrl-S
; toggles bit 7 of the next key; Ctrl-A takes the following digits as a decimal character code.
; Exit: d0 = key (character in the low byte, scan code in bits 16-23)
;------------------------------------------------------------------------------
edit_read_key:
	bsr.s	edit_wait_key
	tst.b	d0                              ; a character?
	bne.s	.check_ctrl_s                   ; yes
	btst	#$1b,d0                         ; Alternate held?
	beq.s	edit_key_none                   ; no: ignore it
	swap	d0                              ; scan code
	bset	#$7,d0                          ; as an Alternate key
.check_ctrl_s:
	cmpi.b	#$13,d0                         ; Ctrl-S?
	bne.s	.check_ctrl_a                   ; no
	bsr.s	edit_wait_key                   ; next key
	bchg	#$7,d0                          ; with bit 7 flipped
.check_ctrl_a:
	cmpi.b	#$1,d0                          ; Ctrl-A?
	bne.s	.done                           ; no
	moveq	#0,d5                           ; character code
.next_digit:
	bsr.s	edit_wait_key                   ; next key
	subi.b	#$30,d0
	cmpi.b	#$9,d0                          ; a digit?
	bhi.s	.code_done                      ; no: code complete
	mulu.w	#$a,d5                          ; code * 10
	add.w	d0,d5                           ; + digit
	cmpi.w	#$1a,d5                         ; below 26: more digits
	bcs.s	.next_digit
.code_done:
	move.w	d5,d0                           ; the code as the key
.done:
	rts

;------------------------------------------------------------------------------
; Waits for a key.
; Exit: d0 = key
;------------------------------------------------------------------------------
edit_wait_key:
	dc.w	$6100,$0000                     ; bsr.w edit_wait_key+2 -> INKEY (filled in by the linker), bsr.w
                                                ;   edit_wait_key+2 -> INKEY (filled in by the linker), key waiting?
	beq.s	edit_wait_key                   ; no: wait
	rts

;------------------------------------------------------------------------------
; Writes a character for the line editor: with Bconout to the console (mouse hidden), or through PRINT in the text
; window.
; Entry: d0 = character
;------------------------------------------------------------------------------
edit_put_char:
	move.w	$1372(a6),d2                    ; text window?
	bne.s	edit_put_char_window            ; yes
	move.w	d0,-(sp)                        ; character
	pea	$30005                          ; Bconout, device 5 (raw console)

edit_put_char_call_hidem:
	dc.w	$6100,$0000                     ; bsr.w edit_put_char_call_hidem+2 -> Hidem (filled in by the linker),
                                                ;   bsr.w m_input_loc_01b6+2 -> Hidem (filled in by the linker), hide
                                                ;   the mouse
	trap	#13                             ; BIOS, Bconout
	addq.l	#6,sp                           ; drop the arguments
	rts

;------------------------------------------------------------------------------
; Text window: PRINTs the character on the console channel (-1).
;------------------------------------------------------------------------------
edit_put_char_window:
	move.w	#$ffff,$44(a6)                  ; console channel
	bra.w	put_char_saving_registers       ; print it

;------------------------------------------------------------------------------
; Redraws the edited line from its start: the text with the cursor character in reverse (ESC p ... ESC q), then spaces
; over what the last redraw showed beyond the end. When the line made the screen scroll, its start row moves up one.
; Entry: d6 = length, d7 = cursor position (-1 for none)
;------------------------------------------------------------------------------
edit_redraw:
	movem.w	$136a(a6),d0-d1                 ; start column and row

edit_redraw_call_gtspos:
	dc.w	$6100,$0000                     ; bsr.w edit_redraw_call_gtspos+2 -> GTSPOS (filled in by the linker),
                                                ;   bsr.w m_input_loc_01d0+2 -> GTSPOS (filled in by the linker), cursor
                                                ;   there
	moveq	#0,d5                           ; position in the line
.next_char:
	cmp.w	d5,d7                           ; cursor here?
	bne.s	.draw_char                      ; no
	moveq	#27,d0                          ; ESC p: reverse on
	bsr.s	edit_put_raw
	moveq	#112,d0
	bsr.s	edit_put_raw
.draw_char:
	lea	$46(a6),a0                      ; line buffer
	cmp.w	d5,d6                           ; end of the text?
	beq.s	.after_text                     ; yes
	move.b	0(a0,d5.w),d0                   ; character
	bsr.s	edit_put_char                   ; show it
	cmp.w	d5,d7                           ; under the cursor?
	bne.s	.advance                        ; no
	bsr.s	edit_reverse_off                ; reverse off
.advance:
	addq.w	#1,d5                           ; next position
	bra.s	.next_char
.after_text:
	cmp.w	d5,d7                           ; cursor after the end?
	bne.s	.clear_rest                     ; no
	moveq	#32,d0                          ; reverse space as the cursor
	bsr.s	edit_put_raw
	bsr.s	edit_reverse_off
.clear_rest:
	move.w	d6,-(sp)                        ; keep the length
.blank_old:
	cmp.w	$136e(a6),d6                    ; longer than before?
	bgt.s	.check_scroll                   ; yes: done blanking
	moveq	#32,d0                          ; space over the old text
	bsr.s	edit_put_raw
	addq.w	#1,d6
	bra.s	.blank_old
.check_scroll:
	move.w	(sp)+,d6                        ; length back

edit_redraw_call_crscol:
	dc.w	$6100,$0000                     ; bsr.w edit_redraw_call_crscol+2 -> CRSCOL (filled in by the linker),
                                                ;   bsr.w m_input_loc_0216+2 -> CRSCOL (filled in by the linker), where
                                                ;   the cursor ended up
	cmp.w	$136e(a6),d6                    ; line grew?
	ble.s	.remember                       ; no
	subq.w	#1,d0                           ; at column 1?
	bne.s	.remember                       ; no
	cmp.w	$1368(a6),d1                    ; still the last row?
	bne.s	.remember                       ; no
	subq.w	#1,$136c(a6)                    ; the screen scrolled: start row up one
.remember:
	move.w	d1,$1368(a6)                    ; last row
	move.w	d6,$136e(a6)                    ; length shown
	rts

