	dc.w	$6100,$0000                     ; bsr.w store_call_prxsub+2 -> PRXsub (filled in by the linker), bsr.w
                                                ;   m_store_loc_0040+2 -> PRXsub (filled in by the linker), write the
                                                ;   text

