recall_call_flushbuf:
	dc.w	$6100,$0000                     ; bsr.w recall_call_flushbuf+2 -> FlushBuf (filled in by the linker),
                                                ;   write buffer: flush it first

recall_check_buffer:
	cmp.w	d1,d0                           ; bytes left in the buffer?
	bcs.s	recall_next_char                ; yes

recall_call_fillbuf:
