	move.w	(a2)+,(a1)+
.copy_long:
	lsr.w	#1,d0                           ; bit 2: a long
	bcc.s	.copy_eight
	move.l	(a2)+,(a1)+
.copy_eight:
	lsr.w	#1,d0                           ; bit 3: eight bytes
	bcc.s	.count_blocks
	bra.s	.copy_eight_entry
.copy_loop:
	move.l	(a2)+,(a1)+                     ; 16 bytes at a time
	move.l	(a2)+,(a1)+
.copy_eight_entry:
	move.l	(a2)+,(a1)+
	move.l	(a2)+,(a1)+
.count_blocks:
	dbra	d0,.copy_loop
	addq.l	#6,a0                           ; next descriptor
