;------------------------------------------------------------------------------
; MIN of two floats in memory.
; Entry: a0, a1 -> floats
; Exit: d0-d2 = the smaller
;------------------------------------------------------------------------------
float_min_stored_pair:
	move.l	(a1)+,d0                        ; first float from (a1)
	move.w	(a1)+,d1
	move.w	(a1)+,d2

;------------------------------------------------------------------------------
