	move.l	(a0)+,d3                        ; second float from (a0)
	move.w	(a0)+,d4
	move.w	(a0)+,d5

;------------------------------------------------------------------------------
; MIN of two floats: keeps the smaller.
; Entry: d0-d2, d3-d5 = floats
; Exit: d0-d2 = the smaller
;------------------------------------------------------------------------------
float_min:
	cmp.w	d2,d5                           ; compare the exponent words (signed)
	blt.s	.take_second                    ; second smaller
	bgt.s	.done                           ; first smaller
	tst.w	d2                              ; same exponent: sign?
	bpl.s	.positive                       ; positive
	cmp.l	d0,d3                           ; negative: the larger mantissa is smaller
	bcs.s	.done                           ; first mantissa larger: first smaller
	bne.s	.take_second
	cmp.w	d1,d4                           ; same high long: low words
	bls.s	.done
	bra.s	.take_second
.positive:
	cmp.l	d0,d3                           ; positive: the smaller mantissa is smaller
	bhi.s	.done                           ; second mantissa larger: first smaller
	bne.s	.take_second
	cmp.w	d1,d4                           ; same high long: low words
	bcc.s	.done
.take_second:
	move.l	d3,d0                           ; second float is the result
	move.w	d4,d1
	move.w	d5,d2
.done:
	rts

