	dc.w	$23f9,$0000,$0004,$0000,$0000   ; move.l $4,$0 -> aTIMER (filled in by the linker), move.l $4,$0 ->
                                                ;   aTIMER (filled in by the linker), target = saved target
	rts

;------------------------------------------------------------------------------
; EVERY STOP: stops the EVERY timer. The pending bit it clears, bit 3, is the one the AFTER timer sets.
;------------------------------------------------------------------------------
EVEHOLD:
	dc.w	$42b9,$0000,$0000               ; clr.l $0 -> eTIMER (filled in by the linker), clr.l $0 -> eTIMER
                                                ;   (filled in by the linker), timer off
	bclr	#$3,$1364(a6)                   ; pending flag off
	rts

;------------------------------------------------------------------------------
; EVERY CONT: restarts the EVERY timer from its saved target time.
;------------------------------------------------------------------------------
EVECONT:
	dc.w	$23f9,$0000,$0004,$0000,$0000   ; move.l $4,$0 -> eTIMER (filled in by the linker), move.l $4,$0 ->
                                                ;   eTIMER (filled in by the linker), target = saved target
	rts

;------------------------------------------------------------------------------
; AFTER t GOSUB proc: calls proc once after t 200 Hz ticks; no procedure switches it off.
; Entry: a2 = procedure, d0.l = ticks
;------------------------------------------------------------------------------
AFTER:
	dc.w	$23ca,$0000,$0000               ; move.l a2,$0 -> afterPRO (filled in by the linker), move.l a2,$0 ->
                                                ;   afterPRO (filled in by the linker), procedure
	bne.s	.start                          ; given?
	moveq	#0,d0                           ; no: off
	bra.s	after_store
.start:
	move.l	d0,d6                           ; ticks

after_call_timer:
	dc.w	$6100,$0000                     ; bsr.w after_call_timer+2 -> TIMER (filled in by the linker), bsr.w
                                                ;   m_after_loc_0042+2 -> TIMER (filled in by the linker), 200 Hz
                                                ;   counter
	add.l	d6,d0                           ; target time

after_store:
	move.l	d0,d1
	dc.w	$48f9,$0003,$0000,$0000         ; movem.l d0-d1,$0 -> aTIMER (filled in by the linker), movem.l d0-d1,$0
                                                ;   -> aTIMER (filled in by the linker), target and saved target
	rts

;------------------------------------------------------------------------------
; EVERY t GOSUB proc: calls proc every t 200 Hz ticks; no procedure switches it off.
; Entry: a2 = procedure, d0.l = ticks
;------------------------------------------------------------------------------
EVERY:
	dc.w	$23ca,$0000,$0000               ; move.l a2,$0 -> everyPRO (filled in by the linker), move.l a2,$0 ->
                                                ;   everyPRO (filled in by the linker), procedure
	bne.s	.start                          ; given?
	moveq	#0,d0                           ; no: off
	moveq	#0,d6                           ; no period
	bra.s	every_store
.start:
	move.l	d0,d6                           ; period

every_call_timer:
	dc.w	$6100,$0000                     ; bsr.w every_call_timer+2 -> TIMER (filled in by the linker), bsr.w
                                                ;   m_after_loc_0064+2 -> TIMER (filled in by the linker), 200 Hz
                                                ;   counter
	add.l	d6,d0                           ; target time

every_store:
	move.l	d0,d1
	exg	d6,d0                           ; d0 = period, d6 = target
	dc.w	$48f9,$0043,$0000,$0000         ; movem.l d0-d1/d6,$0 -> EtVAL (filled in by the linker), movem.l
                                                ;   d0-d1/d6,$0 -> EtVAL (filled in by the linker), period, target,
                                                ;   saved target
	rts
	dc.w	$13c0,$0000,$0000               ; move.b d0,$0 -> NumLOCK (filled in by the linker), move.b d0,$0 ->
                                                ;   NumLOCK (filled in by the linker), sets NumLOCK; no label, not
                                                ;   reached from here
	rts

