; relocation words, one a code word: 0 none, 1 data, 2 text, 3 bss, 4 external, 5 a long (its low
; word tells), 6 external pc-relative, 7 the first word of an instruction; an external's symbol
; number is the word >> 3
	dc.w	$0000,$0005,$0034,$0000,$0000,$0000,$0000,$0000
	dc.w	$0005,$0034,$0005,$0034,$0000,$0000,$0005,$003c
	dc.w	$0000,$0000,$0000,$0000,$0000,$0005,$003c,$0005
	dc.w	$003c,$0000,$0000,$0005,$0044,$0000,$0000,$0000
	dc.w	$0000,$0000,$004e,$0000,$0000,$0000,$0000,$0005
	dc.w	$0034,$0000,$0000,$0005,$0054,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$004e,$0000,$0000,$0000,$0000
	dc.w	$0000,$0005,$005c,$0000,$0000,$0005,$0064,$0000

;==============================================================================
; Module KEYDEF.O: 44 bytes of code, 0 of data, 0 of bss; exports KEYDEF
;==============================================================================
	dc.b	$4b,$45,$59,$44,$45,$46,$2e,$4f,$00,$00,$00,$00,$00,$00	; library entry: the name KEYDEF.O
	dc.w	$54ae,$12c1,$0000,$01b6,$0000,$009e,$0000	; entry: the rest (the member's length at +8)
	dc.w	$601a				; DRI object module
	dc.l	$2c,$0,$0,$2a		; text, data and bss lengths, symbol table length
	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_keydef:
;------------------------------------------------------------------------------
; KEYDEF n,s$: sets the text of function key n (1-20), at most 30 characters, in the 32-byte entries
; of KEYBUF that the keyboard interrupt types for the key.
; Entry: d1 = n, a0 = string
; Changes d0, d1, a0, a1
;------------------------------------------------------------------------------
KEYDEF:
	subq.w	#1,d1                           ; 0-based
	move.w	d1,-(sp)                        ; keep it

keydef_call_xstr0kil:
	dc.w	$6100,$0000                     ; bsr.w keydef_call_xstr0kil+2 -> XStr0Kil (filled in by the linker),
                                                ;   bsr.w m_keydef_loc_0004+2 -> XStr0Kil (filled in by the linker),
                                                ;   text as a zero-terminated copy, a1 = text, d1 = length
	move.w	(sp)+,d0                        ; key
	cmpi.w	#$13,d0                         ; beyond 20?
	bhi.s	.done                           ; yes: ignore
	asl.w	#5,d0                           ; * 32
	dc.w	$41f9,$0000,$0000               ; lea $0,a0 -> KEYBUF (filled in by the linker), lea $0,a0 -> KEYBUF
                                                ;   (filled in by the linker), function key texts
	adda.w	d0,a0                           ; this key's entry
	cmpi.w	#$1f,d1                         ; 31 or more?
	bcs.s	.copy_next                      ; no
	moveq	#30,d1                          ; cut to 30
.copy_char:
	move.b	(a1)+,(a0)+                     ; copy a character
.copy_next:
	dbra	d1,.copy_char
	clr.b	(a0)+                           ; terminate it
.done:
	rts

; symbol table: name, type, value
	dc.b	$4b,$45,$59,$44,$45,$46,$00,$00		; KEYDEF
	dc.w	$a200				; defined global text
	dc.l	$0
	dc.b	$58,$53,$74,$72,$30,$4b,$69,$6c		; XStr0Kil
	dc.w	$8800				; defined external
	dc.l	$0
	dc.b	$4b,$45,$59,$42,$55,$46,$00,$00		; KEYBUF
	dc.w	$8800				; defined external
	dc.l	$0
; relocation words, one a code word: 0 none, 1 data, 2 text, 3 bss, 4 external, 5 a long (its low
; word tells), 6 external pc-relative, 7 the first word of an instruction; an external's symbol
; number is the word >> 3
	dc.w	$0000,$0000,$0000,$000e,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0005,$0014,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000

;==============================================================================
; Module KEYIRQ.O: 1024 bytes of code, 0 of data, 672 of bss; exports EtVAL, eTIMER, aTIMER, IRQON, IRQOFF, BOMBON, KEYBUF, KEYPAD
;==============================================================================
	dc.b	$4b,$45,$59,$49,$52,$51,$2e,$4f,$00,$00,$00,$00,$00,$00	; library entry: the name KEYIRQ.O
	dc.w	$56ce,$132b,$0000,$01b6,$0000,$08fc,$0000	; entry: the rest (the member's length at +8)
	dc.w	$601a				; DRI object module
	dc.l	$400,$0,$2a0,$e0		; text, data and bss lengths, symbol table length
	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_keyirq:
; Period of the EVERY timer in 200 Hz ticks (EVERY t: t).
EtVAL:
	dc.w	$0000,$0000

; EVERY timer: target time (0 = off) and the saved target for EVERY CONT.
eTIMER:
	dc.w	$0000,$0000,$0000,$0000

; AFTER timer: target time (0 = off) and the saved target for AFTER CONT.
aTIMER:
	dc.w	$0000,$0000,$0000,$0000

;------------------------------------------------------------------------------
; etv_timer hook: calls the old handler (its address patched into the jsr), then checks the keyboard and
; the AFTER/EVERY timers.
;------------------------------------------------------------------------------
keyirq_timer_hook:
	move.w	4(sp),-(sp)                     ; tick period
	jsr	$0                              ; old etv_timer (patched)
	addq.l	#2,sp                           ; drop it
	bra.s	keyirq_check                    ; check keys and timers

;------------------------------------------------------------------------------
; Routine that gives -1, put at Line-A base + $76 when break is pressed (field not identified; perhaps
; meant as the fill abort routine).
;------------------------------------------------------------------------------
keyirq_return_true:
	moveq	#-1,d0                          ; -1
	rts

;------------------------------------------------------------------------------
; ikbdsys hook: calls the old keyboard handler (its address patched into the jsr), then checks.
;------------------------------------------------------------------------------
keyirq_ikbd_hook:
	jsr	$0                              ; old ikbdsys (patched)

;------------------------------------------------------------------------------
; Keyboard and timer check after each IKBD packet and timer tick: Ctrl-Alt-Shift raises a break (unless
; ON BREAK CONT), then the newest key in the buffer is looked at: keypad ( and - with Ctrl toggle the num
; lock, F1-F20 type their KEYDEF text, the keypad gives cursor keys under num lock or builds a character
; code with Alternate. Then the AFTER and EVERY timers are checked. NumLOCK bits: 0 num lock on,
; 1 Ctrl-keypad toggle allowed, 2 Ctrl keypad, 3 Alternate codes, 4/5 KEYDEF texts (without/with Alt).
; Changes a0-a2, d0-d2
;------------------------------------------------------------------------------
keyirq_check:
	movem.l	d3-d4/a6,-(sp)
	dc.w	$4df9,$0000,$0000               ; lea $0,a6 -> BssA6 (filled in by the linker), lea $0,a6 -> BssA6
                                                ;   (filled in by the linker), runtime variable block

;------------------------------------------------------------------------------
; Address of kbshift (abs.w): $e1b for TOS 1.00, patched from the OS header for later versions.
;------------------------------------------------------------------------------
keyirq_kbshift_address:
	lea	$e1b.w,a0                       ; kbshift
	moveq	#14,d0                          ; Shift, Ctrl, Alt
	and.b	(a0),d0
	cmpi.b	#$e,d0                          ; all three held?
	bne.s	keyirq_keyboard_iorec           ; no
	dc.w	$1239,$0000,$0000               ; move.b $0,d1 -> NoBREAK (filled in by the linker), move.b $0,d1 ->
                                                ;   NoBREAK (filled in by the linker), break mode
	bmi.s	keyirq_keyboard_iorec           ; ON BREAK CONT: ignore
	bset	#$1,$1364(a6)                   ; break pending
	movea.l	$32(a6),a0                      ; Line-A base
	move.l	#keyirq_return_true-m_keyirq,$76(a0) ; routine giving -1 at +$76

;------------------------------------------------------------------------------
; Keyboard Iorec address, patched by IRQON.
;------------------------------------------------------------------------------
keyirq_keyboard_iorec:
	movea.l	#$0,a0                          ; keyboard Iorec (patched)
	ori.w	#$700,sr                        ; interrupts off
	dc.w	$1839,$0000,$0000               ; move.b $0,d4 -> NumLOCK (filled in by the linker), move.b $0,d4 ->
                                                ;   NumLOCK (filled in by the linker), flags
	movea.l	(a0)+,a1                        ; buffer
	movem.w	(a0),d0-d2                      ; size, head, tail
	moveq	#0,d3
	move.b	keyirq_alt_code(pc),d3          ; Alternate code pending?
	beq.s	.new_key                        ; no
	movea.w	keyirq_kbshift_address+2(pc),a2 ; kbshift address
	btst	#$3,(a2)                        ; Alternate still held?
	beq.w	keyirq_put_alt_code             ; no: put the code
.new_key:
	cmp.w	d1,d2                           ; new key?
	beq.w	keyirq_check_timers             ; no: timers
	move.w	0(a1,d2.w),d3                   ; shift state and scan code of the newest key
	cmpi.b	#$63,d3                         ; keypad (?
	beq.w	keyirq_numlock_key
	cmpi.b	#$4a,d3                         ; keypad -?
	beq.w	keyirq_numlock_key
	cmpi.b	#$3b,d3                         ; below F1?
	bcs.s	.check_keypad
	cmpi.b	#$5d,d3                         ; above Shift-F10?
	bhi.s	.check_keypad
	cmpi.b	#$54,d3                         ; Shift-F1 or higher?
	bcs.s	.check_f1                       ; no
	subi.b	#$f,d3                          ; Shift-F1 to $45
	bra.s	.function_key
.check_f1:
	cmpi.b	#$44,d3                         ; above F10?
	bhi.s	.check_keypad                   ; yes: not a function key
.function_key:
	subi.b	#$3b,d3                         ; key number 0-19
	btst	#$b,d3                          ; Alternate held?
	beq.s	.check_keydef                   ; no
	lsr.b	#1,d4                           ; bit 5 instead of bit 4
.check_keydef:
	btst	#$4,d4                          ; KEYDEF texts on?
	bne.w	keyirq_type_keydef              ; yes: type the text
.check_keypad:
	subi.b	#$67,d3                         ; keypad 7 is 0
	cmpi.b	#$a,d3                          ; not a keypad key?
	bhi.s	keyirq_check_timers             ; yes: timers
	btst	#$3,d4                          ; Alternate codes on?
	beq.s	.check_ctrl                     ; no
	btst	#$b,d3                          ; Alternate held?
	bne.s	.alt_digit                      ; yes: a digit
.check_ctrl:
	btst	#$2,d4                          ; Ctrl keypad on?
	beq.s	.check_numlock                  ; no
	btst	#$a,d3                          ; Ctrl held?
	bne.s	.replace_key                    ; yes: replace
.check_numlock:
	btst	#$0,d4                          ; num lock on?
	beq.s	keyirq_check_timers             ; no: keep the key
.replace_key:
	ext.w	d3
	asl.w	#2,d3                           ; * 4
	move.l	keyirq_keypad_codes(pc,d3.w),0(a1,d2.w) ; replace with the code
	bra.s	keyirq_check_timers
.alt_digit:
	ext.w	d3
	moveq	#10,d4
	cmp.w	d4,d3                           ; keypad '.'?
	beq.s	keyirq_check_timers             ; yes: ignore
	mulu.w	keyirq_alt_code_high(pc),d4     ; code * 10
	add.b	keyirq_keypad_digits(pc,d3.w),d4 ; + digit
	move.b	d4,keyirq_alt_code-m_keyirq     ; new code

;------------------------------------------------------------------------------
; Takes the newest key out of the buffer again.
;------------------------------------------------------------------------------
keyirq_drop_key:
	subq.w	#4,d2                           ; tail back one
	bpl.s	.store_tail
	add.w	d0,d2                           ; wrap
.store_tail:
	move.w	d2,4(a0)                        ; new tail

;------------------------------------------------------------------------------
; EVERY timer due: next target one period on, pending bit 2 set. AFTER timer past: switched off,
; pending bit 3 set.
;------------------------------------------------------------------------------
keyirq_check_timers:
	lea	eTIMER(pc),a0                   ; EVERY timer
	move.l	(a0),d0                         ; target
	beq.s	.check_after                    ; off
	cmp.l	$4ba.w,d0                       ; _hz_200, due?
	bhi.s	.check_after                    ; not yet
	add.l	-$4(a0),d0                      ; + period
	move.l	d0,(a0)+                        ; next target
	move.l	d0,(a0)+                        ; and saved target
	bset	#$2,$1364(a6)                   ; EVERY pending
.check_after:
	lea	aTIMER(pc),a0                   ; AFTER timer
	move.l	(a0),d0                         ; target
	beq.s	.done                           ; off
	cmp.l	$4ba.w,d0                       ; _hz_200, past?
	bcc.s	.done                           ; not yet
	clr.l	(a0)+                           ; switch it off
	clr.l	(a0)
	bset	#$3,$1364(a6)                   ; AFTER pending
.done:
	movem.l	(sp)+,d3-d4/a6
	rts

;------------------------------------------------------------------------------
; Digit of each of the keypad keys 7 8 9 4 5 6 1 2 3 0, as data (disassembled as instructions).
;------------------------------------------------------------------------------
keyirq_keypad_digits:
	movep.w	$904(a0),d3                     ; keypad digits, not code
	btst	d2,d6
	btst	d0,d2
	btst	d1,d0

;------------------------------------------------------------------------------
; Key codes the eleven keypad keys become under num lock, as data (disassembled as instructions).
;------------------------------------------------------------------------------
keyirq_keypad_codes:
	subi.w	#$0,$48(sp,d0.w)                ; keypad key codes, not code
	dc.w	$0000,$0448,$0000,$004b,$0000,$0000,$0000,$004d
	dc.w	$0000
	subi.b	#$1a,(a5)+
	ori.w	#$0,(a0)
	subi.w	#$0,(a0)
	ori.w	#$0,(a2)
	ori.b	#$7f,(a5)+

;------------------------------------------------------------------------------
; Keypad ( or -: with Ctrl, when allowed, toggles the num lock and drops the key.
;------------------------------------------------------------------------------
keyirq_numlock_key:
	btst	#$a,d3                          ; Ctrl held?
	beq.s	keyirq_to_timers                ; no: keep the key
	btst	#$1,d4                          ; toggle allowed?
	beq.s	keyirq_to_timers                ; no
	dc.w	$0879,$0000,$0000,$0000         ; bchg #$0,$0 -> NumLOCK (filled in by the linker), bchg #$0,$0 ->
                                                ;   NumLOCK (filled in by the linker), toggle the num lock
	bra.w	keyirq_drop_key                 ; drop the key

;------------------------------------------------------------------------------
; Alternate let go after a keypad code: puts the code into the buffer as a key.
;------------------------------------------------------------------------------
keyirq_put_alt_code:
	clr.w	keyirq_alt_code_high-m_keyirq   ; code consumed
	addq.w	#4,d2                           ; next tail
	cmp.w	d0,d2
	bcs.s	.check_full
	moveq	#0,d2                           ; wrap
.check_full:
	cmp.w	d1,d2                           ; full?
	beq.s	keyirq_to_timers                ; yes: lost
	move.w	d2,4(a0)                        ; new tail
	move.l	d3,0(a1,d2.w)                   ; the code as a key

keyirq_to_timers:
	bra.w	keyirq_check_timers

;------------------------------------------------------------------------------
; Function key with a KEYDEF text: replaces the key with the text's characters (Esc and Return get
; their scan codes) as far as the buffer has room.
; Entry: d3.b = key number 0-19
;------------------------------------------------------------------------------
keyirq_type_keydef:
	ext.w	d3
	asl.w	#5,d3                           ; * 32
	pea	(a3)                            ; keep a3
	lea	$0,a3                           ; KEYDEF texts (relocated)
	adda.w	d3,a3                           ; this key's text
.next_char:
	moveq	#0,d3
	move.b	(a3)+,d3                        ; next character
	beq.s	.done                           ; end of the text
	move.w	d2,4(a0)                        ; tail at this entry
	cmpi.b	#$1b,d3                         ; Esc?
	bne.s	.check_return                   ; no
	bset	#$10,d3                         ; with scan code 1
.check_return:
	cmpi.b	#$d,d3                          ; CR?
	bne.s	.store_char                     ; no
	move.l	#$1c000d,d3                     ; Return key code
.store_char:
	move.l	d3,0(a1,d2.w)                   ; into the buffer
	addq.w	#4,d2                           ; next tail
	cmp.w	d0,d2
	bcs.s	.check_full
	moveq	#0,d2                           ; wrap
.check_full:
	cmp.w	d1,d2                           ; full?
	bne.s	.next_char                      ; no: next character
.done:
	movea.l	(sp)+,a3                        ; a3 back
	bra.w	keyirq_check_timers             ; timers

; Alternate-keypad character code being built (high byte of the word the code is multiplied from).
keyirq_alt_code_high:
	dc.b	$00

; Alternate-keypad character code being built.
keyirq_alt_code:
	dc.b	$00

;------------------------------------------------------------------------------
; IRQON: installs the keyboard and timer handlers (once): ikbdsys, etv_timer and etv_critic hooks,
; conterm bit 3, NumLOCK $2e, and the IRQPATCH jump to IRQCHK; IRQOFF becomes the exit routine.
;------------------------------------------------------------------------------
IRQON:
	lea	IRQOFF(pc),a0
	dc.w	$43f9,$0000,$0000               ; lea $0,a1 -> ExitAdr (filled in by the linker), lea $0,a1 -> ExitAdr
                                                ;   (filled in by the linker), exit routine
	cmpa.l	(a1),a0                         ; installed already?
	beq.s	.done                           ; yes
	move.l	a0,(a1)                         ; IRQOFF runs at the end
	pea	$e0001                          ; Iorec, device 1: keyboard
	trap	#14                             ; XBIOS
	move.l	d0,keyirq_keyboard_iorec+2-m_keyirq ; into the check routine
	dc.w	$13fc,$002e,$0000,$0000         ; move.b #$2e,$0 -> NumLOCK (filled in by the linker), move.b #$2e,$0 ->
                                                ;   NumLOCK (filled in by the linker), NumLOCK flags $2e
	move.w	#$22,(sp)                       ; Kbdvbase
	trap	#14                             ; XBIOS
	movea.l	d0,a0                           ; vector table
	lea	$20(a0),a0                      ; ikbdsys
	lea	keyirq_ikbd_hook(pc),a1         ; our hook
	move.l	(a0),2(a1)                      ; old handler into its jsr
	move.l	a1,(a0)                         ; install it
	clr.l	(sp)                            ; Super(0)
	move.w	#$20,-(sp)
	trap	#1                              ; Super
	addq.l	#6,sp
	move.l	d0,keyirq_saved_ssp-m_keyirq    ; keep the supervisor stack
	move.l	d0,-(sp)
	bsr.s	keyirq_install_vectors          ; install the vectors
	move.w	#$20,-(sp)                      ; back to user mode
	trap	#1                              ; Super, Super
	addq.l	#6,sp
	dc.w	$41f9,$0000,$0000               ; lea	$0,a0 -> IRQPATCH (filled in by the linker)
