	btst	d5,(a0)                         ; first set?
	beq.s	.first_clear                    ; no
	btst	d4,(a1)                         ; second set too?
	bne.s	.done                           ; yes: equal
.exchange:
	bchg	d4,(a1)                         ; flip the second
	bchg	d5,(a0)                         ; flip the first
.done:
	rts
.first_clear:
	btst	d4,(a1)                         ; second set?
	bne.s	.exchange                       ; yes: they differ
	rts

