	bne.s	.done                           ; yes: equal
	st	(a1)                            ; variable TRUE
	bclr	d5,(a0)                         ; element clear
.done:
	rts
.bit_clear:
	tst.b	(a1)                            ; variable FALSE too?
	beq.s	.done                           ; yes: equal
	sf	(a1)                            ; variable FALSE
	bset	d5,(a0)                         ; element set
	rts

