; Ends the program after an error: the error number (sign-extended) becomes the exit code.
;------------------------------------------------------------------------------
error_terminate:
	moveq	#-1,d0                          ; upper bytes all set
	move.b	$6,d0                           ; error number in the low byte

error_call_system:
	dc.w	$6000,$0000                     ; bra.w error_call_system+2 -> SYSTEMN (filled in by the linker), end
                                                ;   the program with that code

;------------------------------------------------------------------------------
; Resets the runtime registers, empties the local stack (a3 = its base, the end of the arrays) and puts sp back at the
; top of the runtime stack, then returns to the caller.
; Exit: a3-a6 and sp reset; a0, d2 used
;------------------------------------------------------------------------------
reset_runtime_stacks:
	movea.l	(sp)+,a0                        ; return address
	bsr.s	load_runtime_registers          ; a4, a5 and a6
	movea.l	$1a(a6),a3                      ; local stack empty
	lea	$3a84(a6),sp                    ; runtime stack top
	jmp	(a0)                            ; return

;------------------------------------------------------------------------------
; Points a4 at the runtime library + $8000, a5 at the variables + $8000 and a6 at the runtime block.
; Exit: a4-a6 set; d2 used
;------------------------------------------------------------------------------
load_runtime_registers:
	dc.w	$4df9,$0000,$0000               ; lea	$0,a6 -> BssA6 (filled in by the linker), runtime block
	dc.w	$49f9,$0000,$0000               ; lea	$0,a4 -> BaseA4 (filled in by the linker), runtime library
	dc.w	$4bf9,$0000,$0000               ; lea	$0,a5 -> BssA5 (filled in by the linker), variables
	move.l	#$8000,d2                       ; both + $8000
	adda.l	d2,a4                           ; a4 = library + $8000
	adda.l	d2,a5                           ; a5 = variables + $8000
	rts                                     ; done

; Text of the runtime error alert: "[1][Error " followed by four characters for the number (written in place) and
; "][Return]".
error_alert_start:
	dc.b	'[1][Error '
error_alert_number:
	dc.w	$2b31,$3131                     ; data: '+111', overwritten with the number
error_alert_end:
	dc.b	'][Return]',0

;------------------------------------------------------------------------------
; ERRTEX: builds the alert text for a runtime error. A message from the
; error table becomes "[1][text][Return]" in the text buffer; otherwise
; the number is written into error_alert_number.
; Entry: d0.b = error number
; Exit: a1 -> alert text
;------------------------------------------------------------------------------
ERRTEX:
	lea	REGS-m_error,a2                 ; a2 -> message table; the reference shows as REGS here, not clear
.find_error:
	move.b	(a2)+,d1                        ; error number of the entry; $7f ends the table
	cmpi.b	#$7f,d1                         ; $7f ends the table
	beq.s	.number_alert                   ; not found: show the number
	cmp.b	d0,d1                           ; this error?
	beq.s	.text_alert                     ; found: show its text
.skip_text:
	tst.b	(a2)+                           ; skip its text
	bne.s	.skip_text                      ; to its zero
	bra.s	.find_error                     ; next entry
.number_alert:
	lea	error_alert_number(pc),a0       ; "[1][Error " and the number: sign and three digits
	moveq	#32,d1                          ; sign: space
	ext.w	d0                              ; as a word
	bpl.s	.write_digits                   ; positive
	moveq	#45,d1                          ; negative: minus
	neg.w	d0
.write_digits:
	move.b	d1,(a0)+                        ; store the sign
	ext.l	d0                              ; as a long for divu
	divu.w	#$64,d0                         ; hundreds
	ori.b	#$30,d0                         ; ASCII digit
	move.b	d0,(a0)+                        ; store it
	swap	d0                              ; remainder
	ext.l	d0                              ; as a long
	divu.w	#$a,d0                          ; tens
	ori.b	#$30,d0                         ; ASCII digit
	move.b	d0,(a0)+                        ; store it
	swap	d0                              ; units
	ori.b	#$30,d0                         ; units
	move.b	d0,(a0)+                        ; store it
	lea	error_alert_start(pc),a1        ; a1 -> "[1][Error snnn][Return]"
	rts                                     ; done
.text_alert:
	lea	$46(a6),a0                      ; build in the scratch buffer
	movea.l	a0,a1                           ; a1 -> alert text
	move.l	#$5b315d5b,(a0)+                ; "[1][" then the table text
.copy_text:
	move.b	(a2)+,(a0)+                     ; copy the message
	bne.s	.copy_text                      ; up to the zero
	subq.l	#1,a0                           ; back onto the zero
	lea	error_alert_end(pc),a2          ; then "][Return]"
.copy_end:
	move.b	(a2)+,(a0)+                     ; copy it with its zero
	bne.s	.copy_end                       ; up to the zero
	rts                                     ; done

