	dc.w	$a200				; defined global text
	dc.l	$e
	dc.b	$45,$4d,$53,$4e,$45,$00,$00,$00		; EMSNE
	dc.w	$a200				; defined global text
	dc.l	$e
	dc.b	$45,$4d,$53,$47,$45,$00,$00,$00		; EMSGE
	dc.w	$a200				; defined global text
	dc.l	$14
	dc.b	$45,$4d,$53,$4c,$54,$00,$00,$00		; EMSLT
	dc.w	$a200				; defined global text
	dc.l	$1a
	dc.b	$58,$53,$74,$72,$4b,$69,$6c,$6c		; XStrKill
	dc.w	$8800				; defined external
	dc.l	$0
; relocation words, one a code word: 0 none, 1 data, 2 text, 3 bss, 4 external, 5 a long (its low
; word tells), 6 external pc-relative, 7 the first word of an instruction; an external's symbol
; number is the word >> 3
	dc.w	$0000,$0036,$0000,$0000,$0000,$0000,$0000,$0000
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000

;==============================================================================
; Module DEFNUM.O: 12 bytes of code, 0 of data, 0 of bss; exports DEFNUM
;==============================================================================
	dc.b	$44,$45,$46,$4e,$55,$4d,$2e,$4f,$00,$00,$00,$00,$00,$00	; library entry: the name DEFNUM.O
	dc.w	$7cb3,$12cb,$0000,$01b6,$0000,$0042,$0000	; entry: the rest (the member's length at +8)
	dc.w	$601a				; DRI object module
	dc.l	$c,$0,$0,$e		; text, data and bss lengths, symbol table length
	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_defnum:
;------------------------------------------------------------------------------
; DEFNUM n: sets the number of digits PRINT shows; values below 3 are ignored.
; Entry: d0 = n
;------------------------------------------------------------------------------
DEFNUM:
	cmpi.w	#$3,d0                          ; below 3?
	bcs.s	.done                           ; yes: ignore
	move.w	d0,$164(a6)                     ; digits for PRINT
.done:
	rts

; symbol table: name, type, value
	dc.b	$44,$45,$46,$4e,$55,$4d,$00,$00		; DEFNUM
	dc.w	$a200				; defined global text
	dc.l	$0
; relocation words, one a code word: 0 none, 1 data, 2 text, 3 bss, 4 external, 5 a long (its low
; word tells), 6 external pc-relative, 7 the first word of an instruction; an external's symbol
; number is the word >> 3
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000

;==============================================================================
; Module DIM.O: 618 bytes of code, 0 of data, 0 of bss; exports DIMS, DIMB, DIMC, DIMW, DIMF, DIMI, DimDELET
;==============================================================================
	dc.b	$44,$49,$4d,$2e,$4f,$00,$00,$00,$00,$00,$00,$00,$00,$00	; library entry: the name DIM.O
	dc.w	$6524,$12fb,$0000,$01b6,$0000,$056e,$0000	; entry: the rest (the member's length at +8)
	dc.w	$601a				; DRI object module
	dc.l	$26a,$0,$0,$7e		; text, data and bss lengths, symbol table length
	dc.w	$0000,$0000,$0000,$0000,$0000	; the rest of the header
m_dim:
;------------------------------------------------------------------------------
; DIM of a string array ($): 6-byte descriptors per element.
; Entry: a0 = array descriptor, d7 = number of dimensions, d0 = last upper bound, d1-d6 = the other bounds.
; Exit: as dim_array.
;------------------------------------------------------------------------------
dim_string_array:
	lea	$fffffffe.w,a1                  ; element code: strings
	bra.s	dim_array

;------------------------------------------------------------------------------
; DIM of a boolean array (!): one bit per element.
; Entry: a0 = array descriptor, d7 = number of dimensions, d0 = last upper bound, d1-d6 = the other bounds.
; Exit: as dim_array.
;------------------------------------------------------------------------------
dim_boolean_array:
	lea	$ffffffff.w,a1                  ; element code: bits
	bra.s	dim_array

;------------------------------------------------------------------------------
; DIM of a byte array (|).
; Entry: a0 = array descriptor, d7 = number of dimensions, d0 = last upper bound, d1-d6 = the other bounds.
; Exit: as dim_array.
;------------------------------------------------------------------------------
dim_byte_array:
	suba.l	a1,a1                           ; element code: bytes
	bra.s	dim_array

;------------------------------------------------------------------------------
; DIM of a word array (&). dim_float_array after it is DIM of a float array (#), 8 bytes per element.
; Entry: a0 = array descriptor, d7 = number of dimensions, d0 = last upper bound, d1-d6 = the other bounds.
; Exit: as dim_array.
;------------------------------------------------------------------------------
dim_word_array:
	lea	$1.w,a1                         ; element code: words
	bra.s	dim_array

;------------------------------------------------------------------------------
; DIM of a float array (8 bytes per element).
; Entry: as dim_array
;------------------------------------------------------------------------------
dim_float_array:
	lea	$3.w,a1                         ; element code: floats
	bra.s	dim_array

;------------------------------------------------------------------------------
; DIM of a long integer array (%).
; Entry: a0 = array descriptor, d7 = number of dimensions, d0 = last upper bound, d1-d6 = the other bounds.
; Exit: as dim_array.
;------------------------------------------------------------------------------
dim_long_array:
	lea	$2.w,a1                         ; element code: longs

;------------------------------------------------------------------------------
; DIM: works out the element count from the bounds (each + 1 unless OPTION BASE 1) and the size from the element code
; (-2 string descriptors of 6 bytes, -1 bits, 0 bytes, 1 words, 2 longs, 3 floats); error 8 when it is too big. The
; array goes into the heap below the local stack, its bounds are written in front of the elements and the elements
; cleared. An array that is already dimensioned goes to the error exit.
; Entry: a0 = array descriptor, a1 = element code, d7 = dimensions, d0 = last upper bound, d1-d6 = the other bounds
; Exit: array allocated
;------------------------------------------------------------------------------
dim_array:
	tst.w	4(a0)                           ; dimensioned already?
	bne.w	dim_redimension_error           ; yes: error
	tst.l	$e(a6)                          ; OPTION BASE 1: bounds as given
	bne.s	.bounds_set
	addq.l	#1,d0                           ; bounds + 1
	addq.l	#1,d1
	addq.l	#1,d2
	addq.l	#1,d3
	addq.l	#1,d4
	addq.l	#1,d5
	addq.l	#1,d6
.bounds_set:
	pea	(a0)                            ; keep the descriptor
	move.w	a1,-(sp)                        ; keep the element code
	exg	d7,d0                           ; d0 = dimensions, d7 = last bound
	lea	$46(a6),a1                      ; bounds into the text buffer
	movem.l	d1-d6,(a1)
	move.w	d0,d4                           ; dimensions
	move.w	d4,d5
	asl.w	#2,d5                           ; * 4
	move.l	d7,-$4(a1,d5.w)                 ; last bound after the others
	move.l	#$ffff,d3                       ; largest bound
	move.w	(sp),d1                         ; element code
	move.l	(a1)+,d0                        ; first bound
	bra.s	.next_bound
.multiply_bounds:
	cmp.l	d3,d0                           ; too large?
	bhi.w	dim_redimension_error           ; yes: error
	move.l	(a1)+,d2                        ; next bound
	cmp.l	d3,d2                           ; too large?
	bhi.w	dim_redimension_error           ; yes: error
	mulu.w	d2,d0                           ; count * bound
.next_bound:
	subq.w	#4,d5
	bne.s	.multiply_bounds                ; more?
	bra.s	dim_element_size

;------------------------------------------------------------------------------
; Size for the bit and string element codes (-1 and -2).
;------------------------------------------------------------------------------
dim_bits_or_strings:
	addq.w	#1,d1                           ; bits?
	bne.s	.string_size                    ; no: strings
	moveq	#15,d1                          ; bits: whole words
	add.l	d1,d0
	lsr.l	#4,d0                           ; / 16
	add.l	d0,d0                           ; * 2 bytes
	bra.s	dim_allocate
.string_size:
	add.l	d0,d0                           ; descriptors: 6 bytes each
	bcs.s	dim_too_big
	move.l	d0,d1
	add.l	d0,d0
	bcs.s	dim_too_big
	add.l	d1,d0
	bcc.s	dim_allocate

;------------------------------------------------------------------------------
; Array too big: error 8.
;------------------------------------------------------------------------------
dim_too_big:
	moveq	#8,d0                           ; error 8: out of memory

dim_raise_error:
	dc.w	$6000,$0000                     ; bra.w dim_raise_error+2 -> ERROR (filled in by the linker), bra.w
                                                ;   m_dim_loc_0094+2 -> ERROR (filled in by the linker), raise it

;------------------------------------------------------------------------------
; Size for the other element codes: count << code, a byte array rounded to an even count.
;------------------------------------------------------------------------------
dim_element_size:
	tst.w	d1                              ; element code
	bmi.s	dim_bits_or_strings             ; bits or strings
	bne.s	.shift_size                     ; bytes: an even count
	btst	#$0,d0
	beq.s	.shift_size
	addq.l	#1,d0
.shift_size:
	asl.l	d1,d0                           ; count << code
	bcs.s	dim_too_big                     ; too big

;------------------------------------------------------------------------------
; Adds the header and bounds, makes room in the heap and fills in the block and the descriptor.
;------------------------------------------------------------------------------
dim_allocate:
	moveq	#8,d1                           ; bounds and header in front
	move.w	d4,-(sp)                        ; keep the dimensions
	asl.w	#2,d4
	add.w	d4,d1
	add.l	d1,d0                           ; block size
	bsr.w	fix_pointers_for_insert         ; fix the pointers above
	lea	$1a(a6),a0                      ; end of the arrays

dim_call_allot:
	dc.w	$6100,$0000                     ; bsr.w dim_call_allot+2 -> ALLOT (filled in by the linker), room in the
                                                ;   heap at the end of the arrays
	move.w	(sp)+,d4                        ; dimensions
	movea.l	a0,a2                           ; block start
	addq.l	#4,a0
	move.l	d0,(a0)+                        ; block size
	move.w	d4,d5
	lea	$46(a6),a1                      ; bounds
	asl.w	#2,d5
	adda.w	d5,a1
	bra.s	.next_copy
.copy_bound:
	move.l	-(a1),(a0)+                     ; copy a bound
.next_copy:
	subq.w	#4,d5
	bpl.s	.copy_bound
	addq.l	#2,sp                           ; drop the element code
	movea.l	(sp)+,a1                        ; descriptor
	move.l	a1,(a2)                         ; back pointer to it
	addq.l	#8,a2                           ; past the header
	move.l	a2,(a1)+                        ; descriptor: bounds pointer
	move.w	d4,(a1)+                        ; dimensions
	moveq	#0,d2                           ; clear the elements
	moveq	#8,d1
	asl.w	#2,d4
	add.w	d4,d1                           ; header + bounds
	sub.l	d1,d0                           ; bytes of elements
	lsr.l	#2,d0                           ; bit 1: a word
	bcc.s	.clear_long
	move.w	d2,(a0)+
.clear_long:
	lsr.l	#1,d0                           ; bit 2: a long
	bcc.s	.clear_eight
	move.l	d2,(a0)+
.clear_eight:
	lsr.l	#1,d0                           ; bit 3: two longs
	bcc.s	.clear_blocks
	move.l	d2,(a0)+
	move.l	d2,(a0)+
.clear_blocks:
	lsr.l	#1,d0                           ; bit 4: four longs
	bcc.s	.count_blocks
	bra.s	.clear_sixteen
.clear_loop:
	move.l	d2,(a0)+                        ; 32 bytes at a time
	move.l	d2,(a0)+
	move.l	d2,(a0)+
	move.l	d2,(a0)+
.clear_sixteen:
	move.l	d2,(a0)+
	move.l	d2,(a0)+
	move.l	d2,(a0)+
	move.l	d2,(a0)+
.count_blocks:
	dbra	d0,.clear_loop
	subi.l	#$10000,d0                      ; high word of the count
	bpl.s	.clear_loop
	rts

;------------------------------------------------------------------------------
; Array already dimensioned (or a bound too large): to the error exit with the error number in d0 as it stands.
;------------------------------------------------------------------------------
dim_redimension_error:
	dc.w	$6000,$0000                     ; bra.w dim_redimension_error+2 -> ERROR (filled in by the linker),
                                                ;   bra.w m_dim_loc_0128+2 -> ERROR (filled in by the linker), error
                                                ;   exit

;------------------------------------------------------------------------------
; Drops the strings owned by an array block that is being removed, then moves the pointers into the array area down by
; the block size.
; Entry: a0 = block start, d0 = block size.
;------------------------------------------------------------------------------
release_array_strings:
	bsr.w	compact_strings_removing
	neg.l	d0                              ; lower instead of raise
	bsr.s	fix_local_stack_pointers
	neg.l	d0
	rts

;------------------------------------------------------------------------------
; Before heap space is inserted at the end of the arrays: fixes the string heap's back pointers and the pointers on the
; local stack that point above it by d0.
; Entry: d0.l = size of the insertion
;------------------------------------------------------------------------------
fix_pointers_for_insert:
	movea.l	$1a(a6),a0                      ; end of the arrays
	bsr.s	compact_strings_adjusting

;------------------------------------------------------------------------------
; Walks the local stack from a3 down to its base and adds d0 to every saved pointer and variable cell that points into
; the local stack area.
; Entry: d0.l = distance, a3 = local stack top
;------------------------------------------------------------------------------
fix_local_stack_pointers:
	movea.l	a3,a0                           ; from the top
	movea.l	$1a(a6),a1                      ; to the base
.check_end:
	cmpa.l	a0,a1                           ; reached the base?
	beq.s	.done                           ; yes
.next_entry:
	move.w	-(a0),d1                        ; tag
	movea.l	-(a0),a2                        ; saved pointer
	beq.s	.check_end                      ; 0: frame end
	bmi.s	.special_tag                    ; negative: special tag
	movea.l	a0,a3
	suba.w	d1,a3                           ; start of the entry
	cmpa.l	(a2),a3                         ; cell points at it?
	beq.s	.adjust_cell                    ; yes
	cmpi.w	#$4,d1                          ; 4-byte entry?
	bne.s	.check_saved                    ; no
	cmpa.l	(a2),a1
	bcc.s	.check_saved
	cmpa.l	(a2),a0
	bcs.s	.check_saved
.adjust_cell:
	add.l	d0,(a2)                         ; move the cell
.check_saved:
	movea.l	-(a0),a2                        ; saved value
	cmpa.l	a1,a2                           ; inside the local stack?
	bcs.s	.advance                        ; no
	cmpa.l	a0,a2
	bhi.s	.advance                        ; no
	add.l	d0,(a0)                         ; move it
.advance:
	suba.w	d1,a0                           ; past the entry
	addq.l	#4,a0
	cmpa.l	a0,a1                           ; at the base?
	bne.s	.next_entry                     ; no
.done:
	movea.l	$1e(a6),a3                      ; a3 back
	rts
.special_tag:
	cmpi.w	#$ffff,d1                       ; frame marker?
	beq.s	.frame                          ; yes
	cmpa.l	a1,a2                           ; inside the local stack?
	bcs.s	.skip_entry                     ; no
	cmpa.l	a0,a2
	bhi.s	.skip_entry                     ; no
	add.l	d0,(a0)                         ; move it
.skip_entry:
	lea	4(a0,d1.w),a0                   ; past the entry
	bra.s	.check_end
.frame:
	suba.l	a2,a0                           ; back over the frame
	bra.s	.check_end

;------------------------------------------------------------------------------
; Compacts the string heap toward its end, dropping free blocks, and adds d0 to every descriptor pointer above d2 on the
; way.
; Entry: a0 = boundary address, d0.l = distance
; Exit: bottom of the string space ($22(a6)) updated
;------------------------------------------------------------------------------
compact_strings_adjusting:
	move.l	a3,$1e(a6)                      ; keep a3
	moveq	#-2,d4                          ; even mask
	move.l	a0,d2                           ; boundary
	movea.l	$26(a6),a0                      ; top of the string heap
	movea.l	$22(a6),a2                      ; bottom of the string space
.next_block:
	movea.l	a0,a1                           ; destination
	cmpa.l	a0,a2                           ; at the bottom?
	beq.s	.done                           ; yes
	move.l	-(a0),d1                        ; back pointer
	movea.l	d1,a3                           ; descriptor
	bmi.s	.skip_free                      ; negative: free
	cmp.l	d2,d1                           ; above the boundary?
	bls.s	.follow_owner                   ; no
	add.l	d0,(a0)                         ; move the pointer
.follow_owner:
	movea.l	(a3),a0                         ; back to the descriptor's text
	bra.s	.next_block
.skip_free:
	adda.l	d1,a0                           ; skip the free block
	cmpa.l	a0,a2                           ; at the bottom?
	beq.s	.done                           ; yes
.next_string:
	move.l	-(a0),d1                        ; back pointer
	bmi.s	.skip_free                      ; free block
	move.l	d1,-(a1)                        ; keep it
	movea.l	d1,a3                           ; descriptor
	cmp.l	d2,d1                           ; above the boundary?
	bls.s	.move_string                    ; no
	add.l	d0,(a1)                         ; move the pointer
.move_string:
	move.w	4(a3),d1                        ; length
	subq.w	#1,d1
	lsr.w	#1,d1                           ; in words
.copy_word:
	move.w	-(a0),-(a1)                     ; move the text up
	dbra	d1,.copy_word
	move.l	a1,(a3)                         ; descriptor points at the new place
	cmpa.l	a0,a2                           ; at the bottom?
	bne.s	.next_string                    ; no
.done:
	move.l	a1,$22(a6)                      ; new bottom of the string space
	movea.l	$1e(a6),a3                      ; a3 back
	rts

;------------------------------------------------------------------------------
; Compacts the string heap for ERASE: strings whose descriptors lie in the removed area (a0 to a0 + d0) are dropped,
; descriptor pointers above it lowered by d0.
; Entry: a0 = start of the removed area, d0.l = its size
;------------------------------------------------------------------------------
compact_strings_removing:
	move.l	a3,$1e(a6)                      ; keep a3
	moveq	#-2,d4                          ; even mask
	move.l	a0,d2                           ; start of the removed area
	move.l	d2,d3
	add.l	d0,d3                           ; end of it
	movea.l	$26(a6),a0                      ; top of the string heap
	movea.l	$22(a6),a2                      ; bottom of the string space
.next_block:
	movea.l	a0,a1                           ; destination
	cmpa.l	a0,a2                           ; at the bottom?
	beq.s	.done                           ; yes
	move.l	-(a0),d1                        ; back pointer
	bmi.s	.skip_free                      ; negative: free
	movea.l	d1,a3                           ; descriptor
	cmp.l	d2,d1                           ; below the removed area?
	bls.s	.follow_owner                   ; yes
	cmp.l	d3,d1                           ; above it?
	bhi.s	.lower_pointer                  ; yes
	movea.l	(a3),a0                         ; inside: the string goes
	bra.s	.check_end
.lower_pointer:
	sub.l	d0,(a0)                         ; lower the pointer
.follow_owner:
	movea.l	(a3),a0
	bra.s	.next_block
.skip_free:
	adda.l	d1,a0                           ; skip the free block
.check_end:
	cmpa.l	a0,a2                           ; at the bottom?
	beq.s	.done                           ; yes
.next_string:
	move.l	-(a0),d1                        ; back pointer
	bmi.s	.skip_free                      ; free block
	move.l	d1,-(a1)                        ; keep it
	movea.l	d1,a3                           ; descriptor
	cmp.l	d2,d1                           ; below the removed area?
	bls.s	.move_string                    ; yes: move it as it is
	cmp.l	d3,d1                           ; above it?
	bhi.s	.lower_moved                    ; yes
	moveq	#1,d1                           ; inside: dropped
	add.w	4(a3),d1
	and.b	d4,d1                           ; to even
	suba.l	d1,a0                           ; skip its text
	addq.l	#4,a1                           ; back pointer not kept
	bra.s	.check_end
.lower_moved:
	sub.l	d0,(a1)                         ; lower the pointer
.move_string:
	move.w	4(a3),d1                        ; length
	subq.w	#1,d1
	lsr.w	#1,d1                           ; in words
.copy_word:
	move.w	-(a0),-(a1)                     ; move the text up
	dbra	d1,.copy_word
	move.l	a1,(a3)                         ; descriptor points at the new place
	cmpa.l	a0,a2                           ; at the bottom?
	bne.s	.next_string                    ; no
.done:
	move.l	a1,$22(a6)                      ; new bottom of the string space
	movea.l	$1e(a6),a3                      ; a3 back
	rts

; symbol table: name, type, value
	dc.b	$44,$49,$4d,$53,$00,$00,$00,$00		; DIMS
	dc.w	$a200				; defined global text
	dc.l	$0
	dc.b	$44,$49,$4d,$42,$00,$00,$00,$00		; DIMB
	dc.w	$a200				; defined global text
	dc.l	$6
	dc.b	$44,$49,$4d,$43,$00,$00,$00,$00		; DIMC
	dc.w	$a200				; defined global text
	dc.l	$c
	dc.b	$44,$49,$4d,$57,$00,$00,$00,$00		; DIMW
	dc.w	$a200				; defined global text
	dc.l	$10
	dc.b	$44,$49,$4d,$46,$00,$00,$00,$00		; DIMF
	dc.w	$a200				; defined global text
	dc.l	$16
	dc.b	$44,$49,$4d,$49,$00,$00,$00,$00		; DIMI
	dc.w	$a200				; defined global text
	dc.l	$1c
	dc.b	$44,$69,$6d,$44,$45,$4c,$45,$54		; DimDELET
	dc.w	$a200				; defined global text
	dc.l	$12c
	dc.b	$45,$52,$52,$4f,$52,$00,$00,$00		; ERROR
	dc.w	$8800				; defined external
	dc.l	$0
	dc.b	$41,$4c,$4c,$4f,$54,$00,$00,$00		; ALLOT
	dc.w	$8800				; defined external
	dc.l	$0
