	subq.w	#1,$127a(a6)
	bpl.s	pusing_field_scan
	bra.w	pusing_number_no_field          ; end: no field
.check_digit:
	cmpi.b	#$23,d0                         ; #?
	beq.s	pusing_field_digit
	cmpi.b	#$24,d0                         ; $?
	beq.s	pusing_field_dollar
	cmpi.b	#$2a,d0                         ; *?
	beq.s	pusing_field_star
	cmp.b	$617(a6),d0                     ; thousands separator?
	beq.s	pusing_field_scan
	cmpi.b	#$5e,d0                         ; ^?
	beq.s	.count_exponent
	cmpi.b	#$2b,d0                         ; +?
	beq.s	.trailing_sign
	cmpi.b	#$2d,d0                         ; -?
