	cmpi.b	#$23,d0                         ; #?
	beq.s	.count_decimals
	cmpi.b	#$5e,d0                         ; ^?
	beq.s	.count_exponent
	cmpi.b	#$2b,d0                         ; +?
	beq.s	.trailing_sign
	cmpi.b	#$2d,d0                         ; -?
	beq.s	.trailing_sign
	cmpi.b	#$5f,d0                         ; _?
