	move.b	(a1)+,d0                        ; next character
	subq.w	#1,$127a(a6)
	bmi.s	.field_end                      ; end
	cmpi.b	#$5e,d0                         ; ^?
	beq.s	.count_exponent
	cmpi.b	#$2b,d0                         ; +?
	beq.s	.trailing_sign
	cmpi.b	#$2d,d0                         ; -?
