;------------------------------------------------------------------------------
; ERASE: removes a dimensioned array. Drops its strings, fixes the pointers above it, walks the array descriptors of all
; variables (counts from the variable type table) to move those above it down and clear its own, then moves the rest of
; the array area down over it.
; Entry: a0 = array descriptor.
; Exit: array area and heap top lowered.
;------------------------------------------------------------------------------
erase_array:
	movea.l	a0,a1                           ; descriptor
	movea.l	(a1)+,a0                        ; bounds pointer
	tst.w	(a1)                            ; dimensioned?
	bne.s	.remove                         ; yes
	rts                                     ; no: nothing to do
.remove:
	move.l	-(a0),d0                        ; block size
	subq.l	#4,a0                           ; block start
	movem.l	d0/a0,-(sp)                     ; keep size and start

erase_call_dimdelet:
	dc.w	$6100,$0000                     ; bsr.w erase_call_dimdelet+2 -> DimDELET (filled in by the linker),
                                                ;   drop its strings, fix pointers
	movem.l	(sp),d0/a0                      ; size and start again
	addq.l	#8,a0                           ; past the header
	moveq	#-2,d6                          ; mask for rounding to even
	movem.l	a1/a3,-(sp)                     ; keep a1 and a3
	dc.w	$47f9,$0000,$0000               ; lea	$0,a3 -> TYPETAB (filled in by the linker), variable type counts
	lea	-$8000(a5),a1                   ; the variables
	move.l	(a3)+,d3                        ; skip the plain variables, 4 bytes each
	add.l	(a3)+,d3
	add.l	(a3)+,d3
	add.l	(a3)+,d3
	add.l	(a3)+,d3
	add.l	(a3)+,d3
	move.l	d3,d4                           ; add the high and low word counts
	swap	d4
	add.w	d4,d3
	asl.w	#2,d3                           ; * 4 bytes a cell
	adda.w	d3,a1                           ; past the cells
	clr.w	-(sp)                           ; pass flag
.next_pass:
	move.w	(a3)+,d3                        ; skip more variables
	asl.w	#3,d3                           ; * 8: floats
	adda.w	d3,a1                           ; past them
	moveq	#6,d3                           ; 6 bytes a string
	mulu.w	(a3)+,d3
	adda.w	d3,a1                           ; past them
	move.w	(a3)+,d3
	asl.w	#2,d3                           ; integers * 4
	add.w	(a3)+,d3                        ; + booleans
	addq.w	#1,d3                           ; round up
	and.w	d6,d3                           ; to even
	adda.w	d3,a1                           ; past them
	move.w	(a3)+,d4                        ; array descriptors of the first kinds
	add.w	(a3)+,d4
	add.w	(a3)+,d4
	add.w	(a3)+,d4
	bsr.s	fix_array_descriptors           ; fix them
	move.w	(a3)+,d3                        ; words
	add.w	d3,d3                           ; * 2
	add.w	(a3)+,d3                        ; + bytes
	addq.w	#1,d3                           ; round up
	and.w	d6,d3                           ; to even
	adda.w	d3,a1                           ; past them
	move.w	(a3)+,d4                        ; array descriptors of the other kinds
	add.w	(a3)+,d4
	bsr.s	fix_array_descriptors           ; fix them
	dc.w	$47f9,$0000,$0000               ; lea	$0,a3 -> TYPETAB (filled in by the linker)
	not.w	(sp)                            ; two passes
	bne.s	.next_pass                      ; second pass
	addq.l	#2,sp                           ; drop the flag
	movem.l	(sp)+,a1/a3                     ; a1, a3 back
	movem.l	(sp)+,d1/a1                     ; d1 = block size, a1 = block start
	sub.l	d1,$1a(a6)                      ; end of the arrays lower
	suba.l	d1,a3                           ; heap top lower
	move.l	a3,$1e(a6)                      ; new local stack top
	lea	0(a1,d1.l),a0                   ; data above the block ...
	move.l	a3,d0                           ; ... up to the heap top
	sub.l	a1,d0                           ; bytes to move

erase_call_ldire:
	dc.w	$6000,$0000                     ; bra.w erase_call_ldire+2 -> Ldire (filled in by the linker), moves
                                                ;   down over the block

;------------------------------------------------------------------------------
; One array descriptor (pointer .l, dimensions .w): above the removed block it moves down by d0; if it is the removed
; array it is cleared.
; Entry: a1 = descriptor, a0 = removed block, d0 = its size.
;------------------------------------------------------------------------------
fix_array_descriptor:
	movea.l	a1,a2                           ; descriptor
	addq.l	#6,a1                           ; next descriptor
	cmpa.l	(a2),a0                         ; below the removed block: leave it
	bhi.s	fix_array_descriptors
	bne.s	.move_down                      ; the removed array itself
	clr.w	4(a2)                           ; no longer dimensioned
.move_down:
	sub.l	d0,(a2)                         ; moves down

;------------------------------------------------------------------------------
; Runs fix_array_descriptor on d4 descriptors in a row. The loop after it (unused) does the same through a list of
; descriptor pointers.
; Entry: a1 = first descriptor, d4 = count.
;------------------------------------------------------------------------------
fix_array_descriptors:
	dbra	d4,fix_array_descriptor         ; next descriptor
	rts
.next_pointer:
	movea.l	(a1)+,a2                        ; descriptor
	cmpa.l	(a2),a0                         ; below the removed block?
	bhi.s	.next                           ; yes: leave it
	bne.s	.move_down                      ; not the removed array
	clr.w	4(a2)                           ; no longer dimensioned
.move_down:
	sub.l	d0,(a2)                         ; moves down
.next:
	dbra	d4,.next_pointer                ; next pointer
	rts

