m_sound:
	dc.w	$0000                           ; voice 1: octave, note

;------------------------------------------------------------------------------
; Per-voice records of 12 bytes: octave, note, then a Dosound list: period high (register 1/3/5),
; period low (0/2/4), volume (8/9/10), mixer (7: $fe/$fd/$fb) and the end. All kept as data; some words
; disassemble as instructions.
;------------------------------------------------------------------------------
sound_voice1_list:
	btst	d0,d0                           ; register 1 (period high), value
	dc.w	$0000                           ; register 0 (period low), value
sound_voice1_volume_pair:
	dc.b	$08                             ; register 8 (volume)
sound_voice1_volume:
	dc.b	$00,$07,$fe,$ff,$00,$00,$00     ; voice 1 volume; mixer $fe; end; voice 2: octave, note

sound_voice2_list:
	btst	d1,d0                           ; register 3, value
	dc.w	$0200                           ; register 2, value

sound_voice2_volume_pair:
	btst	d4,d0                           ; register 9 (volume), value
	dc.w	$07fd,$ff00,$0000               ; mixer $fd, end; voice 3: octave, note

sound_voice3_list:
	btst	d2,d0                           ; register 5, value
	dc.w	$0400                           ; register 4, value
sound_voice3_volume_pair:
	dc.w	$0a00,$07fb,$ff00               ; register 10 (volume), mixer $fb, end

; Combined Dosound list built by SOUND0: the period and volume pairs of the three voices, followed by
; the WAVE list.
sound_all_voices_list:
	dc.w	$0000,$0000,$0000,$0000,$0000,$0000,$0000,$0000 ; room for the three voices' pairs
	dc.w	$0000

; WAVE list: noise period (6), mixer (7), envelope shape (13), envelope period (12, 11), end.
sound_wave_list:
	dc.w	$0600,$07ff                     ; register 6 (noise period), mixer (7)

sound_envelope_shape_pair:
	btst	d6,d0                           ; register 13 (envelope shape), value
	dc.w	$0c00                           ; register 12 (envelope period high), value
	btst	d5,d0                           ; register 11, value
	dc.w	$ff00                           ; end of the list

;------------------------------------------------------------------------------
; Dosound record of a voice (0 and 1 give voice 1).
; Entry: d1 = voice
; Exit: a0 = its Dosound list (octave and note at -2 and -1)
;------------------------------------------------------------------------------
sound_voice_record:
	andi.w	#$3,d1                          ; voices 1-3
	beq.s	.voice_offset                   ; 0: voice 1
	subq.w	#1,d1
.voice_offset:
	mulu.w	#$c,d1                          ; 12 bytes a voice
	lea	sound_voice1_list(pc,d1.w),a0   ; the voice's list
	rts

;------------------------------------------------------------------------------
; SOUND v,vol: sets the volume of a voice and plays its list.
; Entry: d1 = voice, d0 = volume
;------------------------------------------------------------------------------
SOUND2:
	bsr.s	sound_voice_record              ; voice record
	move.b	d0,5(a0)                        ; volume
	bra.s	sound_play_list                 ; play

;------------------------------------------------------------------------------
; SOUND v: plays the voice's list again.
; Entry: d0 = voice
;------------------------------------------------------------------------------
SOUND1:
	move.l	d0,d1                           ; voice
	bsr.s	sound_voice_record              ; voice record
	bra.s	sound_play_list                 ; play

;------------------------------------------------------------------------------
; SOUND v,vol,note: sets volume and note, keeping the octave.
; Entry: d1 = voice, d2 = volume, d0 = note
;------------------------------------------------------------------------------
SOUND3:
	bsr.s	sound_voice_record              ; voice record
	move.b	d2,5(a0)                        ; volume
	move.b	d0,-$1(a0)                      ; note
	move.b	-$2(a0),d0                      ; octave kept
	bra.s	sound_set_note

;------------------------------------------------------------------------------
; SOUND v,vol,note,octave.
; Entry: d1 = voice, d2 = volume, d3 = note, d0 = octave
;------------------------------------------------------------------------------
SOUND4:
	bsr.s	sound_voice_record              ; voice record
	move.b	d2,5(a0)                        ; volume
	move.b	d3,-$1(a0)                      ; note

;------------------------------------------------------------------------------
; Tone period of the note: the octave-0 period from the table shifted right by the octave, rounded.
; Entry: a0 = voice list, d0 = octave, -1(a0) = note
;------------------------------------------------------------------------------
sound_set_note:
	move.b	-$1(a0),d1                      ; note
	move.b	d0,-$2(a0)                      ; octave
	ext.w	d1
	add.w	d1,d1                           ; * 2
	lea	sound_note_periods(pc),a1       ; periods
	move.w	0(a1,d1.w),d1                   ; octave-0 period
	lsr.w	d0,d1                           ; shifted by the octave
	move.w	d1,d0
	bcc.s	sound_set_period                ; no bit lost
	addq.w	#1,d0                           ; round
	bra.s	sound_set_period

;------------------------------------------------------------------------------
; SOUND v,vol,#period: volume and tone period given directly.
; Entry: d1 = voice, d2 = volume, d0 = period
;------------------------------------------------------------------------------
SOUNDP:
	bsr.s	sound_voice_record              ; voice record
	move.b	d2,5(a0)                        ; volume

;------------------------------------------------------------------------------
; Stores the tone period in the voice's list.
;------------------------------------------------------------------------------
sound_set_period:
	movep.w	d0,1(a0)                        ; period high and low

;------------------------------------------------------------------------------
; Plays a Dosound list.
; Entry: a0 = list
;------------------------------------------------------------------------------
sound_play_list:
	pea	(a0)                            ; list
	move.w	#$20,-(sp)                      ; Dosound
	trap	#14                             ; Dosound
	addq.l	#6,sp                           ; drop the arguments
	rts

; Octave-0 tone periods of the notes (data; parts disassemble as instructions).
sound_note_periods:
	dc.w	$1fa4,$1ddc,$1c30               ; note periods, not code
	move.b	(a2)+,(a5)
	move.b	(a4)+,-(a4)
	dc.w	$17b4,$165e
	move.b	(a6)+,-(a2)
	move.b	$12d0(a6),$11c210c2
	bset	d7,(a2)
	dc.w	$0eee,$0e18
	movep.l	$c8e(a5),d6
	bset	d5,(a2)+
	btst	d5,$a8f(sp)
	dc.w	$09f7
	bchg	d4,$8e1(a0)
	dc.w	$0861
	bset	d3,$777(a1)

;------------------------------------------------------------------------------
; WAVE voc: sets the mixer (bits 0-5: tones and noise, inverted here) and the noise period (bits 8-12),
; then plays all voices.
; Entry: d0 = voc
;------------------------------------------------------------------------------
WAVE1:
	not.b	d0                              ; mixer bits are active low
	lea	sound_wave_list(pc),a0          ; WAVE list
	movep.w	d0,1(a0)                        ; noise period and mixer
	bra.s	SOUND0                          ; play all

;------------------------------------------------------------------------------
; WAVE voc,env,form,dur: also sets the envelope period.
; Entry: d1 = voc, d2 = envelope voices, d3 = form, d0 = period
;------------------------------------------------------------------------------
WAVE4:
	lea	sound_wave_list(pc),a0          ; WAVE list
	movep.w	d0,7(a0)                        ; envelope period high and low
	move.w	d3,d0                           ; form

;------------------------------------------------------------------------------
; WAVE voc,env,form: also sets the envelope shape.
; Entry: d1 = voc, d2 = envelope voices, d0 = form
;------------------------------------------------------------------------------
WAVE3:
	lea	sound_envelope_shape_pair+1(pc),a1 ; envelope shape value
	move.b	d0,(a1)                         ; store it
	move.w	d2,d0                           ; envelope voices

;------------------------------------------------------------------------------
; WAVE voc,env: sets mixer and noise period, and the envelope bit (bit 4) of each voice's volume for
; the voices in env (bits 0-2).
; Entry: d1 = voc, d0 = envelope voices
;------------------------------------------------------------------------------
WAVE2:
	not.b	d1                              ; mixer bits are active low
	lea	sound_wave_list(pc),a0          ; WAVE list
	movep.w	d1,1(a0)                        ; noise period and mixer
	lea	sound_voice1_volume(pc),a0      ; voice 1 volume
	bset	#$4,(a0)                        ; envelope on for voice 1
	bset	#$4,$c(a0)                      ; voice 2
	bset	#$4,$18(a0)                     ; voice 3
	btst	#$0,d0                          ; voice 1 on the envelope?
	bne.s	.check_voice2                   ; yes
	bclr	#$4,(a0)                        ; no: off
.check_voice2:
	btst	#$1,d0                          ; voice 2?
	bne.s	.check_voice3                   ; yes
	bclr	#$4,$c(a0)                      ; no: off
.check_voice3:
	btst	#$2,d0                          ; voice 3?
	bne.s	SOUND0                          ; yes
	bclr	#$4,$18(a0)                     ; no: off

;------------------------------------------------------------------------------
; SOUND0 (used by WAVE): builds the combined list from the three voices and plays it.
;------------------------------------------------------------------------------
SOUND0:
	lea	sound_all_voices_list(pc),a0    ; combined list
	movea.l	a0,a1
	move.l	sound_voice1_list(pc),(a1)+     ; voice 1 period pairs
	move.w	sound_voice1_volume_pair(pc),(a1)+ ; voice 1 volume pair
	move.l	sound_voice2_list(pc),(a1)+     ; voice 2 period pairs
	move.w	sound_voice2_volume_pair(pc),(a1)+ ; voice 2 volume pair
	move.l	sound_voice3_list(pc),(a1)+     ; voice 3 period pairs
	move.w	sound_voice3_volume_pair(pc),(a1)+ ; voice 3 volume pair
	bra.w	sound_play_list                 ; WAVE list follows: play

