;------------------------------------------------------------------------------
; FULLW n: opens GFA window n (1-4) over the whole desktop by placing the common corner point of the
; four windows at the desktop corner opposite to window n's quadrant and opening it with OPENW n,x,y.
; Entry: d0 = window number
; Exit: through OPENWXY; nothing for window 0 or below
; Changes d0-d4
;------------------------------------------------------------------------------
FULLW:
	move.w	d0,-(sp)                        ; keep the window number
	subq.w	#1,d0                           ; window 1-4 as 0-3
	move.w	d0,d4                           ; d4 = quadrant
	bmi.s	fullw_invalid                   ; window 0 or below: nothing to do
	movem.w	$1250(a6),d0-d3                 ; desktop work area x, y, w, h
	btst	#$0,d4                          ; windows 2 and 4 are right of the point ...
	bne.s	.x_done                         ; ... so x stays at the left edge
	add.w	d2,d0                           ; windows 1 and 3: point at the right edge
.x_done:
	btst	#$1,d4                          ; windows 3 and 4 are below the point ...
	bne.s	.y_done                         ; ... so y stays at the top edge
	add.w	d3,d1                           ; windows 1 and 2: point at the bottom edge
.y_done:
	move.w	d0,d2                           ; d2 = x of the corner point
	move.w	d1,d0                           ; d0 = y of the corner point
	move.w	(sp)+,d1                        ; d1 = window number

