	dc.w	$6000,$0000                     ; bra.w fullw_open_at_point+2 -> OPENWXY (filled in by the linker),
                                                ;   OPENW n,x,y

fullw_invalid:
	addq.l	#2,sp                           ; drop the saved window number
	rts

;------------------------------------------------------------------------------
; FULLW n (other form): copies the desktop work area into window n's table entry and opens the
; window with OPENW.
; Entry: d0 = window number
; Exit: through OPENW; nothing for window 0 or below
; Changes d1, d2, a0
;------------------------------------------------------------------------------
