	move.w	d0,d1                           ; d1 = window number
	subq.l	#1,d1                           ; window 1-4 as 0-3
	bmi.s	fullw_desktop_invalid           ; window 0 or below: nothing to do
	andi.w	#$3,d1                          ; only the four GFA windows
	moveq	#12,d2                          ; 12 bytes per window table entry
	mulu.w	d1,d2                           ; offset of window n's entry
	lea	$1220(a6),a0                    ; window table entries
	adda.w	d2,a0                           ; a0 -> window n's entry
	move.l	$1250(a6),(a0)+                 ; x and y of the desktop work area ...
	move.l	$1254(a6),(a0)+                 ; ... and its width and height

