	moveq	#0,d0                           ; Iorec device 0: RS232

inpaux_read_buffer:
	move.w	d0,-(sp)                        ; device
	move.w	#$e,-(sp)                       ; Iorec
	trap	#14                             ; Iorec
	addq.l	#4,sp                           ; drop the arguments
