	movem.l	(sp)+,d0-d2/a2-a3               ; a2 -> IOREC size word, a3 = buffer, old a3 left on the stack
.copy_loop:
	addq.w	#1,d1                           ; next head position
	cmp.w	d0,d1                           ; past the end of the buffer?
	bcs.s	.copy_byte                      ; no
	moveq	#0,d1                           ; yes: wrap to the start
.copy_byte:
	move.b	0(a3,d1.w),(a1)+                ; copy a byte into the string
	cmp.w	d2,d1                           ; up to the tail
	bne.s	.copy_loop
	move.w	d1,2(a2)                        ; new head: buffer now empty
	movea.l	(sp)+,a3                        ; restore a3
