	muls.w	#$3,d5                          ; 3 * (x2 - x1)
	sub.l	d3,d5                           ; b = 3*(x2-x1) - c
	sub.w	d1,d7                           ; x3 - x0
	ext.l	d7                              ; x3 - x0 as a long
	sub.l	d3,d7                           ; - c
	sub.l	d5,d7                           ; a = x3 - x0 - c - b
	sub.w	d4,d6                           ; y2 - y1
	sub.w	d2,d4                           ; y1 - y0
	muls.w	#$3,d4                          ; c = 3 * (y1 - y0)
	muls.w	#$3,d6                          ; 3 * (y2 - y1)
