	move.w	a1,d2                           ; ... + a * (step+1)
.x_a_loop:
	add.l	d7,d1                           ; add a
	dbra	d2,.x_a_loop                    ; step + 1 times
	move.w	a1,d2                           ; then times (step+1) ...
	movea.l	d1,a0                           ; by repeated adding
