	bra.s	ksingle_store

ksingle_zero:
	moveq	#0,d0                           ; too small: store zero
	bra.s	ksingle_store

;------------------------------------------------------------------------------
; Converts a positive float to an IEEE single and stores it.
; Entry: a0 = address, d0.l = mantissa, d2 = exponent
; Exit: d0.l stored at a0
