	move.b	d2,d0                           ; exponent into the low byte
	ror.l	#8,d0                           ; exponent to the top byte, mantissa below
	lsr.l	#1,d0                           ; sign bit position clear

ksingle_store:
	move.l	d0,(a0)                         ; store the single
	rts

